def test_upper_bound(run, x):
    lines = x.strip().split('\n')
    n, m = map(int, lines[0].split())
    out = run(x).strip()
    try:
        ans = float(out)
    except ValueError:
        raise AssertionError('Output must be a number')
    eps = 1e-6
    for i in range(1, n+1):
        a, b = map(int, lines[i].split())
        cost = a * m / b
        if not (ans <= cost + eps and (abs(ans - cost) <= eps or (abs(ans - cost) / max(1, abs(cost))) <= eps)):
            # violation: cost is strictly less than ans beyond tolerance
            if cost < ans - eps:
                raise AssertionError(f'Answer {ans} exceeds supermarket cost {cost}')


def test_achievable(run, x):
    lines = x.strip().split('\n')
