def test_symmetry(run, x):
    import subprocess, sys
    N, K = map(int, x.split())
    # Build symmetric input (N, -K)
    symmetric_input = f"{N} {-K}\n"
    out1 = run(x).strip()
    out2 = run(symmetric_input).strip()
    # Both must be integers (handled by later test), compare as ints
    assert int(out1) == int(out2), f"Symmetry broken: ({N},{K}) gave {out1}, ({N},{-K}) gave {out2}"


def test_monotonicity_N(run, x):
    N, K = map(int, x.split())
    if N < 100000:
        larger_input = f"{N+1} {K}\n"
        out_small = int(run(x).strip())
        out_large = int(run(larger_input).strip())
        assert out_small <= out_large, f"Monotonicity in N broken: count at N={N} is {out_small}, at N={N+1} is {out_large}"


def test_upper_bound_N3(run, x):
    N, K = map(int, x.split())
    ans = int(run(x).strip())
    # Upper bound derived from convolution: answer ≤ N³
    assert ans <= N**3, f"Answer {ans} exceeds N³ = {N**3}"


def test_lower_bound_K0(run, x):
    N, K = map(int, x.split())
    if K == 0:
        ans = int(run(x).strip())
        # At least N² quadruples with a=c, b=d
        assert ans >= N**2, f"For K=0, answer {ans} < N² = {N**2}"


def test_min_at_max_K(run, x):
    N, K = map(int, x.split())
    maxK = 2 * (N - 1)
    if abs(K) == maxK:
        ans = int(run(x).strip())
        assert ans >= 1, f"For |K| = maxK = {maxK}, answer {ans} < 1"


def test_N1(run, x):
    N, K = map(int, x.split())
    if N == 1:
        ans = int(run(x).strip())
        # Only possible quadruple is (1,1,1,1) giving K=0, answer must be 1
        assert ans == 1, f"For N=1, answer must be 1, got {ans}"


def test_non_negative(run, x):
    ans = int(run(x).strip())
    assert ans >= 0, f"Answer {ans} is negative"


def test_integer(run, x):
    out = run(x).strip()
    # Must parse as integer, no extra whitespace or non‑digits
    int(out)  # Raises ValueError if not integer


def test_small_N_brute_force(run, x):
    N, K = map(int, x.split())
    if N <= 30:
        # Enumerate all quadruples
        count = 0
        for a in range(1, N+1):
            for b in range(1, N+1):
                for c in range(1, N+1):
                    for d in range(1, N+1):
                        if a + b - c - d == K:
                            count += 1
        ans = int(run(x).strip())
        assert ans == count, f"Brute force mismatch: got {ans}, expected {count}"


def test_small_N_monotonicity_in_K(run, x):
    N, K = map(int, x.split())
    if N <= 10:
        # For each K' from 0 to 2(N-1), check symmetry and monotonicity
        max_absK = 2 * (N - 1)
        prev = None
        for Kp in range(0, max_absK + 1):
            out_pos = int(run(f"{N} {Kp}\n").strip())
            out_neg = int(run(f"{N} {-Kp}\n").strip())
            assert out_pos == out_neg, f"Symmetry broken for K'={Kp}"
            if prev is not None:
                # Non‑increasing in |K| (since Kp increases)
                assert out_pos <= prev, f"Monotonicity broken: answer for |K|={Kp} is {out_pos}, previous {prev}"
            prev = out_pos

