def test_certificate(run, x):
    # Parse input
    lines = x.strip().split('\n')
    n = int(lines[0])
    input_pairs = []
    for line in lines[1:1 + n]:
        a, b = map(int, line.split())
        input_pairs.append((a, b))
    # Get output
    out_str = run(x)
    out_vals = list(map(int, out_str.split()))
    if len(out_vals) != n:
        return  # length mismatch caught elsewhere
    # Reconstruct pairs from output
    reconstructed = []
    for i, val in enumerate(out_vals):
        front = out_vals[i - 1] if i > 0 else 0
        back = out_vals[i + 1] if i < n - 1 else 0
        reconstructed.append((front, back))
    # Compare multisets (order doesn't matter)
    from collections import Counter
    if Counter(input_pairs) != Counter(reconstructed):
        assert False, "reconstructed pairs do not match input pairs"

def test_swap_reverse(run, x):
    lines = x.strip().split('\n')
    n = int(lines[0])
    swapped_lines = [lines[0]]
    for line in lines[1:1 + n]:
        a, b = map(int, line.split())
        swapped_lines.append(f"{b} {a}")
    swapped_input = '\n'.join(swapped_lines)
    out1_str = run(x)
    out1 = list(map(int, out1_str.split()))
    out2_str = run(swapped_input)
    out2 = list(map(int, out2_str.split()))
    if out1[::-1] != out2:
        assert False, "swapped input did not produce reversed output"

def test_reorder_invariant(run, x):
    lines = x.strip().split('\n')
    n = int(lines[0])
    pairs = []
    for line in lines[1:1 + n]:
        a, b = map(int, line.split())
        pairs.append((a, b))
    pairs.sort()
    sorted_input = str(n) + '\n' + '\n'.join(f"{a} {b}" for a, b in pairs)
    out_original_str = run(x)
    out_sorted_str = run(sorted_input)
    if out_original_str != out_sorted_str:
        assert False, "reordering input changed output"

def test_length(run, x):
    n = int(x.strip().split('\n')[0])
    out_str = run(x)
    out_vals = list(map(int, out_str.split()))
    if len(out_vals) != n:
        assert False, f"output length {len(out_vals)} != n {n}"

def test_distinct(run, x):
    out_str = run(x)
    out_vals = list(map(int, out_str.split()))
    if len(set(out_vals)) != len(out_vals):
        assert False, "output contains duplicate IDs"

def test_positive(run, x):
    out_str = run(x)
    out_vals = list(map(int, out_str.split()))
    if any(v <= 0 for v in out_vals):
        assert False, f"output contains non‑positive ID {[v for v in out_vals if v <= 0][0]}"

def test_id_set(run, x):
    lines = x.strip().split('\n')
    n = int(lines[0])
    input_numbers = set()
    for line in lines[1:1 + n]:
        a, b = map(int, line.split())
        if a != 0:
            input_numbers.add(a)
        if b != 0:
            input_numbers.add(b)
    out_str = run(x)
    out_vals = set(map(int, out_str.split()))
    if out_vals != input_numbers:
        assert False, f"output IDs {out_vals} do not match input non‑zero IDs {input_numbers}"

def test_order_constraint(run, x):
    lines = x.strip().split('\n')
    n = int(lines[0])
    pairs = []
    for line in lines[1:1 + n]:
        a, b = map(int, line.split())
        if a != 0 and b != 0:
            pairs.append((a, b))
    out_str = run(x)
    out_vals = list(map(int, out_str.split()))
    pos = {val: i for i, val in enumerate(out_vals)}
    for a, b in pairs:
        if pos[a] >= pos[b]:
            assert False, f"pair ({a},{b}) order violated"

def test_front_appearance(run, x):
    lines = x.strip().split('\n')
    n = int(lines[0])
    front_set = set()
    for line in lines[1:1 + n]:
        a, b = map(int, line.split())
        if a != 0:
            front_set.add(a)
    out_str = run(x)
    out_vals = list(map(int, out_str.split()))
    # every element except the last must appear as a front neighbor
    for v in out_vals[:-1]:
        if v not in front_set:
            assert False, f"ID {v} (non‑last) never appears as front neighbor"

def test_back_appearance(run, x):
    lines = x.strip().split('\n')
    n = int(lines[0])
    back_set = set()
    for line in lines[1:1 + n]:
        a, b = map(int, line.split())
        if b != 0:
            back_set.add(b)
    out_str = run(x)
    out_vals = list(map(int, out_str.split()))
    # every element except the first must appear as a back neighbor
    for v in out_vals[1:]:
        if v not in back_set:
            assert False, f"ID {v} (non‑first) never appears as back neighbor"

