tests_src:
def test_output_line_count(run, x):
    n = int(x.strip().split('\n')[0])
    output = run(x)
    lines = output.rstrip('\n').split('\n')
    assert len(lines) == n

def test_output_strings_valid(run, x):
    output = run(x)
    for line in output.rstrip('\n').split('\n'):
        assert line in ["Freda's", "Rainbow's", "OMG>.< I don't know!"]

def test_freda_sufficient(run, x):
    lines = x.rstrip('\n').split('\n')[1:]
    output_lines = run(x).rstrip('\n').split('\n')
    for s, out in zip(lines, output_lines):
        if s.endswith('lala.') and not s.startswith('miao.'):
            assert out == "Freda's"

def test_rainbow_sufficient(run, x):
    lines = x.rstrip('\n').split('\n')[1:]
    output_lines = run(x).rstrip('\n').split('\n')
    for s, out in zip(lines, output_lines):
        if s.startswith('miao.') and not s.endswith('lala.'):
            assert out == "Rainbow's"

def test_both_conditions_omg(run, x):
    lines = x.rstrip('\n').split('\n')[1:]
    output_lines = run(x).rstrip('\n').split('\n')
    for s, out in zip(lines, output_lines):
        if s.startswith('miao.') and s.endswith('lala.'):
            assert out == "OMG>.< I don't know!"

def test_neither_condition_omg(run, x):
    lines = x.rstrip('\n').split('\n')[1:]
    output_lines = run(x).rstrip('\n').split('\n')
    for s, out in zip(lines, output_lines):
        if not s.startswith('miao.') and not s.endswith('lala.'):
            assert out == "OMG>.< I don't know!"

def test_freda_necessary(run, x):
    lines = x.rstrip('\n').split('\n')[1:]
    output_lines = run(x).rstrip('\n').split('\n')
    for s, out in zip(lines, output_lines):
        if out == "Freda's":
            assert s.endswith('lala.') and not s.startswith('miao.')

def test_rainbow_necessary(run, x):
    lines = x.rstrip('\n').split('\n')[1:]
    output_lines = run(x).rstrip('\n').split('\n')
    for s, out in zip(lines, output_lines):
        if out == "Rainbow's":
            assert s.startswith('miao.') and not s.endswith('lala.')

def test_duplication(run, x):
    lines = x.rstrip('\n').split('\n')
    n = int(lines[0])
    sentences = lines[1:]
    new_n = 2 * n
    new_input = str(new_n) + '\n' + '\n'.join(sentences + sentences)
    original_output = run(x).rstrip('\n').split('\n')
    new_output = run(new_input).rstrip('\n').split('\n')
    expected = original_output + original_output
    assert new_output == expected

def test_reversal(run, x):
    lines = x.rstrip('\n').split('\n')
    n = int(lines[0])
    sentences = lines[1:]
    reversed_sentences = list(reversed(sentences))
    reversed_input = str(n) + '\n' + '\n'.join(reversed_sentences)
    original_output = run(x).rstrip('\n').split('\n')
    reversed_output = run(reversed_input).rstrip('\n').split('\n')
    assert reversed_output == list(reversed(original_output))

