def test_length(run, x):
    lines = x.strip().split('\n')
    n = int(lines[0])
    output = run(x).strip()
    if output == '':
        nums = []
    else:
        nums = list(map(int, output.split()))
    assert len(nums) == n, f'Expected {n} numbers, got {len(nums)}'

def test_ids_set(run, x):
    lines = x.strip().split('\n')[1:]
    ids_from_input = set()
    for line in lines:
        a, b = map(int, line.split())
        if a > 0:
            ids_from_input.add(a)
        if b > 0:
            ids_from_input.add(b)
    output = run(x).strip()
    if output == '':
        output_ids = set()
    else:
        output_ids = set(map(int, output.split()))
    assert output_ids == ids_from_input, f'Output set {output_ids} != input set {ids_from_input}'

def test_bounds(run, x):
    output = run(x).strip()
    if output == '':
        return
    for v in map(int, output.split()):
        assert 1 <= v <= 10**6, f'ID {v} out of bounds'

def test_neighbor_consistency(run, x):
    lines = x.strip().split('\n')[1:]
    front_to_back = {}
    back_to_front = {}
    for line in lines:
        a, b = map(int, line.split())
        if a != 0:
            front_to_back[a] = b
        if b != 0:
            back_to_front[b] = a
    output = run(x).strip()
    if output == '':
        nums = []
    else:
        nums = list(map(int, output.split()))
    for i in range(len(nums)-1):
        x, y = nums[i], nums[i+1]
        assert front_to_back.get(x) == y, f'front_to_back[{x}] != {y}'
        assert back_to_front.get(y) == x, f'back_to_front[{y}] != {x}'

