def test_shape(run, x):
    out = run(x)
    lines = out.strip('\n').split('\n')
    n, m, _ = map(int, x.split('\n')[0].split())
    assert len(lines) == n, f'Expected {n} lines, got {len(lines)}'
    for i, line in enumerate(lines):
        parts = line.split()
        assert len(parts) == m, f'Line {i+1}: expected {m} integers, got {len(parts)}'


def test_bounds(run, x):
    out = run(x)
    lines = out.strip('\n').split('\n')
    for line in lines:
        for num_str in line.split():
            val = int(num_str)
            assert 0 <= val <= 10**9, f'Value {val} out of bounds [0, 10^9]'


def test_certificate(run, x):
    out = run(x)
    lines = out.strip('\n').split('\n')
    n, m, k = map(int, x.split('\n')[0].split())
    ops = [line.strip().split() for line in x.strip('\n').split('\n')[1:]]
    last_row = [-1, 0] * (n + 1)  # [index, color]
    last_col = [-1, 0] * (m + 1)
    for idx, op in enumerate(ops):
        t, pos, color = map(int, op)
        if t == 1:
            last_row[pos] = [idx, color]
        else:
            last_col[pos] = [idx, color]
    for i in range(n):
        row_vals = list(map(int, lines[i].split()))
        for j in range(m):
            r_idx, r_col = last_row[i+1]
            c_idx, c_col = last_col[j+1]
            expected = r_col if r_idx > c_idx else c_col
            assert row_vals[j] == expected, f'Cell ({i+1},{j+1}) expected {expected}, got {row_vals[j]}'


def test_redundant_operations_removal(run, x):
    out = run(x)
    n, m, k = map(int, x.split('\n')[0].split())
    ops = [line.strip().split() for line in x.strip('\n').split('\n')[1:]]
    last_row = [-1, 0] * (n + 1)
    last_col = [-1, 0] * (m + 1)
    for idx, op in enumerate(ops):
        t, pos, color = map(int, op)
        if t == 1:
            last_row[pos] = [idx, color]
        else:
            last_col[pos] = [idx, color]
    reduced_ops = []
    for idx, op in enumerate(ops):
        t, pos, color = map(int, op)
        if t == 1 and last_row[pos][0] == idx:
            reduced_ops.append(op)
        if t == 2 and last_col[pos][0] == idx:
            reduced_ops.append(op)
    # keep original order
    reduced_input = f'{n} {m} {len(reduced_ops)}\n' + '\n'.join(' '.join(map(str, op)) for op in reduced_ops)
    reduced_out = run(reduced_input)
    assert out == reduced_out, 'Output differs after removing redundant operations'


def test_no_operations(run, x):
    n, m, k = map(int, x.split('\n')[0].split())
    if k == 0:
        out = run(x)
        lines = out.strip('\n').split('\n')
        for line in lines:
            for num_str in line.split():
                assert int(num_str) == 0, f'Non-zero cell when k=0'


def test_single_operation(run, x):
    n, m, k = map(int, x.split('\n')[0].split())
    if k == 1:
        out = run(x)
        lines = out.strip('\n').split('\n')
        op = x.strip('\n').split('\n')[1].split()
        t, pos, color = map(int, op)
        for i in range(n):
            row_vals = list(map(int, lines[i].split()))
            for j in range(m):
                expected = 0
                if t == 1 and i+1 == pos:
                    expected = color
                if t == 2 and j+1 == pos:
                    expected = color
                assert row_vals[j] == expected, f'Cell ({i+1},{j+1}) mismatch for single operation'


def test_all_row_operations(run, x):
    ops = [line.strip().split() for line in x.strip('\n').split('\n')[1:]]
    if not ops:
        return
    if all(op[0] == '1' for op in ops):
        out = run(x)
        lines = out.strip('\n').split('\n')
        n, m, _ = map(int, x.split('\n')[0].split())
        last_row_color = [0] * (n + 1)
        for op in ops:
            t, pos, color = map(int, op)
            last_row_color[pos] = color
        for i in range(n):
            row_vals = list(map(int, lines[i].split()))
            expected = last_row_color[i+1]
            for val in row_vals:
                assert val == expected, f'Row {i+1} not uniform with color {expected}'


def test_all_column_operations(run, x):
    ops = [line.strip().split() for line in x.strip('\n').split('\n')[1:]]
    if not ops:
        return
    if all(op[0] == '2' for op in ops):
        out = run(x)
        lines = out.strip('\n').split('\n')
        n, m, _ = map(int, x.split('\n')[0].split())
        last_col_color = [0] * (m + 1)
        for op in ops:
            t, pos, color = map(int, op)
            last_col_color[pos] = color
        for j in range(m):
            expected = last_col_color[j+1]
            for i in range(n):
                row_vals = list(map(int, lines[i].split()))
                assert row_vals[j] == expected, f'Column {j+1} not uniform with color {expected}'


def test_duplicate_input(run, x):
    n, m, k = map(int, x.split('\n')[0].split())
    if 2 * k <= 100000 and n * m <= 100000:
        doubled_input = f'{n} {m} {2*k}\n' + x.strip('\n').split('\n', 1)[1] + '\n' + x.strip('\n').split('\n', 1)[1]
        out1 = run(x)
        out2 = run(doubled_input)
        assert out1 == out2, 'Output changed after duplicating operations'


def test_transpose(run, x):
    n, m, k = map(int, x.split('\n')[0].split())
    ops = [line.strip().split() for line in x.strip('\n').split('\n')[1:]]
    transposed_ops = []
    for op in ops:
        t, pos, color = map(int, op)
        new_t = 2 if t == 1 else 1
        transposed_ops.append(f'{new_t} {pos} {color}')
    transposed_input = f'{m} {n} {k}\n' + '\n'.join(transposed_ops)
    out_orig = run(x)
    out_trans = run(transposed_input)
    # transpose the original output
    orig_lines = out_orig.strip('\n').split('\n')
    orig_matrix = [list(map(int, line.split())) for line in orig_lines]
    transposed_matrix = [[orig_matrix[i][j] for i in range(n)] for j in range(m)]
    expected_lines = [' '.join(map(str, row)) for row in transposed_matrix]
    expected_out = '\n'.join(expected_lines) + ('\n' if out_orig.endswith('\n') else '')
    assert out_trans == expected_out, 'Transposed output mismatch'

