def test_longest_chain_lower_bound(run, x):
    output = run(x).rstrip('\n')
    lines = output.split('\n')
    if lines[0] != 'Yes':
        return
    n, m = map(int, x.split('\n')[0].split())
    rows = x.strip().split('\n')[1:1+n]
    # Build equality DSU
    parent = list(range(n + m))
    def find(u):
        while parent[u] != u:
            parent[u] = parent[parent[u]]
            u = parent[u]
        return u
    def union(u, v):
        pu, pv = find(u), find(v)
        if pu != pv:
            parent[pu] = pv
    for i in range(n):
        row = rows[i]
        for j in range(m):
            if row[j] == '=':
                union(i, n + j)
    # Map each original dish to its component representative
    comp = [find(i) for i in range(n + m)]
    comp_ids = {c: idx for idx, c in enumerate(sorted(set(comp)))}
    k = len(comp_ids)
    # Build directed graph on components, ignoring equalities and same-component edges
    from collections import defaultdict
    adj = defaultdict(list)
    indeg = [0] * k
    for i in range(n):
        row = rows[i]
        for j in range(m):
            ci = comp_ids[comp[i]]
            cj = comp_ids[comp[n + j]]
            if ci == cj:
                continue
            if row[j] == '<':
                adj[ci].append(cj)
            elif row[j] == '>':
                adj[cj].append(ci)
    # Remove duplicate edges
    for u in adj:
        adj[u] = list(set(adj[u]))
        for v in adj[u]:
            indeg[v] += 1
    # Topological order longest path (graph may have cycles? but if output is Yes, the graph must be acyclic)
    # Compute longest chain length via DP on DAG
    from collections import deque
    q = deque([u for u in range(k) if indeg[u] == 0])
    dist = [0] * k
    while q:
        u = q.popleft()
        for v in adj[u]:
            indeg[v] -= 1
            if indeg[v] == 0:
                q.append(v)
            dist[v] = max(dist[v], dist[u] + 1)
    # If there is a cycle, indeg won't go to zero for all nodes, but we can still compute the maximum dist
    # The longest chain length is max(dist)+1 (since dist counts edges)
    longest = max(dist) + 1 if k > 0 else 0
    # Get maximum assigned value
    first_vals = list(map(int, lines[1].split()))
    second_vals = list(map(int, lines[2].split()))
    max_val = max(first_vals + second_vals)
    assert max_val >= longest, f"Max assigned value {max_val} is smaller than longest chain length {longest}."


def test_cycle_implies_no(run, x):
    # This test only asserts that if the constraint graph has a cycle, output must be 'No'.
    # It does NOT assert the converse (if no cycle then output must be Yes).
    n, m = map(int, x.split('\n')[0].split())
    rows = x.strip().split('\n')[1:1+n]
    # Build equality DSU
    parent = list(range(n + m))
    def find(u):
        while parent[u] != u:
            parent[u] = parent[parent[u]]
            u = parent[u]
        return u
    def union(u, v):
        pu, pv = find(u), find(v)
        if pu != pv:
            parent[pu] = pv
    for i in range(n):
        row = rows[i]
        for j in range(m):
            if row[j] == '=':
                union(i, n + j)
    comp = [find(i) for i in range(n + m)]
    comp_ids = {c: idx for idx, c in enumerate(sorted(set(comp)))}
    k = len(comp_ids)
    # Build directed graph on components
    from collections import defaultdict
    adj = defaultdict(list)
    for i in range(n):
        row = rows[i]
        for j in range(m):
            ci = comp_ids[comp[i]]
            cj = comp_ids[comp[n + j]]
            if ci == cj:
                continue
            if row[j] == '<':
                adj[ci].append(cj)
            elif row[j] == '>':
                adj[cj].append(ci)
    # Detect cycle with DFS
    visited = [0] * k  # 0 unvisited, 1 visiting, 2 visited
    has_cycle = False
    def dfs(u):
        nonlocal has_cycle
        if has_cycle:
            return
        visited[u] = 1
        for v in adj[u]:
            if visited[v] == 0:
                dfs(v)
            elif visited[v] == 1:
                has_cycle = True
                return
        visited[u] = 2
    for u in range(k):
        if visited[u] == 0:
            dfs(u)
        if has_cycle:
            break
    if has_cycle:
        output = run(x).rstrip('\n')
        lines = output.split('\n')
        assert lines[0] == 'No', f"Constraint graph has a cycle, but output is '{lines[0]}' (should be 'No')."
    # else: no cycle, we make no assertion about output being Yes.

