tests_src:
def test_bounds(run, x):
    n = int(x.strip())
    upper = n * (n + 1) // 2
    out = run(x).strip()
    if not out:
        assert False, "empty output"
    vals = list(map(int, out.split()))
    for v in vals:
        assert 1 <= v <= upper, f"value {v} out of bounds [1, {upper}]"

def test_min(run, x):
    out = run(x).strip()
    if not out:
        assert False, "empty output"
    vals = list(map(int, out.split()))
    assert vals[0] == 1, f"smallest value {vals[0]} is not 1"

def test_max(run, x):
    n = int(x.strip())
    expected_max = n * (n + 1) // 2
    out = run(x).strip()
    if not out:
        assert False, "empty output"
    vals = list(map(int, out.split()))
    assert vals[-1] == expected_max, f"largest value {vals[-1]} != expected {expected_max}"

def test_increasing(run, x):
    out = run(x).strip()
    if not out:
        assert False, "empty output"
    vals = list(map(int, out.split()))
    for i in range(len(vals)-1):
        assert vals[i] < vals[i+1], f"not increasing at position {i}: {vals[i]} >= {vals[i+1]}"

def test_count_divisors(run, x):
    n = int(x.strip())
    # count divisors by trial division up to sqrt(n) - fast enough for n up to 10^9
    cnt = 0
    i = 1
    while i * i <= n:
        if n % i == 0:
            cnt += 1
            if i * i != n:
                cnt += 1
        i += 1
    out = run(x).strip()
    if not out:
        assert False, "empty output"
    vals = list(map(int, out.split()))
    assert len(vals) == cnt, f"length {len(vals)} != number of divisors {cnt}"

def test_certificate(run, x):
    n = int(x.strip())
    out = run(x).strip()
    if not out:
        assert False, "empty output"
    vals = list(map(int, out.split()))
    for s in vals:
        tmp = 2 * s + n
        # (n+2) might be 0? n>=2 so n+2>0
        if tmp % (n + 2) != 0:
            assert False, f"value {s} fails divisibility"
        L = tmp // (n + 2)
        if n % L != 0:
            assert False, f"value {s}: L={L} does not divide n"
        if s != L + n * (L - 1) // 2:
            assert False, f"value {s} does not match formula with L={L}"

def test_distinct(run, x):
    out = run(x).strip()
    if not out:
        assert False, "empty output"
    vals = list(map(int, out.split()))
    assert len(set(vals)) == len(vals), "duplicate values found"

def test_prime(run, x):
    n = int(x.strip())
    # simple primality test up to sqrt(n) - fine for n <= 10^9
    if n < 2:
        return
    i = 2
    while i * i <= n:
        if n % i == 0:
            return  # n is composite, test does not apply
        i += 1
    # n is prime
    out = run(x).strip()
    if not out:
        assert False, "empty output"
    vals = list(map(int, out.split()))
    expected = [1, n * (n + 1) // 2]
    assert vals == expected, f"for prime n={n}, expected {expected}, got {vals}"

def test_square(run, x):
    n = int(x.strip())
    root = int(n ** 0.5)
    if root * root != n:
        return  # not a perfect square, test does not apply
    out = run(x).strip()
    if not out:
        assert False, "empty output"
    vals = list(map(int, out.split()))
    assert len(vals) % 2 == 1, f"for square n={n}, length {len(vals)} is even"

def test_format(run, x):
    out = run(x).strip()
    # check no leading/trailing spaces
    assert out == out.strip(), "leading/trailing spaces"
    if out:
        parts = out.split()
        # check each part is an integer
        for p in parts:
            # valid integer?
            # allow negative? specification says positive, but test_bounds already checks >=1
            int(p)
        # check separated by single spaces
        assert ' '.join(parts) == out, "not single-space separated"
        # non-decreasing order
        vals = list(map(int, parts))
        for i in range(len(vals)-1):
            assert vals[i] <= vals[i+1], f"not non-decreasing at {i}"
    else:
        # empty output is invalid because there is at least one fun value (1)
        assert False, "empty output"

