tests_src:
def test_length(run, x):
    lines = x.rstrip('\n').split('\n')
    if len(lines) < 3:
        return
    s = lines[2]
    output = run(x)
    assert len(output.rstrip('\n')) == len(s), f'Length mismatch: input length {len(s)}, output length {len(output.rstrip('\n'))}'


def test_digits(run, x):
    lines = x.rstrip('\n').split('\n')
    if len(lines) < 3:
        return
    s = lines[2]
    output = run(x).rstrip('\n')
    for i, ch in enumerate(s):
        if ch.isdigit():
            assert i < len(output) and output[i] == ch, f'Digit mismatch at position {i}: input {ch}, output {output[i] if i < len(output) else "out of bounds"}'


def test_case_preservation(run, x):
    lines = x.rstrip('\n').split('\n')
    if len(lines) < 3:
        return
    s = lines[2]
    output = run(x).rstrip('\n')
    for i, ch in enumerate(s):
        if ch.isalpha():
            assert i < len(output) and output[i].isalpha(), f'Non-letter at position {i} where input is letter'
            assert ch.isupper() == output[i].isupper(), f'Case mismatch at position {i}: input {ch}, output {output[i]}'


def test_mapping(run, x):
    lines = x.rstrip('\n').split('\n')
    if len(lines) < 3:
        return
    s1, s2, s = lines[0], lines[1], lines[2]
    output = run(x).rstrip('\n')
    for i, ch in enumerate(s):
        if ch.isalpha():
            L = ch.lower()
            idx = s1.find(L)
            assert idx != -1, f'Letter {L} not found in layout s1'
            expected_lower = s2[idx]
            assert output[i].lower() == expected_lower, f'Mapping mismatch at position {i}: input {ch}, output {output[i]}, expected lowercase {expected_lower}'


def test_identity_layout(run, x):
    lines = x.rstrip('\n').split('\n')
    if len(lines) < 3:
        return
    s1, s2, s = lines[0], lines[1], lines[2]
    if s1 == s2:
        output = run(x).rstrip('\n')
        assert output == s, f'Layouts identical, output must equal input, but got {output} vs {s}'


def test_inversion(run, x):
    lines = x.rstrip('\n').split('\n')
    if len(lines) < 3:
        return
    s1, s2, s = lines[0], lines[1], lines[2]
    output = run(x).rstrip('\n')
    # Build swapped input: s2 as first layout, s1 as second, output as text
    swapped_input = f'{s2}\n{s1}\n{output}\n'
    swapped_output = run(swapped_input).rstrip('\n')
    assert swapped_output == s, f'Double transformation did not return original: {swapped_output} vs {s}'


def test_uppercase_consistency(run, x):
    lines = x.rstrip('\n').split('\n')
    if len(lines) < 3:
        return
    s1, s2, s = lines[0], lines[1], lines[2]
    # Convert s to uppercase, leaving digits unchanged
    s_upper = ''.join(ch.upper() if ch.isalpha() else ch for ch in s)
    upper_input = f'{s1}\n{s2}\n{s_upper}\n'
    upper_output = run(upper_input).rstrip('\n')
    original_output = run(x).rstrip('\n')
    assert upper_output == original_output.upper(), f'Uppercase transformation mismatch: {upper_output} vs {original_output.upper()}'


def test_lowercase_consistency(run, x):
    lines = x.rstrip('\n').split('\n')
    if len(lines) < 3:
        return
    s1, s2, s = lines[0], lines[1], lines[2]
    s_lower = ''.join(ch.lower() if ch.isalpha() else ch for ch in s)
    lower_input = f'{s1}\n{s2}\n{s_lower}\n'
    lower_output = run(lower_input).rstrip('\n')
    original_output = run(x).rstrip('\n')
    assert lower_output == original_output.lower(), f'Lowercase transformation mismatch: {lower_output} vs {original_output.lower()}'


def test_alphanumeric(run, x):
    output = run(x).rstrip('\n')
    for ch in output:
        assert ch.isalnum(), f'Non-alphanumeric character in output: {ch}'


def test_frequency(run, x):
    lines = x.rstrip('\n').split('\n')
    if len(lines) < 3:
        return
    s1, s2, s = lines[0], lines[1], lines[2]
    output = run(x).rstrip('\n')
    from collections import Counter
    s_lower_counts = Counter(ch.lower() for ch in s if ch.isalpha())
    output_lower_counts = Counter(ch.lower() for ch in output if ch.isalpha())
    for x in s1:
        y = s2[s1.index(x)]
        if s_lower_counts.get(x, 0) != output_lower_counts.get(y, 0):
            assert False, f'Frequency mismatch for letter {x}->{y}: input count {s_lower_counts.get(x,0)} vs output count {output_lower_counts.get(y,0)}'

