    },
    {
      "name": "test_swap_UR",
      "intent": "Swapping every 'U' with 'R' and every 'R' with 'U' reflects the path across the wall, leaving the number of crossings unchanged due to symmetry. Run the program on the original input and on the input with all characters swapped, and assert the outputs are equal."
    },
    {
      "name": "test_all_R_zero",
