    {
      "name": "test_output_length",
      "intent": "Assert that the output string has exactly five characters, as the specification requires exactly five digits."
    },
    {
      "name": "test_output_digits",
      "intent": "Assert that every character in the output is a decimal digit ('0' through '9')."
    },
    {
      "name": "test_output_range",
      "intent": "Convert the output to an integer and assert it is between 0 and 99 999 inclusive, because it represents the last five digits of a larger number."
    },
    {
      "name": "test_last_digit_match",
      "intent": "Extract the thousands digit (the second most significant digit) from the input number and assert that the last digit of the output equals that digit. This follows because the shuffled number ends with that digit and raising to the fifth power preserves the last digit modulo 10."
