    },
    {
      "name": "test_mod2_congruence",
      "intent": "Extract the thousands digit from the input, reduce it modulo 2, and assert that the output integer modulo 2 equals that value, because the parity of the shuffled number is determined by its last digit and raising to an odd power preserves parity."
    },
    {
      "name": "test_example_consistency",
      "intent": "If the input is exactly \"12345\", assert the output is \"71232\"; if \"13542\", assert \"84443\"; if \"71232\", assert \"10151\". For any other input, the test passes. This ensures the program matches the examples given in the specification."
    },
    {
      "name": "full_verification",
      "intent": "Compute the shuffled number from the input as per the specification (first, third, fifth, fourth, second digits), raise it to the fifth power, take the last five digits (formatted as a five‑digit string with leading zeros if necessary), and assert that the output string equals that computed string."
    },
    {
      "name": "test_no_whitespace",
      "intent": "Assert that the output string contains no whitespace characters (space, tab, newline, etc.), as the output must be exactly five contiguous digits."
