    },
    {
      "name": "test_last_four_digits",
      "intent": "Assert that the last four digits of the output equal the last four digits of (1000*d3 + 100*d5 + 10*d4 + d2)^5, formatted as four digits with leading zeros. This checks the output modulo 10000."
    },
    {
      "name": "test_mod_4",
      "intent": "Assert that the integer value of the output modulo 4 equals ((10*d4 + d2) % 4)^5 % 4. This checks consistency of the output with the shuffled number modulo 4."
    },
    {
      "name": "test_mod_8",
      "intent": "Assert that the integer value of the output modulo 8 equals ((100*d5 + 10*d4 + d2) % 8)^5 % 8. This checks consistency modulo 8."
    },
    {
      "name": "test_mod_125",
      "intent": "Assert that the integer value of the output modulo 125 equals (x % 125)^5 % 125, where x is the shuffled integer computed from the input digits. This checks consistency modulo 125, a factor of 100000."
