    colors = list(map(int, lines[1].split()))
    edges = [tuple(map(int, line.split())) for line in lines[2:2+n-1]]
    # build adjacency list
    adj = [[] for _ in range(n)]
    for u, v in edges:
        adj[u-1].append(v-1)
        adj[v-1].append(u-1)
    # contract monochromatic components
    comp_id = [-1]*n
    comp_cnt = 0
    for i in range(n):
        if comp_id[i] != -1:
            continue
        stack = [i]
        comp_id[i] = comp_cnt
        while stack:
            v = stack.pop()
            for nb in adj[v]:
                if comp_id[nb] == -1 and colors[nb] == colors[v]:
                    comp_id[nb] = comp_cnt
                    stack.append(nb)
        comp_cnt += 1
    # build adjacency between components
    comp_adj = [[] for _ in range(comp_cnt)]
    for u, v in edges:
        cu, cv = comp_id[u-1], comp_id[v-1]
        if cu != cv:
            comp_adj[cu].append(cv)
            comp_adj[cv].append(cu)
