def test_exhaustive(run, x):
    # Only run on small n to avoid exponential blowup
    lines = x.strip().split('\n')
    n = int(lines[0])
    s = lines[1].strip()
    if n > 15:
        # skip for large n; test would be too slow
        return
    # enumerate assignments
    unknown_pos = [i for i,ch in enumerate(s) if ch == '?']
    best = [0]*n
    for mask in range(1 << len(unknown_pos)):
        t = list(s)
        for idx, pos in enumerate(unknown_pos):
            t[pos] = '0' if (mask >> idx) & 1 else '1'
        assigned = ''.join(t)
        # compute sets for each x
        for xval in range(1, n+1):
            cnt = 0
            streak = 0
            last = None
            for ch in assigned:
                if last is None or ch != last:
                    streak = 1
                else:
                    streak += 1
                if streak == xval:
                    cnt += 1
                    streak = 0
                    last = None  # reset after set ends
                else:
                    last = ch
            best[xval-1] = max(best[xval-1], cnt)
    out = run(x).strip()
    if out:
        vals = list(map(int, out.split()))
        assert len(vals) == n
        for i in range(n):
            assert vals[i] == best[i], f"x={i+1}: expected {best[i]}, got {vals[i]}"
    else:
        assert False, "empty output"


