def test_fully_known(run, x):
    lines = x.strip().split('\n')
    n = int(lines[0])
    s = lines[1].strip()
    if '?' in s:
        return  # not fully known
    out = run(x).strip()
    if out:
        vals = list(map(int, out.split()))
        # compute deterministic answer
        expected = [0]*n
        for xval in range(1, n+1):
            cnt = 0
            streak = 0
            last = None
            for ch in s:
