  ]
}

{
  "rationale": "These 10 property tests combine exhaustive verification, symmetry invariants, bounds, and achievability checks to catch wrong answers. Tests 1 and 2 directly compute the correct answer by brute force for the given string and all strings of the same length, ensuring correctness on the entire input space. Tests 3 and 4 enforce rotational and reflection symmetries of the circle. Tests 5–7 are basic sanity checks: output within [0, n], integer, and zero only if already logical. Tests 8 and 9 provide lower and upper bounds derived from disjoint violations and alternating patterns. Test 10 verifies the output is achievable. All are consequences of the problem statement. If one test were dropped, it would be test 2 (all strings of same length) as it is computationally intensive and partially covered by test 1 and the other properties.",
  "plan": [
    {
      "name": "test_exact_bruteforce",
