def test_bounds(run, x):
    n_m = x.strip().split()
    n = int(n_m[0])
    out = run(x).strip()
    a = int(out)
    assert 1 <= a <= n, f'a={a} out of range [1, {n}]'

def test_adjacent(run, x):
    n_m = x.strip().split()
    n = int(n_m[0]); m = int(n_m[1])
    if n <= 1:
        return
    out = run(x).strip()
    a = int(out)
    assert abs(a - m) == 1, f'a={a} not adjacent to m={m}'

def test_not_m(run, x):
    n_m = x.strip().split()
    n = int(n_m[0]); m = int(n_m[1])
    if n <= 1:
        return
    out = run(x).strip()
    a = int(out)
    assert a != m, f'a equals m={m}'

def test_direct_condition(run, x):
    n_m = x.strip().split()
    n = int(n_m[0]); m = int(n_m[1])
    out = run(x).strip()
    a = int(out)
    if n == 1:
        assert a == 1, f'when n=1 a must be 1, got {a}'
    else:
        if n - m > m - 1:
            assert a == m + 1, f'expected m+1={m+1}, got {a}'
        else:
            assert a == m - 1, f'expected m-1={m-1}, got {a}'

def test_win_count_optimal(run, x):
    n_m = x.strip().split()
    n = int(n_m[0]); m = int(n_m[1])
    out = run(x).strip()
    a = int(out)
    if n == 1:
        return
    # compute winning count for a
    if a < m:
        win_a = (a + m - 1) // 2
    elif a > m:
        win_a = n - (a + m) // 2
    else:
        win_a = 0
    # the only other candidate is the other adjacent
    if a == m + 1 and m - 1 >= 1:
        other = m - 1
        win_other = (other + m - 1) // 2  # since other < m
        assert win_a >= win_other, f'win count {win_a} < {win_other} for other {other}'
        if win_a == win_other:
            assert a <= other, f'tie but a={a} > other={other}'
    elif a == m - 1 and m + 1 <= n:
        other = m + 1
        win_other = n - (other + m) // 2  # since other > m
        assert win_a >= win_other, f'win count {win_a} < {win_other} for other {other}'
        if win_a == win_other:
            assert a <= other, f'tie but a={a} > other={other}'

def test_symmetry_win_counts(run, x):
    n_m = x.strip().split()
    n = int(n_m[0]); m = int(n_m[1])
    if n == 1:
        return
    out1 = run(x).strip()
    a1 = int(out1)
    # reflected input
    m2 = n + 1 - m
    x2 = f'{n} {m2}\n'
    out2 = run(x2).strip()
    a2 = int(out2)
    # win count for a1 on original input
    if a1 < m:
        win1 = (a1 + m - 1) // 2
    elif a1 > m:
        win1 = n - (a1 + m) // 2
    else:
        win1 = 0
    # win count for a2 on reflected input
    if a2 < m2:
        win2 = (a2 + m2 - 1) // 2
    elif a2 > m2:
        win2 = n - (a2 + m2) // 2
    else:
        win2 = 0
    assert win1 == win2, f'win counts differ: {win1} vs {win2} under symmetry'

def test_positive_win_count(run, x):
    n_m = x.strip().split()
    n = int(n_m[0]); m = int(n_m[1])
    if n == 1:
        return
    out = run(x).strip()
    a = int(out)
    if a < m:
        win = (a + m - 1) // 2
    elif a > m:
        win = n - (a + m) // 2
    else:
        win = 0
    assert win > 0, f'win count {win} is not positive'

def test_extreme_cases(run, x):
    n_m = x.strip().split()
    n = int(n_m[0]); m = int(n_m[1])
    if n > 1:
        out = run(x).strip()
        a = int(out)
        if m == 1:
            assert a == 2, f'for m=1, a must be 2, got {a}'
        elif m == n:
            assert a == n - 1, f'for m=n={n}, a must be {n-1}, got {a}'

def test_consistency_with_adjacent(run, x):
    n_m = x.strip().split()
    n = int(n_m[0]); m = int(n_m[1])
    if n == 1:
        return
    out = run(x).strip()
    a = int(out)
    if a == m - 1:
        assert m - 1 >= n - m, f'chose m-1 but condition m-1 >= n-m fails'
    elif a == m + 1:
        assert n - m > m - 1, f'chose m+1 but condition n-m > m-1 fails'

def test_win_count_range(run, x):
    n_m = x.strip().split()
    n = int(n_m[0]); m = int(n_m[1])
    out = run(x).strip()
    a = int(out)
    if a < m:
        win = (a + m - 1) // 2
    elif a > m:
        win = n - (a + m) // 2
    else:
        win = 0
    assert 0 <= win <= n, f'win count {win} outside [0, {n}]'

