tests_src:
def test_output_parses_as_integer(run, x):
    out = run(x).strip()
    try:
        int(out)
    except ValueError:
        assert False, f'Output "{out}" is not a valid integer.'

def test_output_in_range(run, x):
    n = int(run(x).strip())
    assert 1 <= n <= 10, f'Output {n} is not in [1,10].'

def test_validity(run, x):
    k, r = map(int, x.strip().split())
    n = int(run(x).strip())
    total = k * n
    assert total % 10 in (0, r), f'Total {total} mod 10 is {total%10}, not 0 or {r}.'

def test_minimality(run, x):
    k, r = map(int, x.strip().split())
    n = int(run(x).strip())
    for m in range(1, n):
        if (k * m) % 10 in (0, r):
            assert False, f'Smaller m={m} also satisfies the condition.'

def test_mod10_invariance_add(run, x):
    k, r = map(int, x.strip().split())
    n1 = int(run(x).strip())
    k2 = k + 10
    inp2 = f'{k2} {r}\n'
    n2 = int(run(inp2).strip())
    assert n1 == n2, f'Adding 10 changed output from {n1} to {n2}.'

def test_mod10_invariance_sub(run, x):
    k, r = map(int, x.strip().split())
    if k > 10:
        n1 = int(run(x).strip())
        k2 = k - 10
        inp2 = f'{k2} {r}\n'
        n2 = int(run(inp2).strip())
        assert n1 == n2, f'Subtracting 10 changed output from {n1} to {n2}.'

def test_condition_for_1(run, x):
    k, r = map(int, x.strip().split())
    n = int(run(x).strip())
    if (k * 1) % 10 in (0, r):
        # By minimality, answer must be 1
        assert n == 1, f'k*1 mod 10 is 0 or {r}, but output is {n}, not 1.'

def test_condition_for_2(run, x):
    k, r = map(int, x.strip().split())
    n = int(run(x).strip())
    cond1 = (k * 1) % 10 in (0, r)
    cond2 = (k * 2) % 10 in (0, r)
    if not cond1 and cond2:
        # Minimality forces n=2 because m=1 fails and m=2 works
        assert n == 2, f'k*1 fails, k*2 works, but output is {n}, not 2.'

def test_condition_for_8(run, x):
    k, r = map(int, x.strip().split())
    n = int(run(x).strip())
    if (k * 8) % 10 in (0, r):
        # If m=8 works, minimality ensures n ≤ 8
        assert n <= 8, f'k*8 mod 10 is 0 or {r}, but output {n} > 8.'

def test_condition_for_9(run, x):
    k, r = map(int, x.strip().split())
    n = int(run(x).strip())
    if (k * 9) % 10 in (0, r):
        # If m=9 works, minimality ensures n ≤ 9
        assert n <= 9, f'k*9 mod 10 is 0 or {r}, but output {n} > 9.'

