    n = int(x.strip())
    if n > 100:
        return  # skip for large n as per plan
    # Compute exact MST weight by Kruskal
    edges = []
    for i in range(1, n + 1):
        for j in range(i + 1, n + 1):
            w = (i + j) % (n + 1)
            edges.append((w, i, j))
    edges.sort()
    parent = list(range(n + 1))
    def find(v):
        while parent[v] != v:
            parent[v] = parent[parent[v]]
            v = parent[v]
        return v
    def union(v1, v2):
        p1, p2 = find(v1), find(v2)
        if p1 != p2:
            parent[p2] = p1
            return True
        return False
    mst_weight = 0
    for w, i, j in edges:
        if union(i, j):
