def test_symmetry(run, x):
    n, m = map(int, x.strip().split())
    out1 = run(x).strip()
    out2 = run(f"{m} {n}\n").strip()
    assert out1 == out2, f"symmetry broken: ({n},{m}) -> {out1}, swapped -> {out2}"

def test_mod_range(run, x):
    out = run(x).strip()
    try:
        val = int(out)
        MOD = 10**9 + 7
        assert 0 <= val < MOD, f"output {val} not in modulo range"
    except ValueError:
        raise AssertionError(f"output not an integer: {out}")

def test_parity(run, x):
    out = run(x).strip()
    val = int(out)
    assert val % 2 == 0, f"output {val} is odd, must be even"

def test_1d_row(run, x):
    n, m = map(int, x.strip().split())
    if n != 1:
        return
    MOD = 10**9 + 7
    fib = [1, 2]
    for i in range(2, m):
        fib.append((fib[-1] + fib[-2]) % MOD)
    expected = (2 * fib[m-1]) % MOD if m >= 1 else 2  # m>=1 always
    got = int(run(x).strip())
    assert got == expected, f"1-row: got {got}, expected {expected}"

def test_1d_column(run, x):
    n, m = map(int, x.strip().split())
    if m != 1:
        return
    MOD = 10**9 + 7
    fib = [1, 2]
    for i in range(2, n):
        fib.append((fib[-1] + fib[-2]) % MOD)
    expected = (2 * fib[n-1]) % MOD if n >= 1 else 2
    got = int(run(x).strip())
    assert got == expected, f"1-column: got {got}, expected {expected}"

def test_brute_small(run, x):
    n, m = map(int, x.strip().split())
    if n * m > 9:
        return
    MOD = 10**9 + 7
    total = 0
    for mask in range(1 << (n * m)):
        ok = True
        for i in range(n):
            for j in range(m):
                same = 0
                color = (mask >> (i * m + j)) & 1
                for di, dj in ((1,0),(-1,0),(0,1),(0,-1)):
                    ni, nj = i + di, j + dj
                    if 0 <= ni < n and 0 <= nj < m:
                        ncolor = (mask >> (ni * m + nj)) & 1
                        if ncolor == color:
                            same += 1
                if same > 1:
                    ok = False
                    break
            if not ok:
                break
        if ok:
            total += 1
    expected = total % MOD
    got = int(run(x).strip())
    assert got == expected, f"brute small: got {got}, expected {expected}"

def test_brute_4x4(run, x):
    n, m = map(int, x.strip().split())
    if not (n == 4 and m == 4):
        return
    MOD = 10**9 + 7
    total = 0
    for mask in range(1 << 16):
        ok = True
        for i in range(4):
            for j in range(4):
                same = 0
                color = (mask >> (i * 4 + j)) & 1
                for di, dj in ((1,0),(-1,0),(0,1),(0,-1)):
                    ni, nj = i + di, j + dj
                    if 0 <= ni < 4 and 0 <= nj < 4:
                        ncolor = (mask >> (ni * 4 + nj)) & 1
                        if ncolor == color:
                            same += 1
                if same > 1:
                    ok = False
                    break
            if not ok:
                break
        if ok:
            total += 1
    expected = total % MOD
    got = int(run(x).strip())
    assert got == expected, f"brute 4x4: got {got}, expected {expected}"

def test_square_odd_adjustment(run, x):
    n, m = map(int, x.strip().split())
    if n == m and n % 2 == 1 and n > 1:
        out = int(run(x).strip())
        assert out % 2 == 0, f"square odd n={n}: output {out} must be even"

def test_1d_consistency(run, x):
    n, m = map(int, x.strip().split())
    if n == 1 and m == 1:
        got = int(run(x).strip())
        assert got == 2, f"1x1 must be 2, got {got}"
    elif n == 1 or m == 1:
        # Already covered by 1d_row/1d_column, but double-check via symmetry
        out1 = int(run(x).strip())
        out2 = int(run(f"{m} {n}\n").strip())
        assert out1 == out2, f"1D case symmetry broken: ({n},{m})->{out1}, swapped->{out2}"

def test_example_from_statement(run, x):
    # Only check the exact example given in the statement
    if x.strip() == "2 3":
        got = int(run(x).strip())
        assert got == 8, f"example (2,3) must be 8, got {got}"

