def test_palindrome(run, x):
    out = run(x).strip().split()
    K = int(x.split()[0])
    assert len(out) == 2*K - 1
    for idx in range(K-1):
        if out[idx] != out[2*K - 2 - idx]:
            raise AssertionError(f"Output not symmetric at indices {idx} and {2*K-2-idx}")


def test_i2_total(run, x):
    MOD = 998244353
    K, N = map(int, x.split())
    # compute C(N+K-1, K-1) modulo MOD
    def nCr_mod(n, r):
        r = min(r, n-r)
        numer = 1
        denom = 1
        for i in range(1, r+1):
            numer = numer * (n - r + i) % MOD
            denom = denom * i % MOD
        # modular inverse via Fermat
        return numer * pow(denom, MOD-2, MOD) % MOD
    total = nCr_mod(N+K-1, K-1)
    out = run(x).strip().split()
    assert int(out[0]) == total


def test_i2K_total(run, x):
    MOD = 998244353
    K, N = map(int, x.split())
    def nCr_mod(n, r):
        r = min(r, n-r)
        numer = 1
        denom = 1
        for i in range(1, r+1):
            numer = numer * (n - r + i) % MOD
            denom = denom * i % MOD
        return numer * pow(denom, MOD-2, MOD) % MOD
    total = nCr_mod(N+K-1, K-1)
    out = run(x).strip().split()
    assert int(out[-1]) == total


def test_N1_all_K(run, x):
    K, N = map(int, x.split())
    if N == 1:
        out = run(x).strip().split()
        expected = str(K % 998244353)
        for val in out:
            if val != expected:
                raise AssertionError(f"For N=1, all outputs must be {expected}, got {val}")


def test_K1_all_1(run, x):
    K, N = map(int, x.split())
    if K == 1:
        out = run(x).strip().split()
        for val in out:
            if val != "1":
                raise AssertionError(f"For K=1, all outputs must be 1, got {val}")


def test_small_bruteforce(run, x):
    MOD = 998244353
    K, N = map(int, x.split())
    # estimate total multisets
    total = 1
    for i in range(1, K):
        total = total * (N + i) // i
        if total > 10**6:
            return  # skip, too large
    # enumerate all multisets via recursion
    from itertools import combinations_with_replacement
    multisets = list(combinations_with_replacement(range(1, K+1), N))
    counts = [0] * (2*K - 1)  # indices 0..2K-2 correspond to i=2..2K
    for mset in multisets:
        # check condition for each i
        for idx in range(2*K - 1):
            i = idx + 2
            ok = True
            # check all unordered pairs (different dice)
            # we have a multiset, need to see if any two distinct elements sum to i
            seen = {}
            for v in mset:
                seen[v] = seen.get(v, 0) + 1
            for a in seen:
                b = i - a
                if b in seen:
                    if a != b or seen[a] >= 2:
                        ok = False
                        break
            if ok:
                counts[idx] += 1
    out = list(map(int, run(x).strip().split()))
    for idx in range(2*K - 1):
        if counts[idx] % MOD != out[idx]:
            raise AssertionError(f"Mismatch at i={idx+2}: expected {counts[idx]%MOD}, got {out[idx]}")


def test_output_length(run, x):
    K = int(x.split()[0])
    out = run(x).strip().split()
    assert len(out) == 2*K - 1


def test_output_range(run, x):
    MOD = 998244353
    out = run(x).strip().split()
    for s in out:
        val = int(s)
        assert 0 <= val < MOD


def test_no_negative(run, x):
    out = run(x).strip().split()
    for s in out:
        if int(s) < 0:
            raise AssertionError(f"Negative output: {s}")


def test_i2_equals_i2K(run, x):
    out = run(x).strip().split()
    if out[0] != out[-1]:
        raise AssertionError(f"First output {out[0]} != last output {out[-1]}")

