    if out == 'yes':
        y = int(x.split()[1])
        assert y >= 1, f'Yes but y={y} < 1'

def test_yes_requires_x_ge_y_minus_1(run, x):
    out = run(x).strip().lower()
    if out == 'yes':
        x_val, y_val = map(int, x.split())
