        assert diff % 2 == 0, f'Yes but x-(y-1)={diff} is odd'

def test_yes_requires_y1_implies_x0(run, x):
    out = run(x).strip().lower()
    if out == 'yes':
        x_val, y_val = map(int, x.split())
        if y_val == 1:
            assert x_val == 0, f'Yes with y=1 but x={x_val} != 0'

def test_certificate(run, x):
    out = run(x).strip().lower()
    if out == 'yes':
        x_val, y_val = map(int, x.split())
        u = y_val - 1
        v = (x_val - u) // 2
        # v must be integer (parity already checked)
        assert v >= 0, f'Certificate v={v} negative'
        if v > 0:
            assert u >= 1, f'Need at least one original to perform copy operations, but u={u}'

def test_metamorphic_add_original(run, x):
    out1 = run(x).strip().lower()
    if out1 == 'yes':
        x_val, y_val = map(int, x.split())
        if x_val + 1 <= 10**9 and y_val + 1 <= 10**9:
            inp2 = f'{x_val+1} {y_val+1}\n'
            out2 = run(inp2).strip().lower()
            assert out2 == 'yes', f'Yes at ({x_val},{y_val}) but No at ({x_val+1},{y_val+1})'

def test_metamorphic_add_copy(run, x):
