            # operation on a copy: require c >= 1
            if c >= 1 and c + 2 <= 100:
                nxt = (c + 2, o)
                if nxt not in reachable:
                    reachable.add(nxt)
                    q.append(nxt)
        expected = 'yes' if (x_val, y_val) in reachable else 'no'
        actual = run(x).strip().lower()
        assert actual == expected, f'BFS mismatch: expected {expected}, got {actual}'

