def test_parity(run, x):
    # Parse operands and operators
    parts = x.strip().replace('+', ' ').replace('-', ' ').split()
    operands = [int(p) for p in parts]
    total_sum = sum(operands)
    out = run(x).strip()
    if out.startswith('-') and out[1:].isdigit():
        out_val = int(out)
    elif out.isdigit():
        out_val = int(out)
    else:
        assert False, "output not integer"
    assert (out_val % 2) == (total_sum % 2)

def test_last_digit(run, x):
    # Compute correct evaluation last digit left-to-right
    tokens = []
    num = ''
    for ch in x.strip():
        if ch.isdigit():
            num += ch
        else:
            if num:
                tokens.append(int(num))
                num = ''
            tokens.append(ch)
    if num:
        tokens.append(int(num))
    # Evaluate
    val = tokens[0]
    i = 1
    while i < len(tokens):
        op = tokens[i]
        next_val = tokens[i+1]
        if op == '+':
            val += next_val
        else:  # '-'
            val -= next_val
        i += 2
    correct_last = abs(val) % 10  # last digit of correct evaluation
    out = run(x).strip()
    if out.startswith('-') and out[1:].isdigit():
        out_last = int(out[-1])
    elif out.isdigit():
        out_last = int(out[-1])
    else:
        assert False, "output not integer"
    assert out_last == correct_last

def test_mod3(run, x):
    # Compute correct evaluation mod 3
    tokens = []
    num = ''
    for ch in x.strip():
        if ch.isdigit():
            num += ch
        else:
            if num:
                tokens.append(int(num))
                num = ''
            tokens.append(ch)
    if num:
        tokens.append(int(num))
    val = tokens[0]
    i = 1
    while i < len(tokens):
        op = tokens[i]
        next_val = tokens[i+1]
        if op == '+':
            val += next_val
        else:
            val -= next_val
        i += 2
    correct_mod3 = val % 3
    plus_count = x.strip().count('+')
    expected_mod3 = (correct_mod3 + plus_count) % 3
    out = run(x).strip()
    if out.startswith('-') and out[1:].isdigit():
        out_val = int(out)
    elif out.isdigit():
        out_val = int(out)
    else:
        assert False, "output not integer"
    assert (out_val % 3) == expected_mod3

def test_mod4(run, x):
    # Compute correct evaluation mod 4
    tokens = []
    num = ''
    for ch in x.strip():
        if ch.isdigit():
            num += ch
        else:
            if num:
                tokens.append(int(num))
                num = ''
            tokens.append(ch)
    if num:
        tokens.append(int(num))
    val = tokens[0]
    i = 1
    while i < len(tokens):
        op = tokens[i]
        next_val = tokens[i+1]
        if op == '+':
            val += next_val
        else:
            val -= next_val
        i += 2
    correct_mod4 = val % 4
    # Count operands with length 1
    parts = x.strip().replace('+', ' ').replace('-', ' ').split()
    length1_count = sum(1 for p in parts if len(p) == 1)
    expected_mod4 = (correct_mod4 + 2 * length1_count) % 4
    out = run(x).strip()
    if out.startswith('-') and out[1:].isdigit():
        out_val = int(out)
    elif out.isdigit():
        out_val = int(out)
    else:
        assert False, "output not integer"
    assert (out_val % 4) == expected_mod4

def test_bound(run, x):
    # Compute bound: sum over operands of (10**len * 5 + 255)
    parts = x.strip().replace('+', ' ').replace('-', ' ').split()
    bound = 0
    for p in parts:
        val = int(p)
        bound += (10 ** len(p)) * 5 + 255
    out = run(x).strip()
    if out.startswith('-') and out[1:].isdigit():
        out_val = int(out)
    elif out.isdigit():
        out_val = int(out)
    else:
        assert False, "output not integer"
    assert abs(out_val) <= bound

def test_append_zero(run, x):
    # Count operands from the input
    parts = x.strip().replace('+', ' ').replace('-', ' ').split()
    if len(parts) >= 10:
        # If already 10 operands, skip because appending '+0' would exceed max 10? 
        # Specification says expression will contain between 2 and 10 operands.
        # Appending '+0' would make 11 operands, which is invalid.
        # So only test when fewer than 10.
        return
    modified = x.strip() + '+0'
    out1 = run(x).strip()
    out2 = run(modified).strip()
    if out1.startswith('-') and out1[1:].isdigit():
        v1 = int(out1)
    elif out1.isdigit():
        v1 = int(out1)
    else:
        assert False
    if out2.startswith('-') and out2[1:].isdigit():
        v2 = int(out2)
    elif out2.isdigit():
        v2 = int(out2)
    else:
        assert False
    assert v2 == v1 - 50

def test_all_plus(run, x):
    if '-' in x.strip():
        return  # not all plus
    parts = x.strip().split('+')
    operands = [int(p) for p in parts]
    total = sum(operands)
    out = run(x).strip()
    if out.startswith('-') and out[1:].isdigit():
        out_val = int(out)
    elif out.isdigit():
        out_val = int(out)
    else:
        assert False, "output not integer"
    assert out_val <= total

def test_all_minus(run, x):
    if '+' in x.strip():
        return  # not all minus
    parts = x.strip().split('-')
    operands = [int(p) for p in parts]
    if not operands:
        return
    correct = operands[0] - sum(operands[1:])
    out = run(x).strip()
    if out.startswith('-') and out[1:].isdigit():
        out_val = int(out)
    elif out.isdigit():
        out_val = int(out)
    else:
        assert False, "output not integer"
    assert out_val >= correct

def test_integer(run, x):
    out = run(x).strip()
    # Allow optional leading minus and digits
    if out.startswith('-'):
        rest = out[1:]
        assert rest.isdigit() and (rest == '0' or not rest.startswith('0'))
    else:
        assert out.isdigit() and (out == '0' or not out.startswith('0'))

def test_leading_zero_first(run, x):
    # Prepend a '0' to the first operand
    s = x.strip()
    # Find first number
    i = 0
    while i < len(s) and s[i].isdigit():
        i += 1
    first_num = s[:i]
    rest = s[i:]
    modified = '0' + first_num + rest  # prepend a zero to the first number
    out1 = run(x).strip()
    out2 = run(modified).strip()
    if out1.startswith('-') and out1[1:].isdigit():
        v1 = int(out1)
    elif out1.isdigit():
        v1 = int(out1)
    else:
        assert False
    if out2.startswith('-') and out2[1:].isdigit():
        v2 = int(out2)
    elif out2.isdigit():
        v2 = int(out2)
    else:
        assert False
    assert v2 == v1

