{
  "rationale": "These tests verify necessary properties derived from the specification without computing the exact answer. Bounds and all-zero check basic constraints. Reversal and strip zeros ensure symmetry and that leading/trailing zeros do not affect the answer. Block additivity captures independence across zeros, since operations cannot cover zeros. Constant and single changes test monotonicity and linearity, as adding water requires at most one extra operation per unit increase. All-equal is a special case with a known answer. Together they can catch off‑by‑one errors, mishandling of zeros, and incorrect segment aggregation. If one test had to be dropped, test_single_decrease is the least critical, being symmetric to test_single_increase.",
  "plan": [
    {
      "name": "test_bounds",
      "intent": "Assert that the output is an integer between the maximum height in the input and the sum of all heights, inclusive. Any output outside this range is impossible for a correct solution."
    },
    {
      "name": "test_all_zero",
      "intent": "If every height in the input is zero, the output must be exactly zero. A non‑zero answer in this case is wrong."
    },
    {
      "name": "test_reversal",
      "intent": "Reverse the order of the heights in the input. The output for the reversed input must be the same as for the original input, because the problem is symmetric."
    },
    {
      "name": "test_block_additivity",
      "intent": "Split the sequence into maximal contiguous blocks of positive heights (ignoring zeros). For each block, run the program on that block alone and record its output. The sum of these outputs must equal the output for the original full sequence, because operations cannot cross zeros and the blocks are independent."
    },
    {
      "name": "test_constant_increase",
      "intent": "If every height is less than 100, create a new input by adding 1 to every height. The output for this new input must be exactly 1 greater than the output for the original input."
    },
    {
      "name": "test_constant_decrease",
      "intent": "If every height is greater than 0, create a new input by subtracting 1 from every height. The output for this new input must be exactly 1 less than the output for the original input."
    },
    {
      "name": "test_single_increase",
      "intent": "Find the first index where the height is less than 100. Increase that height by 1 to create a modified input. The output for the modified input must be at least the original output and at most the original output plus 1."
    },
    {
      "name": "test_single_decrease",
      "intent": "Find the first index where the height is greater than 0. Decrease that height by 1 to create a modified input. The output for the modified input must be at most the original output and at least the original output minus 1."
    },
    {
      "name": "test_strip_zeros",
      "intent": "Remove any leading and trailing zeros from the sequence of heights. The output for the stripped sequence must equal the output for the original sequence, because leading and trailing zeros never participate in any watering operation."
    },
    {
      "name": "test_all_equal",
      "intent": "If all heights in the input are equal to the same value c, the output must be exactly c. Any other answer is incorrect for this special case."
    }
  ]
}

{
  "rationale": "The tests verify the specification through total cookie conservation, correct per-person eaten counts, logical implications of the eating order, monotonicity in K, and special cases. The sum and eaten checks are precise certificates; implication tests catch order violations; metamorphic tests ensure consistency. Non-negativity and bounds are basic sanity. If dropping one, test_non_negative is weakest as implied by other checks.",
  "plan": [
