def test_example1(run, x):
    if x == '8-7+6-5+4-3+2-1-0\n':
        assert run(x) == '4\n'

def test_example2(run, x):
    if x == '2+2\n':
        assert run(x) == '-46\n'

def test_example3(run, x):
    if x == '112-37\n':
        assert run(x) == '375\n'

def test_bounds(run, x):
    out = run(x).strip()
    try:
        val = int(out)
    except ValueError:
        raise AssertionError('output not an integer')
    assert -100000 <= val <= 100000

def test_integer(run, x):
    out = run(x).strip()
    if out.startswith('-'):
        rest = out[1:]
        assert rest.isdigit() and len(rest) > 0
    else:
        assert out.isdigit()
    # Ensure conversion works (should, but double-check)
    int(out)

def test_mod10(run, x):
    # Compute correct evaluation of expression modulo 10 from input
    expr = x.strip()
    # Simple evaluator: parse numbers and operators
    import re
    parts = re.split(r'([+-])', expr)
    # parts is like ['', '8', '-', '7', '+', '6', ...] if starts with number
    # Handle first number
    if parts[0] == '':
        parts = parts[1:]
    # Now parts[0] is first number, then op, number, op, ...
    total = int(parts[0])
    i = 1
    while i < len(parts):
        op = parts[i]
        num = int(parts[i+1])
        if op == '+':
            total += num
        else:  # '-'
            total -= num
        i += 2
    correct_mod = total % 10
    # Get output modulo 10
    out = run(x).strip()
    try:
        out_val = int(out)
    except ValueError:
        raise AssertionError('output not an integer')
    assert (out_val % 10) == correct_mod

def test_metamorphic_trailing_plus_zero(run, x):
    expr = x.strip()
    # Parse to get operand count and check preconditions
    import re
    operands = [int(s) for s in re.split(r'[+-]', expr) if s]
    if len(operands) >= 10:
        return  # precondition not met
    if operands[-1] == 2 * operands[0] + 1:
        return  # precondition not met
    # Compute original output
    out1_str = run(x).strip()
    try:
        out1 = int(out1_str)
    except ValueError:
        raise AssertionError('output not an integer')
    # Build modified input: append '+0'
    modified = expr + '+0' + '\n'
    out2_str = run(modified).strip()
    try:
        out2 = int(out2_str)
    except ValueError:
        raise AssertionError('modified output not an integer')
    assert out2 == out1 - 50

def test_metamorphic_leading_zero_plus(run, x):
    expr = x.strip()
    import re
    operands = [int(s) for s in re.split(r'[+-]', expr) if s]
    if len(operands) >= 10:
        return
    if operands[-1] == 2 * operands[0] + 1:
        return
    first = operands[0]
    out1_str = run(x).strip()
    try:
        out1 = int(out1_str)
    except ValueError:
        raise AssertionError('output not an integer')
    modified = '0+' + expr + '\n'
    out2_str = run(modified).strip()
    try:
        out2 = int(out2_str)
    except ValueError:
        raise AssertionError('modified output not an integer')
    delta = 5 * (10 ** len(str(first)))
    assert out2 == out1 - delta

def test_single_operator_formula(run, x):
    expr = x.strip()
    import re
    operands = [int(s) for s in re.split(r'[+-]', expr) if s]
    if len(operands) != 2:
        return  # not exactly one operator
    # Determine operator
    if '+' in expr:
        op = '+'
    else:
        op = '-'
    if operands[-1] == 2 * operands[0] + 1:
        return  # precondition not met
    a, b = operands
    if op == '+':
        correct = (a + b) + (-5) * (10 ** len(str(b)))
    else:
        correct = (a - b) + 3 * (10 ** len(str(b)))
    out_str = run(x).strip()
    try:
        out_val = int(out_str)
    except ValueError:
        raise AssertionError('output not an integer')
    assert out_val == correct

def test_operand_count_range(run, x):
    expr = x.strip()
    import re
    operands = [s for s in re.split(r'[+-]', expr) if s]
    # Specification says between 2 and 10 operands inclusive
    # If the input violates that, the test environment is invalid, but we assert anyway.
    assert 2 <= len(operands) <= 10

