tests_src:
def test_bounds(run, x):
    A, B, C = map(int, x.strip().split())
    out = run(x).strip()
    assert out.isdigit() or (out.startswith('-') and out[1:].isdigit())
    val = int(out)
    assert 0 <= val <= C

def test_maximal_transfer(run, x):
    A, B, C = map(int, x.strip().split())
    out = run(x).strip()
    assert out.isdigit() or (out.startswith('-') and out[1:].isdigit())
    val = int(out)
    t = C - val
    assert 0 <= t <= A - B
    assert t == A - B or val == 0

def test_monotonic_c_increase(run, x):
    A, B, C = map(int, x.strip().split())
    if C < 20:
        out1 = int(run(x).strip())
        out2 = int(run(f'{A} {B} {C+1}\n').strip())
        assert out2 >= out1

def test_monotonic_c_decrease(run, x):
    A, B, C = map(int, x.strip().split())
    if C > 1:
        out1 = int(run(x).strip())
        out2 = int(run(f'{A} {B} {C-1}\n').strip())
        assert out2 <= out1

def test_monotonic_b_increase(run, x):
    A, B, C = map(int, x.strip().split())
    if B < A:
        out1 = int(run(x).strip())
        out2 = int(run(f'{A} {B+1} {C}\n').strip())
        assert out2 >= out1

def test_monotonic_b_decrease(run, x):
    A, B, C = map(int, x.strip().split())
    if B > 1:
        out1 = int(run(x).strip())
        out2 = int(run(f'{A} {B-1} {C}\n').strip())
        assert out2 <= out1

def test_monotonic_a_increase(run, x):
    A, B, C = map(int, x.strip().split())
    if A < 20:
        out1 = int(run(x).strip())
        out2 = int(run(f'{A+1} {B} {C}\n').strip())
        assert out2 <= out1

def test_monotonic_a_decrease(run, x):
    A, B, C = map(int, x.strip().split())
    if A > B:
        out1 = int(run(x).strip())
        out2 = int(run(f'{A-1} {B} {C}\n').strip())
        assert out2 >= out1

def test_full_bottle1(run, x):
    A, B, C = map(int, x.strip().split())
    if A == B:
        out = int(run(x).strip())
        assert out == C

def test_empty_bottle2_possible(run, x):
    A, B, C = map(int, x.strip().split())
    if A - B >= C:
        out = int(run(x).strip())
        assert out == 0

