tests_src:
def test_integer(run, x):
    out = run(x)
    try:
        int(out.strip())
    except ValueError:
        assert False, f"Output '{out}' is not a valid integer."

def test_non_negative(run, x):
    out = run(x)
    val = int(out.strip())
    assert val >= 0, f"Count {val} cannot be negative."

def test_upper_bound(run, x):
    N = int(x.strip())
    max_odd = (N + 1) // 2  # number of odd numbers in [1,N]
    out = run(x)
    val = int(out.strip())
    assert val <= max_odd, f"Count {val} exceeds total odd numbers up to {N} ({max_odd})."

def test_monotonic(run, x):
    N = int(x.strip())
    if N < 200:
        out_N = run(x)
        val_N = int(out_N.strip())
        out_next = run(str(N + 1) + '\n')
        val_next = int(out_next.strip())
        assert val_next >= val_N, f"Count decreased from {val_N} at N={N} to {val_next} at N={N+1}."

def test_small_n(run, x):
    N = int(x.strip())
    if N < 105:
