def test_increase_justified(run, x):
    N = int(x.strip())
    if N > 1:
        out_N = run(x)
        val_N = int(out_N.strip())
        out_prev = run(str(N - 1) + '\n')
        val_prev = int(out_prev.strip())
        if val_N > val_prev:
            # N must be odd and have exactly 8 divisors
            if N % 2 == 0:
                assert False, f"Count increased at N={N} but N is even."
            # count divisors
            d = 0
            for i in range(1, int(N**0.5) + 1):
                if N % i == 0:
                    d += 1
                    if i != N // i:
                        d += 1
            assert d == 8, f"Count increased at N={N} but N has {d} divisors, not 8."

def test_diff_0_or_1(run, x):
    N = int(x.strip())
    if N > 1:
        out_N = run(x)
        val_N = int(out_N.strip())
        out_prev = run(str(N - 1) + '\n')
        val_prev = int(out_prev.strip())
        diff = val_N - val_prev
        assert diff in (0, 1), f"Difference {diff} between N={N} and N-1 is not 0 or 1."

def test_output_format(run, x):
    import re
    out = run(x)
    assert re.fullmatch(r'\d+\n', out), f"Output '{out}' does not match required format (digits followed by newline)."

