tests_src:
def test_output_format(run, x):
    out = run(x)
    assert out in ('Yes\n', 'No\n'), f'Invalid output: {repr(out)}'

def test_stripped_output(run, x):
    out = run(x)
    stripped = out.rstrip('\n')
    assert stripped in ('Yes', 'No'), f'Invalid stripped output: {repr(stripped)}'
    assert out.endswith('\n'), f'Missing newline in output: {repr(out)}'

def test_certificate(run, x):
    lines = x.strip('\n').split('\n')
    if len(lines) != 2:
        return  # Input invalid? but given inputs are valid.
    S, T = lines[0], lines[1]
    condition = (len(T) == len(S) + 1) and T.startswith(S)
    out = run(x).strip()
    if condition:
        assert out == 'Yes', f'Expected Yes, got {repr(out)}'
    else:
        assert out == 'No', f'Expected No, got {repr(out)}'

def test_remove_first_char(run, x):
    lines = x.strip('\n').split('\n')
    if len(lines) != 2:
        return
    S, T = lines[0], lines[1]
    if len(S) <= 1:
        return  # cannot remove first char and still have valid S
    new_S = S[1:]
    new_T = T[1:]
    # Check lengths still satisfy |new_T| = |new_S| + 1
    if len(new_T) != len(new_S) + 1:
        return  # should not happen because we removed same char from both
    new_input = f'{new_S}\n{new_T}\n'
    out1 = run(x).strip()
    out2 = run(new_input).strip()
    assert out1 == out2, f'Outputs differ: original {out1}, new {out2}'

def test_prepend_char(run, x):
    lines = x.strip('\n').split('\n')
    if len(lines) != 2:
        return
    S, T = lines[0], lines[1]
    if len(S) >= 10:
        return  # cannot prepend because |S| would exceed 10
    new_S = 'a' + S
    new_T = 'a' + T
    new_input = f'{new_S}\n{new_T}\n'
    out1 = run(x).strip()
    out2 = run(new_input).strip()
    assert out1 == out2, f'Outputs differ: original {out1}, new {out2}'

def test_shift_chars(run, x):
    lines = x.strip('\n').split('\n')
    if len(lines) != 2:
        return
    S, T = lines[0], lines[1]
    def shift(s):
        result = []
        for ch in s:
            if ch == 'z':
                result.append('a')
            else:
                result.append(chr(ord(ch) + 1))
        return ''.join(result)
    new_S = shift(S)
    new_T = shift(T)
    new_input = f'{new_S}\n{new_T}\n'
    out1 = run(x).strip()
    out2 = run(new_input).strip()
    assert out1 == out2, f'Outputs differ under shift: original {out1}, new {out2}'

def test_swap_ab(run, x):
    lines = x.strip('\n').split('\n')
    if len(lines) != 2:
        return
    S, T = lines[0], lines[1]
    def swap_ab(s):
        result = []
        for ch in s:
            if ch == 'a':
                result.append('b')
            elif ch == 'b':
                result.append('a')
            else:
                result.append(ch)
        return ''.join(result)
    new_S = swap_ab(S)
    new_T = swap_ab(T)
    new_input = f'{new_S}\n{new_T}\n'
    out1 = run(x).strip()
    out2 = run(new_input).strip()
    assert out1 == out2, f'Outputs differ under a↔b swap: original {out1}, new {out2}'

def test_length_check(run, x):
    lines = x.strip('\n').split('\n')
    if len(lines) != 2:
        return
    S, T = lines[0], lines[1]
    out = run(x).strip()
    if out == 'Yes':
        assert len(T) == len(S) + 1, f'Yes output but lengths: |T|={len(T)}, |S|={len(S)}'

def test_no_extra_output(run, x):
    out = run(x)
    lines = out.splitlines()
    assert len(lines) == 1, f'Output has {len(lines)} lines, expected 1'
    assert out.strip() == out.rstrip('\n'), f'Extra whitespace before newline: {repr(out)}'

def test_consistency(run, x):
    out1 = run(x).strip()
    out2 = run(x).strip()
    assert out1 == out2, f'Non-deterministic output: first {repr(out1)}, second {repr(out2)}'

