tests_src:
def test_length(run, x):
    out = run(x)
    assert len(out) == 3, 'Output length must be exactly 3 characters'

def test_chars(run, x):
    out = run(x)
    allowed = set('ABCD')
    for ch in out:
        assert ch in allowed, f'Output contains forbidden character {ch}'

def test_prefix(run, x):
    out = run(x)
    assert out.startswith('AB'), 'Output must start with AB'

def test_set(run, x):
    out = run(x)
    assert out in {'ABC', 'ABD'}, 'Output must be either ABC or ABD'

def test_rule(run, x):
    n = int(x.strip())
    out = run(x)
    if n < 1000:
        assert out == 'ABC', 'N < 1000 must output ABC'
    else:
        assert out == 'ABD', 'N >= 1000 must output ABD'

def test_canonical(run, x):
    n = int(x.strip())
    if n < 1000:
        assert run(x) == run('1\n'), 'All N < 1000 must have same output as N=1'
    else:
        assert run(x) == run('1000\n'), 'All N >= 1000 must have same output as N=1000'

def test_shift_1000_neq(run, x):
    n = int(x.strip())
    if n <= 998:
        out_n = run(x)
        out_shift = run(f'{n+1000}\n')
        assert out_n != out_shift, f'Output for N={n} must differ from N={n+1000}'

def test_shift_1000_neq_rev(run, x):
    n = int(x.strip())
    if n >= 1001:
        out_n = run(x)
        out_shift = run(f'{n-1000}\n')
        assert out_n != out_shift, f'Output for N={n} must differ from N={n-1000}'

def test_neighbor_eq(run, x):
    n = int(x.strip())
    if 1 <= n <= 1997:
        out_n = run(x)
        out_next = run(f'{n+1}\n')
        if n != 999:
            assert out_n == out_next, f'Output for N={n} must equal output for N={n+1}'
        else:
            assert out_n != out_next, f'Output for N=999 must not equal output for N=1000'

def test_samples(run, x):
    if x == '1\n':
        assert run(x) == 'ABC', 'Input 1 must output ABC'
    elif x == '999\n':
        assert run(x) == 'ABC', 'Input 999 must output ABC'
    elif x == '1000\n':
        assert run(x) == 'ABD', 'Input 1000 must output ABD'

