def test_output_format(run, x):
    out = run(x).strip()
    assert out == 'YES' or out == 'NO', 'Output must be YES or NO'

def test_c_zero(run, x):
    A, B, C = map(int, x.strip().split())
    if C == 0:
        assert run(x).strip() == 'YES', 'Must output YES when C == 0'

def test_a_one(run, x):
    A, B, C = map(int, x.strip().split())
    if A == 1:
        assert run(x).strip() == 'YES', 'Must output YES when A == 1'

def test_b_one(run, x):
    A, B, C = map(int, x.strip().split())
    if B == 1:
        assert run(x).strip() == 'YES', 'Must output YES when B == 1 (C must be 0)'

def test_a_multiple_of_b(run, x):
    A, B, C = map(int, x.strip().split())
    if A % B == 0:
        if C == 0:
            assert run(x).strip() == 'YES', 'Must output YES when A multiple of B and C == 0'
        else:
            assert run(x).strip() == 'NO', 'Must output NO when A multiple of B and C != 0'

def test_add_a_to_c(run, x):
    A, B, C = map(int, x.strip().split())
    out1 = run(x).strip()
    C2 = (C + A) % B
    x2 = f'{A} {B} {C2}\n'
    out2 = run(x2).strip()
    assert out1 == out2, f'Adding A to C modulo B must not change output: {out1} vs {out2}'

def test_reduce_a_mod_b(run, x):
    A, B, C = map(int, x.strip().split())
    out1 = run(x).strip()
    A2 = A % B
    if A2 == 0:
        A2 = B
    x2 = f'{A2} {B} {C}\n'
    out2 = run(x2).strip()
    assert out1 == out2, f'Reducing A modulo B must not change output: {out1} vs {out2}'

def test_global_periodicity(run, x):
    A, B, C = map(int, x.strip().split())
    # We check for all C' from 0 to B-1 that output(C') == output((C'+A)%B)
    for cp in range(B):
        x1 = f'{A} {B} {cp}\n'
        x2 = f'{A} {B} {(cp + A) % B}\n'
        out1 = run(x1).strip()
        out2 = run(x2).strip()
        assert out1 == out2, f'Periodicity fails at C={cp}: {out1} vs {out2}'

def test_gcd_one(run, x):
    import math
    A, B, C = map(int, x.strip().split())
    if math.gcd(A, B) == 1:
        assert run(x).strip() == 'YES', 'Must output YES when gcd(A,B)==1'

def test_yes_implies_gcd_divides(run, x):
    import math
    A, B, C = map(int, x.strip().split())
    out = run(x).strip()
    if out == 'YES':
        g = math.gcd(A, B)
        assert C % g == 0, f'When output is YES, gcd({A},{B})={g} must divide C={C}'

