def test_output_format(run, x):
    out = run(x).strip()
    if out == 'inf':
        return
    # must be integer between 0 and MOD-1
    try:
        val = int(out)
        MOD = 10**9 + 7
        assert 0 <= val < MOD
    except:
        raise AssertionError('Output must be "inf" or integer mod 10^9+7')

def test_monotonicity(run, x):
    t, a, b = map(int, x.strip().split())
    out = run(x).strip()
    if t == a == b == 1:
        # infinite case handled by another test
        return
    # polynomial with non‑negative coefficients is non‑decreasing for non‑negative x
    # so P(t) = a and P(a) = b must satisfy: if t < a then b ≥ a, if t > a then b ≤ a, if t == a then b == a
    if (t < a and b < a) or (t > a and b > a) or (t == a and b != a):
        # impossible → answer must be 0
        if out != '0':
            raise AssertionError(f'Monotonicity violation: output must be 0 for {t,a,b}')
    # otherwise answer may be non‑zero, but we don't assert that here

def test_congruence_necessary(run, x):
    t, a, b = map(int, x.strip().split())
    out = run(x).strip()
    if out == '0':
        return  # zero answer always allowed
    if out == 'inf':
        # congruence must also hold for infinite case (except t=a=b=1 already covered)
        pass
    # find c0 as described in plan
    c0_candidates = []
    for c0 in range(0, min(a, b) + 1):
        if c0 % t == a % t and c0 % a == b % a:
            c0_candidates.append(c0)
            break
    if not c0_candidates:
        # no such c0 → answer must be 0
        raise AssertionError(f'No c0 satisfying congruences for {t,a,b}, output should be 0')

def test_existence_certificate(run, x):
    t, a, b = map(int, x.strip().split())
    out = run(x).strip()

    def feasible(t, a, b):
        # recursive check for existence of at least one polynomial with non‑negative integer coefficients
        # returns True if possible, False otherwise
        # as described in plan: we can implement the classic recursion from the problem
        if a == 0:
            # all coefficients must be zero, so b must be zero
            return b == 0
        if t == 1:
            # special case: t=1 means P(1) = sum of coefficients = a
            # then P(a) = sum coeff_i * a^i  must equal b
            # This is a subset‑sum problem with unlimited coefficients, but we can bound.
            # For existence, we only need to know if there is a representation.
            # We can use recursion on the largest power: let k be largest power with coefficient c_k
            # Then a = c0 + c1 + ... + c_k, and b = c0 + c1*a + ... + c_k * a^k
            # We can try possible c0 (0..a) and recurse.
            # This recursion will terminate because a decreases.
            for c0 in range(min(a, b) + 1):
                if c0 % t == a % t and c0 % a == b % a:
                    # same congruence condition
                    if feasible(t, a - c0, b - c0):
                        return True
            return False
        # general case: t > 1
        # Write a = c0 + t * a1, where 0 ≤ c0 ≤ min(a,b) and c0 ≡ a (mod t)
        # Then P(t) = c0 + t * Q(t) = a, so Q(t) = a1 = (a - c0)//t
        # P(P(t)) = c0 + Q(t) * P(t) ??? Wait, better to use standard approach:
        # Let P(x) = c0 + x * Q(x) where Q has non‑negative integer coefficients.
        # Then P(t) = c0 + t * Q(t) = a  => Q(t) = (a - c0)/t must be integer.
        # P(P(t)) = c0 + P(t) * Q(P(t)) = c0 + a * Q(a) = b  => Q(a) = (b - c0)/a must be integer.
        # So we need integer c0 with 0 ≤ c0 ≤ min(a,b), c0 ≡ a (mod t), c0 ≡ b (mod a),
        # and then recursively check feasibility for (t, (a-c0)//t, (b-c0)//a) with polynomial Q.
        for c0 in range(0, min(a, b) + 1):
            if (a - c0) % t == 0 and (b - c0) % a == 0 and c0 % t == a % t and c0 % a == b % a:
                a1 = (a - c0) // t
                b1 = (b - c0) // a
                if feasible(t, a1, b1):
                    return True
        return False

    feasible_result = feasible(t, a, b)
    if out == '0':
        if feasible_result:
            raise AssertionError(f'Feasible but output is 0 for {t,a,b}')
    else:
        # output is positive integer or 'inf'
        if not feasible_result:
            raise AssertionError(f'Infeasible but output is not 0 for {t,a,b}')

def test_t_greater_than_a(run, x):
    t, a, b = map(int, x.strip().split())
    if t > a:
        out = run(x).strip()
        if b == a:
            # only constant polynomial a works
            if out != '1':
                raise AssertionError(f'For t>{a} and b=a, answer must be 1, got {out}')
        else:
            # no polynomial
            if out != '0':
                raise AssertionError(f'For t>{a} and b!=a, answer must be 0, got {out}')

def test_a_eq_t_eq_b_greater_than_1(run, x):
    t, a, b = map(int, x.strip().split())
    if t == a == b and a > 1:
        out = run(x).strip()
        if out == 'inf' or out == '0' or out == '1':
            raise AssertionError(f'For t=a=b={a}>1, answer must be ≥2, got {out}')
        # also must be integer (already checked by format test)
        val = int(out)
        if val < 2:
            raise AssertionError(f'For t=a=b={a}>1, answer must be ≥2, got {val}')

def test_infinite_case(run, x):
    t, a, b = map(int, x.strip().split())
    if t == a == b == 1:
        out = run(x).strip()
        if out != 'inf':
            raise AssertionError('For t=a=b=1, output must be "inf"')

def test_t_eq_1_b_eq_a(run, x):
    t, a, b = map(int, x.strip().split())
    if t == 1 and b == a:
        if a == 1:
            # already covered by infinite case
            return
        out = run(x).strip()
        if out == '0' or out == 'inf':
            raise AssertionError(f'For t=1, b=a={a}>1, output must be at least 1, got {out}')

def test_example_consistency(run, x):
    # The two given examples must be satisfied exactly.
    if x.strip() == '2 2 2':
        out = run(x).strip()
        if out != '2':
            raise AssertionError('For input "2 2 2", output must be 2')
    if x.strip() == '2 3 3':
        out = run(x).strip()
        if out != '1':
            raise AssertionError('For input "2 3 3", output must be 1')

def test_b_eq_a(run, x):
    t, a, b = map(int, x.strip().split())
    if b == a:
        if t == a == b == 1:
            # infinite case
            return
        out = run(x).strip()
        if out == '0':
            raise AssertionError(f'For b=a={a} (not the infinite case), output cannot be 0')

