tests_src:
def test_lower_bound(run, x):
    a, b = map(int, x.strip().split())
    out = int(run(x).strip())
    assert out >= a, f'Output {out} must be at least initial candles {a}'

def test_upper_bound(run, x):
    a, b = map(int, x.strip().split())
    out = int(run(x).strip())
    assert out <= 2 * a - 1, f'Output {out} cannot exceed 2a-1 = {2*a-1}'

def test_monotonic_a(run, x):
    a, b = map(int, x.strip().split())
    if a < 1000:
        out1 = int(run(x).strip())
        out2 = int(run(f'{a+1} {b}\n').strip())
        assert out2 >= out1, f'Increasing a from {a} to {a+1} must not decrease output'

def test_monotonic_b(run, x):
    a, b = map(int, x.strip().split())
    if b < 1000:
        out1 = int(run(x).strip())
        out2 = int(run(f'{a} {b+1}\n').strip())
        assert out2 <= out1, f'Increasing b from {b} to {b+1} must not increase output'

def test_certificate(run, x):
    a, b = map(int, x.strip().split())
    out = int(run(x).strip())
    C = out - a  # candles created by exchange
    leftover = a - C * (b - 1)
    assert 0 <= leftover < b, f'Leftover {leftover} must be in [0, b-1] for consistency'

def test_b2(run, x):
    a, b = map(int, x.strip().split())
    if b == 2:
        out = int(run(x).strip())
        assert out == 2 * a - 1, f'For b=2, output must be 2a-1 = {2*a-1}, got {out}'

def test_a1(run, x):
    a, b = map(int, x.strip().split())
    if a == 1:
        out = int(run(x).strip())
        assert out == 1, f'For a=1, output must be 1, got {out}'

def test_recurrence(run, x):
    a, b = map(int, x.strip().split())
    if a >= b:
        out1 = int(run(x).strip())
        out2 = int(run(f'{a-b+1} {b}\n').strip())
        assert out1 == out2 + b, f'Recurrence failed: output({a},{b}) = {out1} should equal output({a-b+1},{b}) + {b} = {out2 + b}'

def test_a_eq_b(run, x):
    a, b = map(int, x.strip().split())
    if a == b:
        out = int(run(x).strip())
        assert out == a + 1, f'For a=b={a}, output must be a+1 = {a+1}, got {out}'

def test_a_ge_b_extra(run, x):
    a, b = map(int, x.strip().split())
    if a >= b:
        out = int(run(x).strip())
        assert out >= a + 1, f'For a={a} >= b={b}, output must be at least a+1 = {a+1}, got {out}'

