    b = list(map(int, lines[1].split()))
    out = list(map(int, run(x).strip().split()))
    # Map button value to its first occurrence index in b (1‑based order)
    order = {val: idx for idx, val in enumerate(b, start=1)}
    # For each button u that appears, collect its light indices
    lights_for_button = {}
    for i, val in enumerate(out, start=1):
        lights_for_button.setdefault(val, []).append(i)
    # Compare every pair of distinct buttons
    buttons = list(lights_for_button.keys())
    for i in range(len(buttons)):
        for j in range(i+1, len(buttons)):
            u, v = buttons[i], buttons[j]
            if u not in order or v not in order:
                continue
            if order[u] < order[v]:  # u pressed before v
                # All lights of u must be > all lights of v
                max_u, min_v = max(lights_for_button[u]), min(lights_for_button[v])
