def test_length(run, x):
    """The output must contain exactly n integers."""
    lines = x.strip().split('\n')
    n, _ = map(int, lines[0].split())
    out = run(x).strip()
    if out == '':
        values = []
    else:
        values = out.split()
    assert len(values) == n, f'Expected {n} numbers, got {len(values)}'

def test_values_in_b(run, x):
    """Every output integer must be an element of the input list b."""
    lines = x.strip().split('\n')
    _, m = map(int, lines[0].split())
    b = list(map(int, lines[1].split()))
    out = run(x).strip()
    if out == '':
        values = []
    else:
        values = list(map(int, out.split()))
    b_set = set(b)
    for v in values:
        assert v in b_set, f'Output value {v} not in button list {b}'

def test_range(run, x):
    """Each output integer must lie between 1 and n inclusive."""
    lines = x.strip().split('\n')
    n, _ = map(int, lines[0].split())
    out = run(x).strip()
    if out == '':
        values = []
    else:
        values = list(map(int, out.split()))
    for v in values:
        assert 1 <= v <= n, f'Output value {v} outside range [1, {n}]'

def test_non_decreasing(run, x):
    """The output sequence must be non‑decreasing."""
    out = run(x).strip()
    if out == '':
        values = []
    else:
        values = list(map(int, out.split()))
    for i in range(1, len(values)):
        assert values[i] >= values[i-1], f'Sequence decreases at position {i}: {values[i-1]} -> {values[i]}'

def test_first_light(run, x):
    """For a valid input, the first output integer must be 1."""
    lines = x.strip().split('\n')
    n, _ = map(int, lines[0].split())
    b = list(map(int, lines[1].split()))
    # Input is guaranteed valid.
    out = run(x).strip()
    if out == '':
        values = []
    else:
        values = list(map(int, out.split()))
    if values:
        assert values[0] == 1, f'First light should be turned off by button 1, got {values[0]}'

def test_last_light(run, x):
    """For a valid input, the last output integer must equal the first button b[0]."""
    lines = x.strip().split('\n')
    n, _ = map(int, lines[0].split())
    b = list(map(int, lines[1].split()))
    out = run(x).strip()
    if out == '':
        values = []
    else:
        values = list(map(int, out.split()))
    if values:
        assert values[-1] == b[0], f'Last light should be turned off by first button {b[0]}, got {values[-1]}'

def test_button_le_light(run, x):
    """For each light i (1‑indexed), output a[i] must satisfy a[i] ≤ i."""
    lines = x.strip().split('\n')
    n, _ = map(int, lines[0].split())
    out = run(x).strip()
    if out == '':
        values = []
    else:
        values = list(map(int, out.split()))
    for i, v in enumerate(values, start=1):
        assert v <= i, f'Light {i} turned off by button {v} > {i}'

def test_certificate(run, x):
    """For each light i with output a[i], let pos be index of a[i] in b.
    For every button b[j] with j < pos, we must have b[j] > i, and also a[i] ≤ i."""
    lines = x.strip().split('\n')
    n, _ = map(int, lines[0].split())
    b = list(map(int, lines[1].split()))
    out = run(x).strip()
    if out == '':
        values = []
    else:
        values = list(map(int, out.split()))
    # Map button value to its first occurrence index in b.
    first_pos = {val: idx for idx, val in enumerate(b)}
    for i, a in enumerate(values, start=1):
        assert a <= i, f'Light {i}: button {a} > {i}'
        if a in first_pos:
            pos = first_pos[a]
            for j in range(pos):
                if b[j] <= i:
                    assert False, f'Light {i}: earlier button {b[j]} ≤ {i} prevents {a} from being the one that turns it off'
        else:
            assert False, f'Light {i}: button {a} not in b'

def test_contiguous(run, x):
    """For each distinct button value v, the set of indices i where output[i] = v must form a contiguous interval, and the smallest index in that interval must be at least v."""
    lines = x.strip().split('\n')
    n, _ = map(int, lines[0].split())
    out = run(x).strip()
    if out == '':
        values = []
    else:
        values = list(map(int, out.split()))
    # Group indices (1‑based) by value.
    groups = {}
    for idx, v in enumerate(values, start=1):
        groups.setdefault(v, []).append(idx)
    for v, idxs in groups.items():
        # Check contiguity.
        if idxs != list(range(min(idxs), max(idxs)+1)):
            assert False, f'Button {v} used on non‑contiguous lights: {idxs}'
        # Smallest index at least v.
        if min(idxs) < v:
            assert False, f'Button {v} used on light {min(idxs)} < {v}'

def test_cover(run, x):
    """The intervals for each button value must be disjoint and cover every index from 1 to n exactly once."""
    lines = x.strip().split('\n')
    n, _ = map(int, lines[0].split())
    out = run(x).strip()
    if out == '':
        values = []
    else:
        values = list(map(int, out.split()))
    seen = [False] * (n + 1)  # 1‑based
    i = 0
    while i < len(values):
        v = values[i]
        j = i
        while j < len(values) and values[j] == v:
            j += 1
        # interval is [i+1, j] (1‑based)
        for idx in range(i+1, j+1):
            if seen[idx]:
                assert False, f'Light {idx} covered multiple times'
            seen[idx] = True
        i = j
    for idx in range(1, n+1):
        if not seen[idx]:
            assert False, f'Light {idx} not covered by any button'

