tests_src:
def test_valid_integer(run, x):
    # intent 1: output must be parseable as integer
    try:
        y = int(x.strip())
    except:
        return  # skip invalid input (shouldn't happen)
    out = run(x).strip()
    assert out.isdigit(), "Output must consist only of digits"
    try:
        int(out)
    except:
        assert False, "Output must be a valid integer"


def test_range(run, x):
    # intent 2: output must be > y and ≤ 9012 (derived upper bound)
    try:
        y = int(x.strip())
    except:
        return
    out = run(x).strip()
    out_int = int(out)
    assert y < out_int, "Output must be strictly greater than input"
    # Upper bound derived: the answer exists for y ≤ 9000, and the next distinct-digit year after 9000 is 9012.
    # Therefore output ≤ 9012 for any y in [1000, 9000].
    assert out_int <= 9012, "Output must not exceed 9012 (derived from existence guarantee)"


def test_distinct_digits(run, x):
    # intent 3: all digits of output must be distinct
    try:
        y = int(x.strip())
    except:
        return
    out = run(x).strip()
    assert len(set(out)) == len(out), "Output digits must be distinct"


def test_minimality(run, x):
    # intent 4: no year between y+1 and output-1 has distinct digits
    try:
        y = int(x.strip())
    except:
        return
    out = run(x).strip()
    out_int = int(out)
    for t in range(y + 1, out_int):
        if len(set(str(t))) == len(str(t)):
            assert False, f"Year {t} has distinct digits, violating minimality"


def test_four_digits(run, x):
    # intent 5: output must be a 4‑digit number
    try:
        y = int(x.strip())
    except:
        return
    out = run(x).strip()
    out_int = int(out)
    assert 1000 <= out_int <= 9999, "Output must be a 4‑digit year"


def test_monotonic(run, x):
    # intent 6: answer must be non‑decreasing when input increases by 1
    try:
        y = int(x.strip())
    except:
        return
    if y == 9000:
        return  # skip because y+1 would be invalid
    out_y = int(run(x).strip())
    out_y1 = int(run(str(y + 1)).strip())
    assert out_y <= out_y1, "Answer for y must not exceed answer for y+1"


def test_constant_for_gap(run, x):
    # intent 7: if y+1 < output(y), then output(y+1) must equal output(y)
    try:
        y = int(x.strip())
    except:
        return
    if y == 9000:
        return
    out_y = int(run(x).strip())
    if y + 1 < out_y:
        out_y1 = int(run(str(y + 1)).strip())
        assert out_y1 == out_y, "When there is a gap, answer for y+1 must equal answer for y"


def test_no_leading_zero(run, x):
    # intent 8: output string must not start with '0'
    try:
        y = int(x.strip())
    except:
        return
    out = run(x).strip()
    assert out[0] != '0', "Output must not have leading zero"


def test_output_format(run, x):
    # intent 9: output string must contain only digits, optionally with newline
    try:
        y = int(x.strip())
    except:
        return
    out = run(x).strip()
    assert out.isdigit(), "Output must consist only of digits"


def test_output_in_set(run, x):
    # intent 10: output must be a valid distinct-digit year between 1000 and 9012
    # Precompute the set of all such years
    valid_set = set()
    for year in range(1000, 9013):
        if len(set(str(year))) == 4:
            valid_set.add(year)
    try:
        y = int(x.strip())
    except:
        return
    out = run(x).strip()
    out_int = int(out)
    assert out_int in valid_set, "Output must be a distinct-digit year within [1000, 9012]"

