tests_src:
def test_example_1(run, x):
    if x == '1\n':
        assert run(x) == '1\n'

def test_example_2(run, x):
    if x == '2\n':
        assert run(x) == '3\n'

def test_example_3(run, x):
    if x == '3\n':
        assert run(x) == '7\n'

def test_valid_positive(run, x):
    output = run(x).strip()
    val = int(output)
    assert val > 0

def test_at_least_n(run, x):
    n = int(x.strip())
    val = int(run(x).strip())
    assert val >= n

def test_lower_bound(run, x):
    n = int(x.strip())
    # L(n) = n + n*n*(n+1)//2 - n*(n+1)*(2*n+1)//6
    L = n + n * n * (n + 1) // 2 - n * (n + 1) * (2 * n + 1) // 6
    val = int(run(x).strip())
    assert val >= L

def test_upper_bound(run, x):
    n = int(x.strip())
    # U(n) = n + n*(n+1)*(n+1)//2 - n*(n+1)*(2*n+1)//6
    U = n + n * (n + 1) * (n + 1) // 2 - n * (n + 1) * (2 * n + 1) // 6
    val = int(run(x).strip())
    assert val <= U

def test_recurrence(run, x):
    n = int(x.strip())
    if n > 1:
        f_n = int(run(x).strip())
        prev_input = str(n - 1) + '\n'
        f_prev = int(run(prev_input).strip())
        assert f_n == f_prev + 1 + n * (n - 1) // 2

def test_monotonic(run, x):
    n = int(x.strip())
    if n > 1:
        f_n = int(run(x).strip())
        prev_input = str(n - 1) + '\n'
        f_prev = int(run(prev_input).strip())
        assert f_n > f_prev

def test_formula(run, x):
    n = int(x.strip())
    f = int(run(x).strip())
    assert 6 * f == n * (n * n + 5)

