    },
    {
      "name": "test_certificate_l_from_dh",
      "intent": "Parse the output as float D. Compute L_calc = sqrt(2*D*H + H*H). Assert that |L_calc - L| / max(1, L) ≤ 1e-6. A violation means the given L does not match the L derived from D and H."
    },
