    }
  ]
}

{
  "rationale": "The tests are designed to catch deviations from the required expected second-price auction outcome. Symmetry and shift tests catch errors dependent on input order or additive miscalibrations. Lower and upper bounds from pairwise minima and overall maximum provide sanity checks. The certificate test recomputes the expectation directly from the definition, catching any major miscalculation. Monotonicity tests on adding/removing companies catch errors in handling the number of bidders. Possible bounds ensure the answer lies within the support of the second-highest bid. Degenerate and n=2 tests target special cases where the answer simplifies and is prone to oversight. The certificate is the strongest; if one test were to be dropped, it would be the pairwise lower bound as it is subsumed by the certificate but is cheaper and catches some errors.",
  "plan": [
    {
      "name": "test_symmetry",
      "intent": "The expected payment is invariant under permutation of the bidders. For the given input, produce a permutation (e.g., reverse the order of lines) and run the program on both. Assert that the two outputs differ by at most 1e-9 in relative or absolute terms."
    },
    {
      "name": "test_shift",
      "intent": "If all bid ranges are shifted by the same integer constant c such that no upper bound exceeds 10000, the expected payment shifts by exactly c. For the input, if possible (max R_i + c <= 10000 for c=1), create a shifted input by adding c to each L_i and R_i. Run both and assert that the difference equals c within 1e-9 tolerance."
    },
    {
      "name": "test_lower_bound_pairwise",
      "intent": "For any pair of bidders, the overall expected second-highest is at least the expected minimum of their two bids. For each pair (i,j), compute E[min(X_i,X_j)] by summing over x from 1 to 10000 the product P(X_i >= x) * P(X_j >= x). Assert that the program's output is not less than any such pairwise expectation minus 1e-9."
    },
    {
      "name": "test_upper_bound_max",
      "intent": "The expected second-highest cannot exceed the expected maximum bid. Compute E[max(X_1,...,X_n)] by summing over x from 1 to 10000 the probability that the maximum is at least x, i.e., 1 - product_i P(X_i < x). Assert that the program's output is not greater than this value plus 1e-9."
