        return (r - x + 1) / (r - l + 1)
    max_val = 10000
    pair_expectations = []
    for i in range(n):
        for j in range(i+1, n):
            exp = 0.0
            for v in range(1, max_val+1):
                exp += prob_ge(i, v) * prob_ge(j, v)
            pair_expectations.append(exp)
    out = float(run(x).strip())
