    ranges = [list(map(int, line.split())) for line in lines[1:]]
    def prob_lt(i, x):
        l, r = ranges[i]
        if x <= l:
            return 0.0
        if x > r+1:
            return 1.0
        return (x - l) / (r - l + 1)
    max_val = 10000
    exp_max = 0.0
    for v in range(1, max_val+1):
        p_ge = 1.0
        for i in range(n):
            p_ge *= (1.0 - prob_lt(i, v))
        exp_max += p_ge
    out = float(run(x).strip())
    assert out <= exp_max + 1e-9"
    },
    {
      "name": "test_certificate",
      "source": "def test_certificate(run, x):
    lines = x.strip().split('\n')
    n = int(lines[0])
    ranges = [list(map(int, line.split())) for line in lines[1:]]
    def prob_ge(i, x):
        l, r = ranges[i]
        if x < l:
            return 1.0
        if x > r:
            return 0.0
        return (r - x + 1) / (r - l + 1)
    max_val = 10000
    expected_sum = 0.0
    for v in range(1, max_val+1):
