tests_src:
def test_output_format(run, x):
    out = run(x)
    assert out in ('YES\n', 'NO\n'), f'Output must be exactly YES\n or NO\n, got {repr(out)}'

def test_symmetry(run, x):
    a, b = map(int, x.strip().split())
    out1 = run(x)
    swapped = f'{b} {a}\n'
    out2 = run(swapped)
    assert out1 == out2, f'Swapping inputs changed output: {repr(out1)} vs {repr(out2)}'

def test_yes_necessary_diff(run, x):
    out = run(x)
    if out.strip() == 'YES':
        a, b = map(int, x.strip().split())
        assert abs(a - b) <= 1, f'YES but |a-b|={abs(a-b)} > 1'

def test_yes_necessary_total(run, x):
    out = run(x)
    if out.strip() == 'YES':
        a, b = map(int, x.strip().split())
        assert a + b > 0, f'YES but total steps is zero'

def test_yes_parity_even(run, x):
    out = run(x)
    if out.strip() == 'YES':
        a, b = map(int, x.strip().split())
        total = a + b
        if total % 2 == 0:
            assert a == b, f'YES, total even {total}, but a={a} != b={b}'

def test_yes_parity_odd(run, x):
    out = run(x)
    if out.strip() == 'YES':
        a, b = map(int, x.strip().split())
        total = a + b
        if total % 2 == 1:
            assert abs(a - b) == 1, f'YES, total odd {total}, but |a-b|={abs(a-b)} != 1'

def test_sufficient_equal(run, x):
    a, b = map(int, x.strip().split())
    if a == b and a > 0:
        out = run(x)
        assert out.strip() == 'YES', f'Equal positive a=b={a} must be YES, got {out.strip()}'

def test_sufficient_diff_one(run, x):
    a, b = map(int, x.strip().split())
    if abs(a - b) == 1 and a + b > 0:
        out = run(x)
        assert out.strip() == 'YES', f'|a-b|=1 and total>0 must be YES, got {out.strip()}'

def test_no_zero_total(run, x):
    a, b = map(int, x.strip().split())
    if a == 0 and b == 0:
        out = run(x)
        assert out.strip() == 'NO', f'Zero total must be NO, got {out.strip()}'

def test_no_large_diff(run, x):
    a, b = map(int, x.strip().split())
    if abs(a - b) > 1:
        out = run(x)
        assert out.strip() == 'NO', f'|a-b|={abs(a-b)} > 1 must be NO, got {out.strip()}'

