tests_src:
def test_sorted(run, x):
    out = run(x).strip('\n')
    lines = out.split('\n') if out else []
    for line in lines:
        if line != ''.join(sorted(line)):
            assert False, f'output line not sorted: {line}'

def test_no_duplicates(run, x):
    out = run(x).strip('\n')
    lines = out.split('\n') if out else []
    for line in lines:
        if len(set(line)) != len(line):
            assert False, f'duplicates in output: {line}'

def test_subset(run, x):
    out = run(x).strip('\n')
    lines = out.split('\n') if out else []
    inputs = x.strip().split('\n')[1:]
    for line, inp in zip(lines, inputs):
        if not set(line).issubset(set(inp)):
            assert False, f'output char not in input: {line} vs {inp}'

def test_reversal(run, x):
    parts = x.strip().split('\n')
    t = int(parts[0])
    strings = parts[1:]
    rev_strings = [s[::-1] for s in strings]
    rev_input = f'{t}\n' + '\n'.join(rev_strings)
    orig_out = run(x).strip('\n').split('\n')
    rev_out = run(rev_input).strip('\n').split('\n')
    for o, r in zip(orig_out, rev_out):
        if o != r:
            assert False, f'reversal mismatch: {o} vs {r}'

def test_duplication(run, x):
    parts = x.strip().split('\n')
    t = int(parts[0])
    strings = parts[1:]
    new_strings = []
    for s in strings:
        if len(s) * 2 <= 500:
            new_strings.append(s + s)
        else:
            new_strings.append(s)
    new_input = f'{t}\n' + '\n'.join(new_strings)
    orig_out = run(x).strip('\n').split('\n')
    new_out = run(new_input).strip('\n').split('\n')
    for o, n in zip(orig_out, new_out):
        if o != n:
            assert False, f'duplication mismatch: {o} vs {n}'

def test_append_pair(run, x):
    parts = x.strip().split('\n')
    t = int(parts[0])
    strings = parts[1:]
    new_strings = []
    for s in strings:
        if len(s) + 2 <= 500:
            new_strings.append(s + s[-1] + s[-1])
        else:
            new_strings.append(s)
    new_input = f'{t}\n' + '\n'.join(new_strings)
    orig_out = run(x).strip('\n').split('\n')
    new_out = run(new_input).strip('\n').split('\n')
    for o, n in zip(orig_out, new_out):
        if o != n:
            assert False, f'append pair mismatch: {o} vs {n}'

def test_bounded(run, x):
    out = run(x).strip('\n')
    lines = out.split('\n') if out else []
    inputs = x.strip().split('\n')[1:]
    for line, inp in zip(lines, inputs):
        if len(line) > len(set(inp)) or len(line) > 26:
            assert False, f'output too long: {line}'

def test_output_has_odd_run(run, x):
    out = run(x).strip('\n')
    lines = out.split('\n') if out else []
    inputs = x.strip().split('\n')[1:]
    for line, inp in zip(lines, inputs):
        for ch in line:
            runs = []
            cnt = 0
            for c in inp:
                if c == ch:
                    cnt += 1
                else:
                    if cnt > 0:
                        runs.append(cnt)
                    cnt = 0
            if cnt > 0:
                runs.append(cnt)
            if all(r % 2 == 0 for r in runs):
                assert False, f'char {ch} has no odd run in input'

def test_odd_run_in_output(run, x):
    out = run(x).strip('\n')
    lines = out.split('\n') if out else []
    inputs = x.strip().split('\n')[1:]
    for line, inp in zip(lines, inputs):
        chars_with_odd = set()
        i = 0
        while i < len(inp):
            j = i
            while j < len(inp) and inp[j] == inp[i]:
                j += 1
            if (j - i) % 2 == 1:
                chars_with_odd.add(inp[i])
            i = j
        if not chars_with_odd.issubset(set(line)):
            assert False, f'char with odd run missing from output: {chars_with_odd - set(line)}'

def test_line_count(run, x):
    t = int(x.strip().split('\n')[0])
    out = run(x).strip('\n')
    lines = out.split('\n') if out else []
    if len(lines) != t:
        assert False, f'expected {t} lines, got {len(lines)}'

