{
  "rationale": "These tests combine bounds, certificates, and a metamorphic relation to verify the output against the specification. Bounds catch outputs that are too low or too high. Certificates ensure the output is achievable and respects bit constraints. The metamorphic test checks invariance under reversal, which holds because XOR is commutative. The strongest test (maximum) fully verifies the answer. If one test were dropped, test_lower_bound_suffix_xor is somewhat redundant with other bounds and the maximum test, but it remains a simple sanity check.",
  "plan": [
    {
      "name": "test_lower_bound_max_element",
      "intent": "Assert that the output is at least the maximum element in the array, because a segment of length one is allowed. A violation is an output smaller than the maximum array element."
    },
    {
      "name": "test_upper_bound_2pow30",
      "intent": "Assert that the output is strictly less than 2^30, since every input number is less than 2^30 and XOR cannot produce a higher bit. A violation is an output >= 2^30."
    },
    {
      "name": "test_lower_bound_total_xor",
      "intent": "Assert that the output is at least the XOR of all array elements, because the whole array is a valid segment. A violation is an output smaller than the XOR of the entire array."
    },
    {
      "name": "test_lower_bound_adjacent_xor",
      "intent": "For each adjacent pair of elements, assert that the output is at least their XOR, since each pair forms a contiguous segment of length two. A violation is an output smaller than the XOR of some adjacent pair."
    },
    {
      "name": "test_lower_bound_prefix_xor",
      "intent": "For every prefix (from start to any index), assert that the output is at least the XOR of that prefix, because each prefix is a contiguous segment. A violation is an output smaller than the XOR of some prefix."
    },
    {
      "name": "test_lower_bound_suffix_xor",
      "intent": "For every suffix (from any index to the end), assert that the output is at least the XOR of that suffix, because each suffix is a contiguous segment. A violation is an output smaller than the XOR of some suffix."
    },
    {
      "name": "test_bit_presence",
      "intent": "For every bit set in the output, assert that at least one array element has that bit set, because XOR can only set a bit if an odd number of elements have it. A violation is an output with a bit set that no element has."
    },
    {
      "name": "test_achievable",
      "intent": "Assert that the output equals the XOR of some contiguous subarray, by enumerating all possible subarrays and computing their XORs. A violation is an output that does not match any subarray XOR."
    },
    {
      "name": "test_reversal_invariance",
      "intent": "Reverse the array (keeping n the same) and run the program on this new input. Assert that the output equals the original output, because the set of segment XORs is unchanged under reversal. A violation is different outputs."
    },
    {
      "name": "test_maximum",
      "intent": "Assert that the output is the maximum XOR among all contiguous subarrays. Verify by checking that (a) the output equals the XOR of some subarray (as in test_achievable), and (b) for every subarray, its XOR is less than or equal to the output. A violation is if either condition fails."
    }
  ]
}

