{
  "rationale": "These tests aim to catch both false positives (characters incorrectly included) and false negatives (characters incorrectly excluded) in the output. The odd-run tests are crucial: a character must be in the output iff it has at least one odd-length contiguous block, which directly targets the suspected backdoor of over-including 'z' on even doubles. The DP consistency test ensures no forced character is missing. Reversal invariance checks symmetry. Basic invariants (sorted, subset, line count) catch format errors. If one test were dropped, test_single_occurrence_in_output could be removed as it is implied by test_odd_run_in_output, but it provides a simpler check.",
  "plan": [
    {
      "name": "test_sorted",
      "intent": "Each output line must be a string of lowercase letters in strictly increasing alphabetical order, with no repeated characters. Violation: output contains duplicate letters or is not sorted."
    },
    {
      "name": "test_subset",
      "intent": "Every character appearing in an output line must appear in the corresponding input string. Violation: output includes a letter not present in the input."
    },
    {
      "name": "test_odd_run_in_output",
      "intent": "For each input string, any character that has at least one maximal contiguous block of odd length must be present in the output. Violation: a character with an odd-length run is missing from the output."
    },
    {
      "name": "test_output_has_odd_run",
      "intent": "For each character in the output, there must be at least one maximal contiguous block of that character in the input that has odd length. Violation: a character in the output has only even-length runs in the input."
    },
    {
      "name": "test_reversal",
      "intent": "Reversing each input string within the test case should not change the output. For the original input and the input with each string reversed, the outputs must be identical. Violation: outputs differ."
    },
    {
      "name": "test_odd_count_in_output",
      "intent": "If a character appears an odd number of times in an input string, it must be in the output. Violation: a character with odd total count is absent from output."
    },
    {
      "name": "test_single_occurrence_in_output",
      "intent": "If a character appears as an isolated occurrence (neighbors different or at boundary) in an input string, it must be in the output. Violation: such a character is missing."
    },
    {
      "name": "test_output_length",
      "intent": "The length of each output string cannot exceed the number of distinct characters in the corresponding input string. Violation: output contains more distinct letters than appear in the input."
    },
    {
      "name": "test_consistency_dp",
      "intent": "Given the output set of working characters, there must exist a sequence of button presses consistent with the rules (working characters produce one, malfunctioning produce two) that generates the input string. Check via DP. Violation: no such sequence exists."
    },
    {
      "name": "test_line_count",
      "intent": "The number of lines in the output must equal the number of test cases t given in the input. Violation: line count differs."
    }
  ]
}

