    {
      "name": "test_separated",
      "intent": "Translating the second polygon far away (e.g., by adding (10^7,10^7,10^7) to each vertex) must result in 'NO', as the polygons are clearly not connected. A 'YES' output is wrong."
    },
    {
      "name": "test_coplanar_implies_no",
