    {
      "name": "test_one_group_count",
      "intent": "For i=1, the number of arrangements with exactly one blue group must equal N‑K+1 modulo 10^9+7, because the contiguous block of K blue balls can start at any of N‑K+1 positions. A violation is a different value."
    },
    {
      "name": "test_max_groups_count",
      "intent": "For i=K, the number of arrangements with exactly K blue groups (each blue isolated) must equal C(N‑K+1, K) modulo 10^9+7. A violation is a different value."
    },
    {
      "name": "test_total_sum",
      "intent": "The sum of all output values modulo 10^9+7 must equal the total number of arrangements of K blue balls among N balls, which is C(N, K) modulo 10^9+7. A violation is a mismatch in the sum."
    },
    {
      "name": "test_small_brute_force",
      "intent": "For N ≤ 15, enumerate all subsets of K positions (blue balls) and count the number of blue groups for each arrangement. Compare the resulting counts modulo 10^9+7 with the program's output. A violation is any discrepancy."
    },
    {
      "name": "test_two_groups_count",
      "intent": "For i=2, the number of arrangements with exactly two blue groups must equal (K‑1) * C(N‑K+1, 2) modulo 10^9+7, provided that 2 ≤ min(K, N‑K+1); otherwise it must be 0. A violation is a different value."
    },
    {
      "name": "test_special_cases",
      "intent": "If K=1, the output must be a single line with value N modulo 10^9+7. If N=K, the output must have the first line 1 and all other lines 0. A violation is any deviation from these expectations."
    },
    {
      "name": "test_max_i_count",
      "intent": "For i = min(K, N‑K+1) (the maximum possible number of groups), the output must equal C(K‑1, i‑1) * C(N‑K+1, i) modulo 10^9+7. A violation is a different value."
    }
  ]
}

{
  "rationale": "The tests target properties that any correct solution must satisfy, derived from the specification: blocks are independent (permutation, split, decomposition, duplication), zero output iff some block has no valid numbers (zero-equivalence), non-zero output implies existence of a witness, known answer for a_i=1, and output bounds. These catch miscalculations in per-block counts, floating-point errors in ceil, and multiplicative errors. The weakest test is boundedness (test_bounds), which only checks the output range and would be dropped first.",
  "plan": [
    {
      "name": "test_permutation",
      "intent": "Randomly permute the sequences a and b together. The output must remain unchanged because the total count is the product of per-block counts, which is commutative."
    },
    {
      "name": "test_split_first_block",
      "intent": "If there are at least two blocks, split the input into two valid inputs: first block only (n=k) and the remaining blocks (n=n-k). The product of the outputs for these two inputs modulo 10^9+7 must equal the original output, due to independence of blocks."
    },
    {
      "name": "test_zero_equivalence",
      "intent": "For each block, determine whether there exists at least one valid number (divisible by a_i and not starting with b_i). Assert that the original output is zero if and only if some block has no valid number, because the product modulo 10^9+7 is zero only when a factor is zero."
    },
    {
      "name": "test_witness",
      "intent": "If the original output is non-zero, for each block find one valid number (e.g., by checking multiples of a_i outside the forbidden range) and concatenate them to form a phone number. Verify that this phone number satisfies all block conditions, proving the count is at least one."
    },
    {
      "name": "test_decompose_single_blocks",
      "intent": "If the number of blocks is at most 10, run the program on each block individually (with n=k) and compute the product of their outputs modulo 10^9+7. Assert that this product equals the original output, as the total count is the product of independent block counts."
    },
    {
      "name": "test_all_ones",
      "intent": "Create a modified input where all a_i are set to 1 (keeping b_i, n, k unchanged). Compute the expected output as (10^k - 10^(k-1))^(n/k) modulo 10^9+7. Run the program on this input and assert equality, since for a_i=1 every number is divisible and the only constraint is the first digit."
    },
    {
      "name": "test_duplication",
      "intent": "Create a new input by duplicating the sequences a and b (so n'=2n, a'=a+a, b'=b+b). Run the program on this input and assert that its output equals the square of the original output modulo 10^9+7, because the number of good phone numbers for the duplicated input is the square of the original."
    },
    {
      "name": "test_reverse",
      "intent": "Reverse the order of the sequences a and b. Assert that the output is unchanged, as block order does not affect the product of per-block counts."
    },
    {
      "name": "test_bounds",
      "intent": "Assert that the output is an integer between 0 and 10^9+6 inclusive, as required by the modulo operation."
    },
    {
      "name": "test_sort_by_a",
      "intent": "Sort the blocks by a_i in ascending order (and correspondingly b_i). Assert that the output is unchanged, because the product of per-block counts is independent of the order of the blocks."
    }
  ]
}

{
  "rationale": "The tests combine basic invariants, certificates that the output satisfies the problem constraints, a lower bound based on pure prefix/suffix matches, special cases (b is a subsequence of a, disjoint character sets), and two metamorphic relations (reverse and filtered a). These catch errors such as the backdoor that reduces suffix length incorrectly, as they would violate the reverse relation or the lower bound. The filtered a test ensures irrelevant characters in a do not affect the answer. We would drop test_filtered_a first if needed, as it is more complex and may have edge cases.",
  "plan": [
    {
      "name": "test_reverse",
      "intent": "When the input strings are reversed, the output must be the reverse of the original output, because the operation is symmetric under reversal. A violation is that running the program on the reversed input yields a string not equal to the reverse of the original output."
    },
    {
      "name": "test_subsequence",
      "intent": "The output string must be a subsequence of the first input string a. This can be verified by a greedy scan. A violation is that the output cannot be matched as a subsequence of a in order."
    },
    {
      "name": "test_consecutive_deletion",
      "intent": "The output must be obtainable from the second input string b by deleting a single consecutive block. That is, there exists an index i such that the output equals b[:i] + b[-(len(output)-i):] and i + len(output) <= len(b). A violation is that no such i exists."
    },
    {
      "name": "test_lower_bound",
      "intent": "The length of the output must be at least the maximum of the lengths of the longest prefix of b that is a subsequence of a and the longest suffix of b that is a subsequence of a. These lengths are computed by greedy matching. A violation is that the output is shorter than this maximum."
    },
    {
      "name": "test_b_subsequence",
      "intent": "If b is already a subsequence of a (verified by greedy matching), then no characters need be removed, so the output must equal b. A violation is that b is a subsequence of a but the output differs from b."
    },
    {
      "name": "test_disjoint",
      "intent": "If the sets of characters in a and b are disjoint (no common letters), then no non‑empty subsequence can be formed, so the output must be exactly '-'. A violation is that the sets are disjoint but the output is not '-'."
    },
    {
      "name": "test_format",
      "intent": "The output must be either exactly '-' or a string consisting only of lowercase English letters. A violation is any other form, such as an empty string, extra whitespace, or invalid characters."
    },
    {
      "name": "test_length_bound",
      "intent": "The length of the output cannot exceed the length of a nor the length of b, because it is a subsequence of a and obtained from b by deletion. A violation is that the output is longer than either a or b."
    },
    {
      "name": "test_filtered_a",
      "intent": "Removing from a all characters that do not appear in b should not change the answer. Let a' be a with only characters that are in b. If a' is nonempty, run the program on (a', b) and assert the output equals the original. If a' is empty, assert the original output is '-'. A violation is a mismatch or incorrect empty output."
    },
    {
      "name": "test_chars_in_a",
      "intent": "Every character in the output must appear in a, because the output is a subsequence of a. This is a quick subset check. A violation is an output character not found in a."
