def test_subsequence(run, x):
    a, b = x.strip().split('\n')
    out = run(x).strip()
    if out == '-':
        return
    i = 0
    for ch in out:
        while i < len(a) and a[i] != ch:
            i += 1
        if i == len(a):
            assert False, f"output '{out}' not a subsequence of a='{a}'"
        i += 1

def test_consecutive_removal(run, x):
    a, b = x.strip().split('\n')
    out = run(x).strip()
    if out == '-':
        out = ''
    # check if out can be obtained from b by removing a single consecutive block
    found = False
    for i in range(len(b)+1):
        for j in range(i, len(b)+1):
            if b[:i] + b[j:] == out:
                found = True
                break
        if found:
            break
    assert found, f"output '{out}' cannot be obtained from b='{b}' by removing one consecutive block"

def test_length_bounds(run, x):
    a, b = x.strip().split('\n')
    out = run(x).strip()
    if out == '-':
        out_len = 0
    else:
        out_len = len(out)
    max_len = min(len(a), len(b))
    assert 0 <= out_len <= max_len, f"output length {out_len} not in [0, {max_len}]"

def test_chars_in_intersection(run, x):
    a, b = x.strip().split('\n')
    out = run(x).strip()
    if out == '-':
        return
    set_a = set(a)
    set_b = set(b)
    for ch in out:
        assert ch in set_a and ch in set_b, f"character '{ch}' in output not in both a and b"

def test_reversal_invariance(run, x):
    a, b = x.strip().split('\n')
    out = run(x).strip()
