    else:
        rev_len = len(rev_out)
    assert out_len == rev_len, f"output length {out_len} != reversed length {rev_len}"
    # also check rev_out is a subsequence of reversed a and obtainable from reversed b by one block removal
    if rev_out != '-':
        i = 0
        for ch in rev_out:
            while i < len(a) and a[::-1][i] != ch:
                i += 1
            if i == len(a):
                assert False, f"reversed output not subsequence of reversed a"
            i += 1
        found = False
        rb = b[::-1]
        for i2 in range(len(rb)+1):
            for j2 in range(i2, len(rb)+1):
                if rb[:i2] + rb[j2:] == rev_out:
                    found = True
                    break
            if found:
                break
        assert found, f"reversed output not obtainable from reversed b by one consecutive block"

