                for i2 in range(len(new_b)+1):
                    for j2 in range(i2, len(new_b)+1):
                        if new_b[:i2] + new_b[j2:] == new_out:
                            found = True
                            break
                    if found:
                        break
                assert found, f"new output not obtainable from new b by one consecutive block"
            return
    # no such character, pass

def test_remove_char_a_not_in_b(run, x):
    a, b = x.strip().split('\n')
    set_b = set(b)
    for idx, ch in enumerate(a):
        if ch not in set_b:
            new_a = a[:idx] + a[idx+1:]
            if new_a == '':
                return  # modification invalid (a would be empty), skip
            new_input = new_a + '\n' + b + '\n'
            orig_out = run(x).strip()
            orig_len = 0 if orig_out == '-' else len(orig_out)
            new_out = run(new_input).strip()
            new_len = 0 if new_out == '-' else len(new_out)
            assert orig_len == new_len, f"removing char '{ch}' from a changed output length from {orig_len} to {new_len}"
            # also verify new_out is valid for new_input
            if new_out != '-':
                i = 0
                for ch2 in new_out:
                    while i < len(new_a) and new_a[i] != ch2:
                        i += 1
                    if i == len(new_a):
                        assert False, f"new output not subsequence of new a"
                    i += 1
                found = False
                for i2 in range(len(b)+1):
                    for j2 in range(i2, len(b)+1):
                        if b[:i2] + b[j2:] == new_out:
                            found = True
                            break
                    if found:
                        break
                assert found, f"new output not obtainable from b by one consecutive block"
            return
    # no such character, pass

def test_local_optimality(run, x):
    a, b = x.strip().split('\n')
    out = run(x).strip()
    if out == '-':
        out = ''
    if out == b:
        return  # nothing removed, trivially optimal
    # find a split (i,j) such that out == b[:i] + b[j:]
    found_split = None
    for i in range(len(b)+1):
        for j in range(i, len(b)+1):
            if b[:i] + b[j:] == out:
                found_split = (i, j)
                break
        if found_split:
            break
    if found_split is None:
        return  # already caught by test_consecutive_removal
    i, j = found_split
    # try extending prefix: if i < j, b[i] is removed; check if b[:i+1] + b[j:] is a subsequence of a
    if i < j:
        extended = b[:i+1] + b[j:]
        # check subsequence
        idx = 0
        ok = True
        for ch in extended:
            while idx < len(a) and a[idx] != ch:
                idx += 1
            if idx == len(a):
                ok = False
                break
            idx += 1
        assert not ok, f"output can be extended by adding removed character b[{i}]='{b[i]}' and still be subsequence"
    # try extending suffix: if j > i, b[j-1] is removed; check if b[:i] + b[j-1:] is a subsequence of a
    if j > i:
        extended = b[:i] + b[j-1:]
        idx = 0
        ok = True
        for ch in extended:
            while idx < len(a) and a[idx] != ch:
                idx += 1
            if idx == len(a):
                ok = False
                break
            idx += 1
        assert not ok, f"output can be extended by adding removed character b[{j-1}]='{b[j-1]}' and still be subsequence"

def test_empty_iff_no_common_chars(run, x):
    a, b = x.strip().split('\n')
    out = run(x).strip()
    common = set(a) & set(b)
    if out == '-':
        assert len(common) == 0, f"output is '-' but there are common characters: {common}"
    else:
        assert len(common) > 0, f"output is non‑empty but there are no common characters"

def test_at_least_greedy(run, x):
    a, b = x.strip().split('\n')
    out = run(x).strip()
    out_len = 0 if out == '-' else len(out)
    # longest prefix of b that is subsequence of a
    i = 0
    prefix_len = 0
    for ch in b:
        while i < len(a) and a[i] != ch:
            i += 1
        if i == len(a):
            break
        i += 1
        prefix_len += 1
    # longest suffix of b that is subsequence of a
    i = len(a) - 1
    suffix_len = 0
    for ch in reversed(b):
        while i >= 0 and a[i] != ch:
            i -= 1
        if i < 0:
            break
        i -= 1
        suffix_len += 1
    best_greedy = max(prefix_len, suffix_len)
    assert out_len >= best_greedy, f"output length {out_len} < greedy achievable length {best_greedy}"

