{
  "rationale": "Each test implements the plan's intent strictly using property checks justified by the specification. Where an intent required knowledge of the submission's internal logic (e.g., monotonicity under expansion), it's implemented as a metamorphic relation only when the modified input is valid and the relation follows directly from the problem's definition (the count of multiples in an interval cannot decrease when the interval expands). For intents that are inherently about the output format or bounds, they are implemented as invariants or boundedness checks. The 'test_monotonic_k' intent is weakened to a bound check because the specification does not guarantee monotonicity in k for arbitrary intervals—only that a larger divisor cannot produce more multiples, which is a logical necessity. All tests avoid computing the correct answer; they rely only on input-output relations, format, and logical constraints. If I had to drop one, I'd drop test_scaling because it depends on a scaling relation that is not explicitly guaranteed by the specification for arbitrary intervals (multiples of scaled intervals align only if the scaling preserves divisibility exactly, which is not assured for all inputs). However, the plan includes it, so I implement it strictly as written, but note it could raise false alarms on correct solutions if the scaling does not preserve the count.",
  "tests": [
    {
      "name": "test_non_negative",
      "source": "def test_non_negative(run, x):
    k_str, a_str, b_str = x.strip().split()
    k, a, b = int(k_str), int(a_str), int(b_str)
    if k >= 1 and a <= b:
        output = run(x).strip()
        value = int(output)
        assert value >= 0"
    },
    {
      "name": "test_upper_bound",
      "source": "def test_upper_bound(run, x):
    k_str, a_str, b_str = x.strip().split()
    k, a, b = int(k_str), int(a_str), int(b_str)
    if k >= 1 and a <= b:
        bound = (b - a) // k + 1  # maximum possible multiples if every k-step fits
        output = run(x).strip()
        value = int(output)
        assert value <= bound"
    },
    {
      "name": "test_output_format",
      "source": "def test_output_format(run, x):
    import re
    output = run(x)
    assert re.fullmatch(r'-?\d+\n', output), "Output must be an integer followed by newline"
    # Ensure it's a valid integer within Python's range (though problem uses up to 10^18)
    int(output.strip())  # Will raise ValueError if not parseable"
    },
    {
      "name": "test_monotonic_expansion",
      "source": "def test_monotonic_expansion(run, x):
    k_str, a_str, b_str = x.strip().split()
    k, a, b = int(k_str), int(a_str), int(b_str)
    if k >= 1 and a <= b:
        if a - 1 >= -10**18 and b + 1 <= 10**18:
            expanded_input = f"{k} {a-1} {b+1}\n"
            orig_out = int(run(x).strip())
            expanded_out = int(run(expanded_input).strip())
            assert expanded_out >= orig_out, "Expanding interval should not decrease count""
    },
    {
      "name": "test_splitting",
      "source": "def test_splitting(run, x):
    k_str, a_str, b_str = x.strip().split()
    k, a, b = int(k_str), int(a_str), int(b_str)
    if k >= 1 and a < b:
        c = (a + b) // 2
        left_input = f"{k} {a} {c}\n"
        right_input = f"{k} {c+1} {b}\n"
        orig_out = int(run(x).strip())
        left_out = int(run(left_input).strip())
        right_out = int(run(right_input).strip())
        assert orig_out == left_out + right_out, "Count over whole interval should equal sum of counts over disjoint subintervals""
    },
    {
      "name": "test_shift_by_k",
      "source": "def test_shift_by_k(run, x):
    k_str, a_str, b_str = x.strip().split()
    k, a, b = int(k_str), int(a_str), int(b_str)
    if k >= 1:
        if a + k >= -10**18 and b + k <= 10**18:
            shifted_input = f"{k} {a+k} {b+k}\n"
            orig_out = int(run(x).strip())
            shifted_out = int(run(shifted_input).strip())
            assert orig_out == shifted_out, "Shifting interval by k should preserve count"
        elif a - k >= -10**18 and b - k <= 10**18:
            shifted_input = f"{k} {a-k} {b-k}\n"
            orig_out = int(run(x).strip())
            shifted_out = int(run(shifted_input).strip())
            assert orig_out == shifted_out, "Shifting interval by -k should preserve count""
    },
    {
      "name": "test_scaling",
      "source": "def test_scaling(run, x):
    k_str, a_str, b_str = x.strip().split()
    k, a, b = int(k_str), int(a_str), int(b_str)
    if k >= 1 and 2 * k <= 10**18:
        if 2 * a >= -10**18 and 2 * b <= 10**18:
            scaled_input = f"{2*k} {2*a} {2*b}\n"
            orig_out = int(run(x).strip())
            scaled_out = int(run(scaled_input).strip())
            assert orig_out == scaled_out, "Doubling k, a, b should preserve count (since x divisible by k iff 2x divisible by 2k)""
    },
    {
      "name": "test_trivial_bound",
      "source": "def test_trivial_bound(run, x):
    k_str, a_str, b_str = x.strip().split()
    k, a, b = int(k_str), int(a_str), int(b_str)
    if k >= 1 and a <= b:
        output = run(x).strip()
        value = int(output)
        assert value <= b - a + 1, "Count cannot exceed number of integers in [a,b]""
    },
    {
      "name": "test_monotonic_k",
      "source": "def test_monotonic_k(run, x):
    k_str, a_str, b_str = x.strip().split()
    k, a, b = int(k_str), int(a_str), int(b_str)
    if k >= 1 and 2 * k <= 10**18:
        larger_input = f"{2*k} {a} {b}\n"
        orig_out = int(run(x).strip())
        larger_out = int(run(larger_input).strip())
        assert larger_out <= orig_out, "With larger divisor, count cannot increase""
    },
    {
      "name": "test_lower_bound_if_divisible",
      "source": "def test_lower_bound_if_divisible(run, x):
    k_str, a_str, b_str = x.strip().split()
    k, a, b = int(k_str), int(a_str), int(b_str)
    if k >= 1 and a <= b:
        output = int(run(x).strip())
        # Use Python's % which yields non-negative remainder
        a_mod = a % k if a >= 0 else (k - (-a) % k) % k
        b_mod = b % k if b >= 0 else (k - (-b) % k) % k
        if a_mod == 0:
            assert output >= 1, "If a is divisible by k, count must be at least 1"
        if b_mod == 0:
            assert output >= 1, "If b is divisible by k, count must be at least 1""
    }
  ]
}

