def test_increment_one(run, x):
    n = int(x.strip())
    if n + 1 <= 10**18:
        out_n = int(run(x).strip())
        out_n1 = int(run(str(n+1)).strip())
        # Check if n+1 is divisible by any of 2,3,5,7
        divisible = any((n+1) % d == 0 for d in (2,3,5,7))
        if not divisible:
            assert out_n1 == out_n + 1, f"increment from {n} to {n+1}: expected +1, got {out_n1} vs {out_n}"
        else:
            assert out_n1 == out_n, f"increment from {n} to {n+1}: expected no change, got {out_n1} vs {out_n}"

def test_decrement_one(run, x):
    n = int(x.strip())
    if n >= 2:
        out_n = int(run(x).strip())
        out_nm1 = int(run(str(n-1)).strip())
        # Check if n is divisible by any of 2,3,5,7
        divisible = any(n % d == 0 for d in (2,3,5,7))
        if not divisible:
            assert out_n == out_nm1 + 1, f"decrement from {n-1} to {n}: expected +1, got {out_n} vs {out_nm1}"
        else:
            assert out_n == out_nm1, f"decrement from {n-1} to {n}: expected no change, got {out_n} vs {out_nm1}"

def test_increment_two(run, x):
    n = int(x.strip())
    if n + 2 <= 10**18:
        out_n = int(run(x).strip())
        out_n2 = int(run(str(n+2)).strip())
        # Count how many of n+1 and n+2 are not divisible by any of 2,3,5,7
        count = 0
        for i in (n+1, n+2):
            if not any(i % d == 0 for d in (2,3,5,7)):
                count += 1
        assert out_n2 - out_n == count, f"increment from {n} to {n+2}: expected difference {count}, got {out_n2 - out_n}"

def test_decrement_two(run, x):
