            if not any(i % d == 0 for d in (2,3,5,7)):
                count += 1
        assert out_n - out_nm2 == count, f"decrement from {n-2} to {n}: expected difference {count}, got {out_n - out_nm2}"

def test_lower_bound(run, x):
    n = int(x.strip())
    k = n // 210
    out = int(run(x).strip())
    # Each complete block of 210 numbers contains at least 48 numbers satisfying the condition
    assert out >= k * 48, f"lower bound: expected at least {k*48}, got {out}"

def test_upper_bound(run, x):
    n = int(x.strip())
    k = n // 210
    r = n % 210
    out = int(run(x).strip())
    # The remainder can have at most min(r, 48) numbers satisfying the condition
    assert out <= k * 48 + min(r, 48), f"upper bound: expected at most {k*48 + min(r, 48)}, got {out}"

def test_multiple_of_210_mod48(run, x):
    n = int(x.strip())
    if n % 210 == 0:
        out = int(run(x).strip())
        assert out % 48 == 0, f"multiple of 210: output {out} should be divisible by 48"

def test_monotonicity(run, x):
    n = int(x.strip())
    if n + 1 <= 10**18:
        out_n = int(run(x).strip())
        out_n1 = int(run(str(n+1)).strip())
        # The count cannot decrease when n increases
        assert out_n1 >= out_n, f"monotonicity: output decreased from {out_n} at n={n} to {out_n1} at n={n+1}"

def test_210_periodicity(run, x):
    n = int(x.strip())
    if n + 210 <= 10**18:
        out_n = int(run(x).strip())
        out_n210 = int(run(str(n+210)).strip())
        # The condition is periodic with period 210, so the count increases by exactly 48
        assert out_n210 == out_n + 48, f"periodicity: from n={n} to n+210 expected +48, got {out_n210 - out_n}"

def test_n_equal_one(run, x):
    n = int(x.strip())
    if n == 1:
        out = int(run(x).strip())
        assert out == 1, f"n=1: output must be 1, got {out}"

