{
  "rationale": "The tests combine basic sanity checks, bounds derived from the problem's geometry, consistency requirements across queries in the same connected component, and metamorphic relations that must hold for any correct solution. They target potential backdoors like incorrect component labeling, miscounted walls, or inconsistent handling of symmetric inputs. The weakest test is test_upper_bound_component_size because it uses a loose bound; if a test must be dropped, that one would be removed first.",
  "plan": [
    {
      "name": "test_output_length",
      "intent": "The output must contain exactly k integers, one per line. If the number of output lines differs from k, the answer is wrong."
    },
    {
      "name": "test_non_negative",
      "intent": "Each output integer must be non‑negative, since the number of pictures seen cannot be negative. A negative output is invalid."
    },
    {
      "name": "test_lower_bound_immediate_neighbors",
      "intent": "For each query (x,y), count how many of its four neighbouring cells are '*'. The output for that query must be at least that count, because Igor can always see those pictures from the starting cell itself."
    },
    {
      "name": "test_upper_bound_component_size",
      "intent": "For each query, perform a BFS (without counting '*') to find the size of the connected component of '.' cells containing it. The output cannot exceed four times that size, as each '.' cell can border at most four '*' cells."
    },
    {
      "name": "test_same_component_same_answer",
      "intent": "Precompute the connected components of '.' cells for the whole grid. All queries that lie in the same component must produce the same output value; if two queries in the same component yield different numbers, the answer is inconsistent."
    },
    {
      "name": "test_swap_queries_consistency",
      "intent": "Create a modified input by swapping the first and last query lines. Run the program on this input and compare the output to the original: the first and last output values must be swapped, and all others unchanged. Any deviation indicates an order‑sensitivity bug."
    },
    {
      "name": "test_duplicate_query_consistency",
      "intent": "Create a modified input by appending a copy of the first query line to the end. The new output must be the original output list with an extra value equal to the original first output. A mismatch shows incorrect handling of duplicate queries."
    },
    {
      "name": "test_reverse_queries_consistency",
      "intent": "Create a modified input by reversing the order of all query lines. The output must be exactly the reverse of the original output list. Failure means the program does not treat each query independently of order."
    },
    {
      "name": "test_horizontal_flip_invariance",
      "intent": "Create a modified input by flipping the museum grid horizontally (reversing each row) and transforming each query's column coordinate to y' = m+1-y. The output list must remain identical to the original, as the problem is symmetric under reflection."
    },
    {
      "name": "test_distinct_star_bound",
      "intent": "For each query, perform a BFS to find its connected component and collect the set of distinct '*' cells adjacent to any cell in the component. The output must be at least the size of this set (each such '*' cell contributes at least one picture) and at most four times its size (each '*' cell can border at most four '.' cells)."
