    },
    {
      "name": "test_total_turns",
      "intent": "The sum of all output numbers must equal the floor of the total sum of a_i divided by m. Parse the output into a list t and assert sum(t) == total_a // m."
    },
    {
      "name": "test_non_negative",
      "intent": "Every output number must be non‑negative. Parse the output into a list t and assert all(t_i >= 0 for t_i in t)."
    },
    {
