    out_lines = output.split('\n')
    # Ensure we have at least n lines (allow extra trailing newline)
    if len(out_lines) > n:
        out_lines = out_lines[:n]
    elif len(out_lines) < n:
        out_lines += [''] * (n - len(out_lines))
    waiting = set()
    expected = n
    for day in range(n):
        waiting.add(falls[day])
        placed = []
        while expected in waiting:
            placed.append(expected)
            waiting.remove(expected)
            expected -= 1
        # Construct expected line: placed numbers in decreasing order
