    a = list(map(int, lines[2].split()))
    b = list(map(int, lines[3].split()))
    out = run(x).strip()
    try:
        ans = int(out)
    except ValueError:
        raise AssertionError('Output not integer')
    if ans == -1:
        return
    # Check if b is a subsequence of a
    i = 0
    idx_map = {}
    for idx, v in enumerate(a):
        if i < m and v == b[i]:
            idx_map[i] = idx
            i += 1
    if i != m:
        # b not subsequence but ans != -1, contradiction, but we'll let other tests catch
        return
    # Split into segments: between matched indices, including boundaries
    segments = []
    prev = -1
    for j in range(m):
        cur = idx_map[j]
        if cur > prev + 1:
            segments.append((prev, cur, a[prev+1:cur]))
        prev = cur
    if prev + 1 < n:
        segments.append((prev, n, a[prev+1:n]))
    # For each segment
    for left_idx, right_idx, seg in segments:
        L = len(seg)
        if L == 0:
            continue
        M = max(seg)
        left_boundary = a[left_idx] if left_idx >= 0 else -1
        right_boundary = a[right_idx] if right_idx < n else -1
        if L < k:
            if M > left_boundary and M > right_boundary:
                # According to plan, this should be impossible, but specification does not guarantee?
                # The plan says if this happens, it's impossible, so output should be -1.
                # However, we already have ans != -1, so we raise.
                raise AssertionError('Segment with length < k and max greater than both boundaries should make answer -1')

def test_scaling(run, x):
    lines = x.strip().split('\n')
    if len(lines) < 4:
        return
    n_m = list(map(int, lines[0].split()))
    if len(n_m) != 2:
        return
    n, m = n_m[0], n_m[1]
    xk_line = list(map(int, lines[1].split()))
    if len(xk_line) != 3:
        return
    x_cost, k, y_cost = xk_line[0], xk_line[1], xk_line[2]
    # Check if doubling fits within bounds (1e9)
    if 2 * x_cost <= 10**9 and 2 * y_cost <= 10**9:
        new_x = 2 * x_cost
        new_y = 2 * y_cost
        # Build modified input
        modified = f'{n} {m}\n{new_x} {k} {new_y}\n{lines[2]}\n{lines[3]}'
        out1 = run(x).strip()
        out2 = run(modified).strip()
        try:
            val1 = int(out1)
            val2 = int(out2)
        except ValueError:
            raise AssertionError('Output not integer')
        if val1 == -1:
            if val2 != -1:
                raise AssertionError('Scaling: original -1 but modified not -1')
        else:
            if val2 != 2 * val1:
                raise AssertionError('Scaling: output not doubled when costs doubled')

