    x_cost, k, y_cost = xk_line[0], xk_line[1], xk_line[2]
    a = list(map(int, lines[2].split()))
    b = list(map(int, lines[3].split()))
    # Build sorted list of all values in a (distinct)
    sorted_vals = sorted(a)
    rank = {val: i+1 for i, val in enumerate(sorted_vals)}  # 1‑based rank
    a_rank = [rank[v] for v in a]
    b_rank = [rank[v] for v in b if v in rank]  # b values are guaranteed subset of a? Not necessarily, but if not, subsequence fails.
    # If b contains value not in a, the transformed input is invalid because b values must be distinct and ≤n, but rank mapping may produce duplicates? Actually, since all a are distinct, rank is bijection to 1..n. b values are subset of a values? Specification says b_i are distinct and ≤ n, but not necessarily subset of a. However, if a value not in a appears in b, the subsequence condition fails, but the transformed input would map it to something not in rank. To keep validity, we only apply transformation if every b value is in a.
    if len(b_rank) != m:
        # some b value not in a, then original input may be impossible; skip this test
        return
    modified = f'{n} {m}\n{x_cost} {k} {y_cost}\n{' '.join(map(str, a_rank))}\n{' '.join(map(str, b_rank))}'
    out1 = run(x).strip()
