def test_feasibility(run, x):
    lines = x.strip().split('\n')
    if len(lines) < 4:
        return
    n_m = list(map(int, lines[0].split()))
    if len(n_m) != 2:
        return
    n, m = n_m[0], n_m[1]
    xk_line = list(map(int, lines[1].split()))
    if len(xk_line) != 3:
        return
    x_cost, k, y_cost = xk_line[0], xk_line[1], xk_line[2]
    a = list(map(int, lines[2].split()))
    b = list(map(int, lines[3].split()))
    # Check if b is a subsequence of a
    i = 0
    idx_map = {}
    for idx, v in enumerate(a):
        if i < m and v == b[i]:
            idx_map[i] = idx
            i += 1
    if i != m:
        # b not subsequence
        out = run(x).strip()
        try:
            val = int(out)
        except ValueError:
            raise AssertionError('Output not integer')
        # If not subsequence, answer should be -1, but we don't assert that here (other test does)
        return
    # b is subsequence
    # Split into segments
    segments = []
    prev = -1
    for j in range(m):
        cur = idx_map[j]
        if cur > prev + 1:
            seg = a[prev+1:cur]
            segments.append((prev, cur, seg))
        prev = cur
    if prev + 1 < n:
        seg = a[prev+1:n]
        segments.append((prev, n, seg))
    feasible = True
    for left_idx, right_idx, seg in segments:
        L = len(seg)
        if L == 0:
            continue
        if L < k:
            M = max(seg)
            left_boundary = a[left_idx] if left_idx >= 0 else -1
            right_boundary = a[right_idx] if right_idx < n else -1
            if M > left_boundary and M > right_boundary:
                feasible = False
                break
    if feasible:
        out = run(x).strip()
        try:
            val = int(out)
        except ValueError:
            raise AssertionError('Output not integer')
        if val == -1:
            raise AssertionError('Feasible case should not output -1')

