      "name": "test_transpose_symmetry",
      "source": "def test_transpose_symmetry(run, x):
    n = int(x.strip())
    output = run(x)
    lines = output.strip().split('\n')
    for i in range(n):
        for j in range(n):
            assert lines[i][j] == lines[j][i], f'Transpose mismatch at ({i},{j})'"
    },
    {
      "name": "test_middle_row_all_D",
