tests_src:
def test_invariant_output_format(run, x):
    output = run(x)
    assert output in ('YES\n', 'NO\n'), f'Invalid output: {repr(output)}'

def test_yes_implies_existence_of_non_unique_switch(run, x):
    output = run(x)
    if output == 'YES\n':
        lines = x.strip().split('\n')
        n, m = map(int, lines[0].split())
        rows = lines[1:1+n]
        col_sums = [0]*m
        for r in rows:
            for j,ch in enumerate(r):
                if ch == '1':
                    col_sums[j] += 1
        ok = False
        for i in range(n):
            row = rows[i]
            only_switch = True
            for j,ch in enumerate(row):
                if ch == '1' and col_sums[j] == 1:
                    only_switch = False
                    break
            if only_switch:
                ok = True
                break
        assert ok, 'YES but every switch is unique for some lamp'

def test_no_implies_every_switch_unique_for_some_lamp(run, x):
    output = run(x)
    if output == 'NO\n':
        lines = x.strip().split('\n')
        n, m = map(int, lines[0].split())
        rows = lines[1:1+n]
        col_sums = [0]*m
        for r in rows:
            for j,ch in enumerate(r):
                if ch == '1':
                    col_sums[j] += 1
        for i in range(n):
            row = rows[i]
            found = False
            for j,ch in enumerate(row):
                if ch == '1' and col_sums[j] == 1:
                    found = True
                    break
            assert found, f'NO but switch {i+1} is not unique for any lamp'

def test_all_zero_row_implies_yes(run, x):
    lines = x.strip().split('\n')
    n, m = map(int, lines[0].split())
    rows = lines[1:1+n]
    for r in rows:
        if r == '0'*m:
            assert run(x) == 'YES\n', 'All-zero row exists but output is not YES'

def test_single_lamp_multiple_switches_implies_yes(run, x):
    lines = x.strip().split('\n')
    n, m = map(int, lines[0].split())
    if m == 1 and n >= 2:
        assert run(x) == 'YES\n', 'Single lamp with multiple switches but output not YES'

def test_single_switch_implies_no(run, x):
    lines = x.strip().split('\n')
    n, m = map(int, lines[0].split())
    if n == 1:
        assert run(x) == 'NO\n', 'Single switch but output is not NO'

def test_every_lamp_covered_by_at_least_two_switches_implies_yes(run, x):
    lines = x.strip().split('\n')
    n, m = map(int, lines[0].split())
    rows = lines[1:1+n]
    col_sums = [0]*m
    for r in rows:
        for j,ch in enumerate(r):
            if ch == '1':
                col_sums[j] += 1
    if all(cs >= 2 for cs in col_sums):
        assert run(x) == 'YES\n', 'Every lamp covered by at least two switches but output not YES'

def test_row_order_invariance(run, x):
    lines = x.strip().split('\n')
    n, m = map(int, lines[0].split())
    rows = lines[1:1+n]
    rev_rows = list(reversed(rows))
    new_input = f'{n} {m}\n' + '\n'.join(rev_rows) + '\n'
    out1 = run(x)
    out2 = run(new_input)
    assert out1 == out2, 'Row order changed the answer'

def test_column_order_invariance(run, x):
    lines = x.strip().split('\n')
    n, m = map(int, lines[0].split())
    rows = lines[1:1+n]
    rev_rows = [r[::-1] for r in rows]
    new_input = f'{n} {m}\n' + '\n'.join(rev_rows) + '\n'
    out1 = run(x)
    out2 = run(new_input)
    assert out1 == out2, 'Column order changed the answer'

def test_row_column_reversal_invariance(run, x):
    lines = x.strip().split('\n')
    n, m = map(int, lines[0].split())
    rows = lines[1:1+n]
    rev_rows = list(reversed(rows))
    rev_cols = [r[::-1] for r in rev_rows]
    new_input = f'{n} {m}\n' + '\n'.join(rev_cols) + '\n'
    out1 = run(x)
    out2 = run(new_input)
    assert out1 == out2, 'Row and column reversal changed the answer'

