tests_src:
def test_output_format(run, x):
    output = run(x)
    assert output in ('Yes\n', 'No\n'), f'Output must be Yes\\n or No\\n, got {repr(output)}'

def test_yes_certificate(run, x):
    a, b, c = map(int, x.strip().split())
    output = run(x)
    if output == 'Yes\n':
        found = False
        for xcnt in range(c // a + 1):
            rem = c - a * xcnt
            if rem >= 0 and rem % b == 0:
                found = True
                break
        assert found, f'Program said Yes but no non‑negative x,y satisfy {a}*x + {b}*y = {c}'

def test_divisible_by_a(run, x):
    a, b, c = map(int, x.strip().split())
    if c % a == 0:
        output = run(x)
        assert output == 'Yes\n', f'c={c} divisible by a={a}, must output Yes'

def test_divisible_by_b(run, x):
    a, b, c = map(int, x.strip().split())
    if c % b == 0:
        output = run(x)
        assert output == 'Yes\n', f'c={c} divisible by b={b}, must output Yes'

def test_a_eq_1(run, x):
    a, b, c = map(int, x.strip().split())
    if a == 1:
        output = run(x)
        assert output == 'Yes\n', f'a=1, any c must be achievable'

def test_b_eq_1(run, x):
    a, b, c = map(int, x.strip().split())
    if b == 1:
        output = run(x)
        assert output == 'Yes\n', f'b=1, any c must be achievable'

def test_swap_symmetry(run, x):
    a, b, c = map(int, x.strip().split())
    out1 = run(x)
    swapped_input = f'{b} {a} {c}\n'
    out2 = run(swapped_input)
    assert out1 == out2, f'Swapping a and b changed output: {out1} vs {out2}'

def test_yes_increment_a(run, x):
    a, b, c = map(int, x.strip().split())
    output = run(x)
    if output == 'Yes\n' and c + a <= 10000:
        new_input = f'{a} {b} {c + a}\n'
        new_output = run(new_input)
        assert new_output == 'Yes\n', f'Adding a to c should keep answer Yes'

def test_yes_increment_b(run, x):
    a, b, c = map(int, x.strip().split())
    output = run(x)
    if output == 'Yes\n' and c + b <= 10000:
        new_input = f'{a} {b} {c + b}\n'
        new_output = run(new_input)
        assert new_output == 'Yes\n', f'Adding b to c should keep answer Yes'

def test_frobenius_coprime(run, x):
    import math
    a, b, c = map(int, x.strip().split())
    if math.gcd(a, b) == 1 and c > a * b - a - b:
        output = run(x)
        assert output == 'Yes\n', f'gcd=1 and c>{a*b-a-b}, Frobenius guarantees Yes'

