    # only run brute force if n <= 5 and all values <= 5
    if n > 5 or any(v > 5 for v in a):
        return
    # compute winner by exhaustive search
    from functools import lru_cache
    @lru_cache(maxsize=None)
    def winner(state):
        # state is sorted tuple of pile sizes
        if all(v == 0 for v in state):
            return 'cslnb'  # previous player just took last stone?
        # check if any move leads to losing position for opponent
        for i, val in enumerate(state):
