tests_src:
def test_output_format(run, x):
    out = run(x)
    stripped = out.rstrip()
    assert stripped in ('Yes', 'No'), f'Output must be "Yes" or "No", got {repr(stripped)}'

def test_yes_certificate(run, x):
    out = run(x).rstrip()
    if out == 'Yes':
        a_str, b_str, c_str = x.strip().split()
        a, b, c = map(int, (a_str, b_str, c_str))
        for xc in range(0, c // a + 1):
            rem = c - a * xc
            if rem >= 0 and rem % b == 0:
                break
        else:
            raise AssertionError('Output is "Yes" but no non‑negative solution exists')

def test_no_certificate(run, x):
    out = run(x).rstrip()
    if out == 'No':
        a_str, b_str, c_str = x.strip().split()
        a, b, c = map(int, (a_str, b_str, c_str))
        for xc in range(0, c // a + 1):
            rem = c - a * xc
            if rem >= 0 and rem % b == 0:
                raise AssertionError('Output is "No" but a solution exists')

def test_symmetry(run, x):
    a_str, b_str, c_str = x.strip().split()
    swapped = f'{b_str} {a_str} {c_str}\n'
    out1 = run(x).rstrip()
    out2 = run(swapped).rstrip()
    assert out1 == out2, f'Symmetric inputs gave different outputs: {out1} vs {out2}'

def test_scaling_by_gcd(run, x):
    a_str, b_str, c_str = x.strip().split()
    a, b, c = map(int, (a_str, b_str, c_str))
    import math
    g = math.gcd(a, b)
    if g == 0:
        return
    if g > 1 and c % g == 0:
        a2, b2, c2 = a // g, b // g, c // g
        scaled = f'{a2} {b2} {c2}\n'
        out1 = run(x).rstrip()
        out2 = run(scaled).rstrip()
        assert out1 == out2, f'Scaling by gcd changed output: {out1} vs {out2}'

def test_divisible_by_a_or_b(run, x):
    a_str, b_str, c_str = x.strip().split()
    a, b, c = map(int, (a_str, b_str, c_str))
    out = run(x).rstrip()
    if c % a == 0 or c % b == 0:
        assert out == 'Yes', f'c divisible by a or b but output is {out}'

def test_gcd_does_not_divide(run, x):
    a_str, b_str, c_str = x.strip().split()
    a, b, c = map(int, (a_str, b_str, c_str))
    import math
    g = math.gcd(a, b)
    out = run(x).rstrip()
    if g > 0 and c % g != 0:
        assert out == 'No', f'gcd does not divide c but output is {out}'

def test_a_or_b_eq_one(run, x):
    a_str, b_str, c_str = x.strip().split()
    a, b, c = map(int, (a_str, b_str, c_str))
    out = run(x).rstrip()
    if a == 1 or b == 1:
        assert out == 'Yes', f'a or b is 1 but output is {out}'

def test_c_less_than_both(run, x):
    a_str, b_str, c_str = x.strip().split()
    a, b, c = map(int, (a_str, b_str, c_str))
    out = run(x).rstrip()
    if c < a and c < b:
        assert out == 'No', f'c < min(a,b) but output is {out}'

def test_add_lcm(run, x):
    a_str, b_str, c_str = x.strip().split()
    a, b, c = map(int, (a_str, b_str, c_str))
    import math
    out = run(x).rstrip()
    if out == 'Yes':
        lcm = a * b // math.gcd(a, b)
        if c + lcm <= 10000:
            new_c = c + lcm
            new_input = f'{a} {b} {new_c}\n'
            out2 = run(new_input).rstrip()
            assert out2 == 'Yes', f'Adding lcm changed Yes to {out2}'

