      "name": "test_minimality_among_divisors",
      "source": "def test_minimality_among_divisors(run, x):
    out = run(x).strip()
    if out == '-1':
        return
    b = int(out)
    n_str, s_str = x.strip().split()
    n = int(n_str)
    s = int(s_str)
    l = n - s
    # enumerate divisors up to sqrt(l) and check smaller bases
    import math
    checked = set()
    for d in range(1, int(math.isqrt(l)) + 1):
        if l % d == 0:
            for cand in (d, l // d):
                if cand + 1 < b and cand + 1 >= 2 and cand + 1 not in checked:
                    checked.add(cand + 1)
                    # compute digit sum in base cand+1
                    temp = n
                    total = 0
                    base = cand + 1
                    while temp:
                        total += temp % base
                        temp //= base
                    if n < base:
                        total = n
                    if total == s:
                        # found a smaller base, violates minimality
                        assert False, f'base {base} also gives digit sum {s}'"
    },
    {
      "name": "test_nonexistence_verification",
      "source": "def test_nonexistence_verification(run, x):
    out = run(x).strip()
    if out != '-1':
        return
    n_str, s_str = x.strip().split()
    n = int(n_str)
    s = int(s_str)
    l = n - s
    # If l == 0, special case: then n == s, but we already handled s == n case.
    # For l > 0, any valid base b must satisfy b-1 divides l.
    # Check all divisors up to sqrt(l) (since n ≤ 1e11, sqrt ≤ 1e5.5)
    import math
    for d in range(1, int(math.isqrt(l)) + 1):
        if l % d == 0:
            for cand in (d, l // d):
                b_cand = cand + 1
                if b_cand >= 2:
