def test_output_format(run, x):
    out = run(x).strip()
    if out == '-1':
        return
    # must be an integer >= 2
    try:
        b = int(out)
    except ValueError:
        assert False, f'Output "{out}" is not an integer'
    assert b >= 2, f'Output {b} is less than 2'

def test_n_minus_s_divisibility(run, x):
    out = run(x).strip()
    if out == '-1':
        return
    b = int(out)
    n, s = map(int, x.strip().split())
    if (n - s) % (b - 1) != 0:
        assert False, f'n-s={n-s} not divisible by b-1={b-1}'

def test_digit_sum_matches(run, x):
    out = run(x).strip()
    if out == '-1':
        return
    b = int(out)
    n, s = map(int, x.strip().split())
    # compute digit sum in base b
    total = 0
    m = n
    while m > 0:
        total += m % b
        m //= b
    assert total == s, f'Digit sum in base {b} is {total}, not {s}'

def test_minimality_among_divisors(run, x):
    out = run(x).strip()
    if out == '-1':
        return
    b = int(out)
    n, s = map(int, x.strip().split())
    diff = n - s
    if diff == 0:
        return  # handled by n_equals_s test
    # check divisors up to sqrt(diff)
    d = 1
    while d * d <= diff:
        if diff % d == 0:
            for cand_div in (d, diff // d):
                cand = cand_div + 1
                if 2 <= cand < b and cand <= n + 1:
                    # compute digit sum in base cand
                    total = 0
                    m = n
                    while m > 0:
                        total += m % cand
                        m //= cand
                    if total == s:
                        assert False, f'Smaller base {cand} also gives digit sum {s}'
        d += 1

def test_no_solution_for_minus_one(run, x):
    out = run(x).strip()
    if out != '-1':
        return
    n, s = map(int, x.strip().split())
    diff = n - s
    if diff == 0:
        # n == s => solution exists (base n+1), so -1 is wrong
        assert False, 'Solution exists (n == s) but output is -1'
    # check divisors up to sqrt(diff)
    d = 1
    while d * d <= diff:
        if diff % d == 0:
            for cand_div in (d, diff // d):
                cand = cand_div + 1
                if 2 <= cand <= n + 1:
                    total = 0
                    m = n
                    while m > 0:
                        total += m % cand
                        m //= cand
                    if total == s:
                        assert False, f'Solution exists in base {cand} but output is -1'
        d += 1

def test_n_equals_s(run, x):
    n, s = map(int, x.strip().split())
    if n == s:
        out = run(x).strip()
        assert out != '-1', 'Output is -1 when n == s (solution exists)'
        b = int(out)
        assert b == n + 1, f'When n == s, smallest base must be n+1, got {b}'

def test_s_greater_than_n(run, x):
    n, s = map(int, x.strip().split())
    if s > n:
        out = run(x).strip()
        assert out == '-1', f's > n but output is {out}, not -1'

def test_upper_bound(run, x):
    out = run(x).strip()
    if out == '-1':
        return
    b = int(out)
    n, s = map(int, x.strip().split())
    # smallest base cannot exceed n+1 (because base n+1 always works when s=n, and for s<n a smaller base may exist but cannot exceed n+1)
    assert b <= n + 1, f'Base {b} > n+1'

def test_digit_sum_upper_bound(run, x):
    out = run(x).strip()
    if out == '-1':
        return
    b = int(out)
    n, s = map(int, x.strip().split())
    if b <= n:
        # compute number of digits in base b
        import math
        if n == 0:
            k = 1
        else:
            k = math.floor(math.log(n, b)) + 1
        max_sum = (b - 1) * k
        assert s <= max_sum, f's={s} exceeds max possible digit sum {max_sum} in base {b}'

def test_s_range(run, x):
    out = run(x).strip()
    if out == '-1':
        return
    n, s = map(int, x.strip().split())
    assert 1 <= s <= n, f's={s} outside allowed range [1, n]'

