def test_positive_integers(run, x):
    out = run(x).strip().split()
    for s in out:
        val = int(s)
        if not (1 <= val <= 10**9):
            assert False, f"value {val} outside allowed range [1, 1e9]"

def test_swap_invariance(run, x):
    lines = x.strip().split('\n')
    n = int(lines[0])
    M = [list(map(int, line.split())) for line in lines[1:1+n]]
    # Build swapped matrix: swap rows 0 and 1, columns 0 and 1
    new_M = [[0]*n for _ in range(n)]
    for i in range(n):
        for j in range(n):
            ni = 1 if i == 0 else (0 if i == 1 else i)
            nj = 1 if j == 0 else (0 if j == 1 else j)
            new_M[ni][nj] = M[i][j]
    # Ensure diagonal is zero (should already hold)
    for i in range(n):
        new_M[i][i] = 0
    new_input = str(n) + '\n' + '\n'.join(' '.join(map(str, row)) for row in new_M) + '\n'
    out_orig = run(x).strip().split()
    out_new = run(new_input).strip().split()
    if len(out_orig) != n or len(out_new) != n:
        assert False, "output length mismatch after swap"
    # Expect out_new[0] == out_orig[1], out_new[1] == out_orig[0], others equal
