        assert False, 'not enough lines'
    k = int(out[0])
    suffixes = out[1:]
    assert len(suffixes) == k, f'expected {k} suffixes, got {len(suffixes)}'
    seen = set()
    prev = ''
    for s in suffixes:
        assert 2 <= len(s) <= 3, f'suffix length {len(s)} not 2 or 3'
        assert all('a' <= c <= 'z' for c in s), f'non-lowercase character'
        assert s not in seen, f'duplicate suffix {s}'
        seen.add(s)
        assert prev <= s, f'not lexicographically sorted: {prev} > {s}'
        prev = s

def test_substring(run, x):
    s = x.strip()
    out = run(x).strip().split('\n')
    if out == ['0']:
