    if n % 10 == 0:
        bound += 1
    out = int(run(x).strip())
    assert out <= bound, f'output for n={n} exceeds bound {bound}, got {out}'"
    },
    {
      "name": "test_monotonic_f",
      "source": "def test_monotonic_f(run, x):
    n = int(x.strip())
