    assert out_n >= out_fn, f'output for n={n} ({out_n}) < output for f(n)={y} ({out_fn})'"
    },
    {
      "name": "test_steps_certificate",
      "source": "def test_steps_certificate(run, x):
    n = int(x.strip())
    steps = 0
