tests_src:
def test_positive_integer(run, x):
    out = run(x).strip()
    assert out != ''
    val = int(out)
    assert val > 0

def test_lower_bound_N_minus_1(run, x):
    N = int(x.strip())
    out = int(run(x).strip())
    assert out >= N - 1

def test_upper_bound_harmonic(run, x):
    import math
    N = int(x.strip())
    out = int(run(x).strip())
    if N == 2:
        upper = 1
    else:
        upper = (N - 1) * (1 + math.log(N - 1))
    assert out <= int(upper) + 1  # add 1 for floating rounding

def test_monotonic_increase(run, x):
    N = int(x.strip())
    if N <= 2:
        return
    outN = int(run(x).strip())
    # get output for N-1
    inp_prev = str(N - 1) + '\n'
    out_prev = int(run(inp_prev).strip())
    assert outN > out_prev

def test_recurrence_1(run, x):
    import math
    N = int(x.strip())
    if N < 3:
        return
    outN = int(run(x).strip())
    inp_prev = str(N - 1) + '\n'
    out_prev = int(run(inp_prev).strip())
    # compute divisor count d(N-1)
    n1 = N - 1
    d = 0
    for i in range(1, int(math.isqrt(n1)) + 1):
        if n1 % i == 0:
            d += 1
            if i != n1 // i:
                d += 1
    assert outN == out_prev + d

def test_recurrence_2(run, x):
    import math
    N = int(x.strip())
    if N < 4:
        return
    outN = int(run(x).strip())
    inp_prev = str(N - 2) + '\n'
    out_prev = int(run(inp_prev).strip())
    # divisor counts of N-2, N-1
    total_d = 0
    for val in [N - 2, N - 1]:
        d = 0
        for i in range(1, int(math.isqrt(val)) + 1):
            if val % i == 0:
                d += 1
                if i != val // i:
                    d += 1
        total_d += d
    assert outN == out_prev + total_d

def test_recurrence_3(run, x):
    import math
    N = int(x.strip())
    if N < 5:
        return
    outN = int(run(x).strip())
    inp_prev = str(N - 3) + '\n'
    out_prev = int(run(inp_prev).strip())
    total_d = 0
    for val in [N - 3, N - 2, N - 1]:
        d = 0
        for i in range(1, int(math.isqrt(val)) + 1):
            if val % i == 0:
                d += 1
                if i != val // i:
                    d += 1
        total_d += d
    assert outN == out_prev + total_d

def test_recurrence_4(run, x):
    import math
    N = int(x.strip())
    if N < 6:
        return
    outN = int(run(x).strip())
    inp_prev = str(N - 4) + '\n'
    out_prev = int(run(inp_prev).strip())
    total_d = 0
    for val in range(N - 4, N):
        d = 0
        for i in range(1, int(math.isqrt(val)) + 1):
            if val % i == 0:
                d += 1
                if i != val // i:
                    d += 1
        total_d += d
    assert outN == out_prev + total_d

def test_recurrence_5(run, x):
    import math
    N = int(x.strip())
    if N < 7:
        return
    outN = int(run(x).strip())
    inp_prev = str(N - 5) + '\n'
    out_prev = int(run(inp_prev).strip())
    total_d = 0
    for val in range(N - 5, N):
        d = 0
        for i in range(1, int(math.isqrt(val)) + 1):
            if val % i == 0:
                d += 1
                if i != val // i:
                    d += 1
        total_d += d
    assert outN == out_prev + total_d

def test_lower_bound_divisor_sum_last_5(run, x):
    N = int(x.strip())
    if N < 6:
        return
    # compute exact formula: sum_{i=1}^{N-1} floor((N-1)/i)
    total = 0
    M = N - 1
    for i in range(1, M + 1):
        total += M // i
    out = int(run(x).strip())
    assert out == total

