tests_src:
def test_non_negative(run, x):
    n = int(x.strip())
    out = run(x)
    assert int(out.strip()) >= 0

def test_upper_bound(run, x):
    n = int(x.strip())
    # hex digit count: 1 for 0, else floor(log16(n)) + 1
    if n == 0:
        digits = 1
    else:
        # compute via bit length: log16(n) = log2(n)/4, so digits = floor(log2(n)/4) + 1
        import math
        digits = (n.bit_length() - 1) // 4 + 1
    out = run(x)
    val = int(out.strip())
    assert val <= 2 * digits

def test_single_digit_range(run, x):
    n = int(x.strip())
    if 0 <= n <= 15:
        out = run(x)
        val = int(out.strip())
        assert 0 <= val <= 2

def test_shift_left_one(run, x):
    n = int(x.strip())
    if n > 0 and 16 * n <= 2000000000:
        out1 = int(run(x).strip())
        out2 = int(run(str(16 * n)).strip())
        assert out2 == out1 + 1

def test_shift_left_plus_14(run, x):
    n = int(x.strip())
    if n > 0 and 16 * n + 14 <= 2000000000:
        out1 = int(run(x).strip())
        out2 = int(run(str(16 * n + 14)).strip())
        assert out2 == out1

def test_shift_left_plus_11(run, x):
    n = int(x.strip())
    if n > 0 and 16 * n + 11 <= 2000000000:
        out1 = int(run(x).strip())
        out2 = int(run(str(16 * n + 11)).strip())
        assert out2 == out1 + 2

def test_shift_left_two(run, x):
    n = int(x.strip())
    if n > 0 and 256 * n <= 2000000000:
        out1 = int(run(x).strip())
        out2 = int(run(str(256 * n)).strip())
        assert out2 == out1 + 2

def test_shift_left_three(run, x):
    n = int(x.strip())
    if n > 0 and 4096 * n <= 2000000000:
        out1 = int(run(x).strip())
        out2 = int(run(str(4096 * n)).strip())
        assert out2 == out1 + 3

def test_trailing_zero(run, x):
    n = int(x.strip())
    if n > 0 and n % 16 == 0:
        out1 = int(run(str(n // 16)).strip())
        out2 = int(run(x).strip())
        assert out2 == out1 + 1

def test_trailing_14(run, x):
    n = int(x.strip())
    if n > 0 and n % 16 == 14:
        out1 = int(run(str(n // 16)).strip())
        out2 = int(run(x).strip())
        assert out2 == out1

