def test_non_negative(run, x):
    out = run(x)
    val = int(out.strip())
    assert val >= 0

def test_upper_bound(run, x):
    out = run(x)
    val = int(out.strip())
    n = int(x.strip())
    d = 0
    t = n
    while t > 0:
        t //= 16
        d += 1
    if n == 0:
        d = 1  # zero has one hex digit '0'
    assert val <= 2 * d

def test_example_11(run, x):
    if x.strip() == "11":
        out = run(x)
        assert out.strip() == "2"

def test_example_14(run, x):
    if x.strip() == "14":
        out = run(x)
        assert out.strip() == "0"

def test_example_61441(run, x):
    if x.strip() == "61441":
        out = run(x)
        assert out.strip() == "2"

def test_example_571576(run, x):
    if x.strip() == "571576":
        out = run(x)
        assert out.strip() == "10"

def test_example_2128506(run, x):
    if x.strip() == "2128506":
        out = run(x)
        assert out.strip() == "3"

def test_recurrence(run, x):
    n = int(x.strip())
    if n > 0:
        q = n // 16
        r = n % 16
        out_n = int(run(x).strip())
        if q == 0:
            out_r = int(run(str(r)).strip())
            assert out_n == out_r
        else:
            out_q = int(run(str(q)).strip())
            out_r = int(run(str(r)).strip())
            assert out_n == out_q + out_r

def test_digit_sum(run, x):
    n = int(x.strip())
    digits = []
    t = n
    while t > 0:
        digits.append(t % 16)
        t //= 16
    if n == 0:
        digits = [0]
    out_n = int(run(x).strip())
    total = 0
    for d in digits:
        total += int(run(str(d)).strip())
    assert out_n == total

def test_shift_add(run, x):
    n = int(x.strip())
    MAX = 2000000000
    if n * 16 + 15 <= MAX:
        y = n * 16 + 15
        out_y = int(run(str(y)).strip())
        out_n = int(run(str(n)).strip())
        out_15 = int(run("15").strip())
        assert out_y == out_n + out_15
    elif n * 16 <= MAX:
        y = n * 16
        out_y = int(run(str(y)).strip())
        out_n = int(run(str(n)).strip())
        out_0 = int(run("0").strip())
        assert out_y == out_n + out_0

