    assert new_out == 'No', f'No turned to {new_out} when T decreased to 1'"
    },
    {
      "name": "test_monotonic_S_increase",
      "source": "def test_monotonic_S_increase(run, x):
    out = run(x).rstrip('\n\r ')
    if out != 'Yes':
        return
    D_str, T_str, S_str = x.strip().split()
    new_input = f'{D_str} {T_str} 10000\n'
    new_out = run(new_input).rstrip('\n\r ')
    assert new_out == 'Yes', f'Yes turned to {new_out} when S increased to 10000'"
    },
    {
      "name": "test_monotonic_S_decrease",
      "source": "def test_monotonic_S_decrease(run, x):
    out = run(x).rstrip('\n\r ')
    if out != 'No':
        return
    D_str, T_str, S_str = x.strip().split()
    new_input = f'{D_str} {T_str} 1\n'
    new_out = run(new_input).rstrip('\n\r ')
    assert new_out == 'No', f'No turned to {new_out} when S decreased to 1'"
    },
    {
      "name": "test_scaling_DT",
      "source": "def test_scaling_DT(run, x):
    D_str, T_str, S_str = x.strip().split()
    D, T = int(D_str), int(T_str)
    if 2 * D <= 10000 and 2 * T <= 10000:
        scaled = f'{2 * D} {2 * T} {S_str}\n'
    elif D % 2 == 0 and T % 2 == 0:
        scaled = f'{D // 2} {T // 2} {S_str}\n'
    else:
        return
    out1 = run(x).rstrip('\n\r ')
    out2 = run(scaled).rstrip('\n\r ')
