def test_certificate(run, x):
    parts = x.strip().split()
    D, T, S = map(int, parts)
    out = run(x)
    if out == 'Yes\n':
        assert D <= T * S
    elif out == 'No\n':
        assert D > T * S
    else:
        assert False, 'Invalid output format'

def test_output_format(run, x):
    out = run(x)
    assert out in ('Yes\n', 'No\n')

def test_scaling_2(run, x):
    parts = x.strip().split()
    D, T, S = map(int, parts)
    if 2 * D <= 10000 and 2 * S <= 10000:
        new_input = f'{2*D} {T} {2*S}\n'
        out_orig = run(x)
        out_scaled = run(new_input)
        assert out_orig == out_scaled

def test_scaling_4(run, x):
    parts = x.strip().split()
    D, T, S = map(int, parts)
    if 4 * D <= 10000 and 4 * S <= 10000:
        new_input = f'{4*D} {T} {4*S}\n'
        out_orig = run(x)
        out_scaled = run(new_input)
        assert out_orig == out_scaled

def test_monotonic_D_decrease(run, x):
    parts = x.strip().split()
    D, T, S = map(int, parts)
    if D > 1:
        new_input = f'{D-1} {T} {S}\n'
        out_orig = run(x)
        out_new = run(new_input)
        if out_orig == 'Yes\n':
            assert out_new == 'Yes\n'

def test_monotonic_D_increase(run, x):
    parts = x.strip().split()
    D, T, S = map(int, parts)
    if D < 10000:
        new_input = f'{D+1} {T} {S}\n'
        out_orig = run(x)
        out_new = run(new_input)
        if out_orig == 'No\n':
            assert out_new == 'No\n'

def test_monotonic_S_increase(run, x):
    parts = x.strip().split()
