    if S < 10000:
        new_input = f'{D} {T} {S+1}\n'
        out_orig = run(x)
        out_new = run(new_input)
        if out_orig == 'Yes\n':
            assert out_new == 'Yes\n'

def test_monotonic_S_decrease(run, x):
    parts = x.strip().split()
    D, T, S = map(int, parts)
