def test_brute_force(run, x):
    import itertools
    lines = x.strip().split('\n')
    H, W, K = map(int, lines[0].split())
    grid = [list(line.strip()) for line in lines[1:]]
    total = 0
    for rows in itertools.product([0, 1], repeat=H):
        for cols in itertools.product([0, 1], repeat=W):
            cnt = 0
            for i in range(H):
                if rows[i]:
                    continue
                for j in range(W):
                    if cols[j]:
                        continue
                    if grid[i][j] == '#':
                        cnt += 1
            if cnt == K:
                total += 1
    assert int(run(x).strip()) == total

def test_transpose_symmetry(run, x):
    lines = x.strip().split('\n')
    H, W, K = map(int, lines[0].split())
    grid = [list(line.strip()) for line in lines[1:]]
    # transpose
    new_lines = [f'{W} {H} {K}']
    for j in range(W):
        row = ''.join(grid[i][j] for i in range(H))
        new_lines.append(row)
    transposed_input = '\n'.join(new_lines) + '\n'
    out1 = run(x).strip()
    out2 = run(transposed_input).strip()
    assert out1 == out2

def test_sum_over_k(run, x):
    lines = x.strip().split('\n')
    H, W, K = map(int, lines[0].split())
    grid_lines = '\n'.join(lines[1:])
    total = 0
    for k in range(H*W + 1):
        new_input = f'{H} {W} {k}\n' + grid_lines + '\n'
        total += int(run(new_input).strip())
    assert total == 2**(H+W)

def test_bounds(run, x):
    lines = x.strip().split('\n')
    H, W, K = map(int, lines[0].split())
    out = int(run(x).strip())
    assert 0 <= out <= 2**(H+W)

def test_k_exceeds_total_black(run, x):
    lines = x.strip().split('\n')
    H, W, K = map(int, lines[0].split())
    grid = [list(line.strip()) for line in lines[1:]]
    total_black = sum(cell == '#' for row in grid for cell in row)
    if K > total_black:
        assert int(run(x).strip()) == 0

def test_all_white(run, x):
    lines = x.strip().split('\n')
    H, W, K = map(int, lines[0].split())
    grid = [list(line.strip()) for line in lines[1:]]
    if all(cell == '.' for row in grid for cell in row):
        out = int(run(x).strip())
        if K == 0:
            assert out == 2**(H+W)
        else:
            assert out == 0

def test_all_black(run, x):
    import itertools
    lines = x.strip().split('\n')
    H, W, K = map(int, lines[0].split())
    grid = [list(line.strip()) for line in lines[1:]]
    if all(cell == '#' for row in grid for cell in row):
        total = 0
        for rows in itertools.product([0, 1], repeat=H):
            for cols in itertools.product([0, 1], repeat=W):
                r = sum(rows)
                c = sum(cols)
                if (H - r) * (W - c) == K:
                    total += 1
        assert int(run(x).strip()) == total

def test_permutation_invariance(run, x):
    lines = x.strip().split('\n')
    H, W, K = map(int, lines[0].split())
    grid = [list(line.strip()) for line in lines[1:]]
    # reverse rows and columns
    rev_grid = [row[::-1] for row in grid[::-1]]
    new_lines = [f'{H} {W} {K}']
    for row in rev_grid:
        new_lines.append(''.join(row))
    rev_input = '\n'.join(new_lines) + '\n'
    out1 = run(x).strip()
    out2 = run(rev_input).strip()
    assert out1 == out2

def test_output_format(run, x):
    out = run(x)
    # must be a single integer, possibly with a trailing newline, no extra whitespace
    s = out.strip()
    assert s.isdigit() or (s == '0')
    # no extra characters before or after
    assert out == s + '\n' or out == s

def test_k_out_of_range(run, x):
    import itertools
    lines = x.strip().split('\n')
    H, W, K = map(int, lines[0].split())
    grid = [list(line.strip()) for line in lines[1:]]
    # compute min and max remaining black squares
    min_black = H*W  # start with all black, then minimize
    max_black = 0
    for rows in itertools.product([0, 1], repeat=H):
        for cols in itertools.product([0, 1], repeat=W):
            cnt = 0
            for i in range(H):
                if rows[i]:
                    continue
                for j in range(W):
                    if cols[j]:
                        continue
                    if grid[i][j] == '#':
                        cnt += 1
            if cnt < min_black:
                min_black = cnt
            if cnt > max_black:
                max_black = cnt
    out = int(run(x).strip())
    if K < min_black or K > max_black:
        assert out == 0

