def test_output_format(run, x):
    out = run(x)
    assert out in ('AC\n', 'WA\n'), 'Output must be exactly AC\n or WA\n'

def test_first_char(run, x):
    out = run(x)
    if out == 'AC\n':
        assert x[0] == 'A', 'If output is AC, first character must be A'

def test_one_c(run, x):
    out = run(x)
    if out == 'AC\n':
        uppercase_c_count = x.count('C')
        assert uppercase_c_count == 1, 'If output is AC, there must be exactly one uppercase C'

def test_c_not_second(run, x):
    out = run(x)
    if out == 'AC\n':
        assert len(x) >= 2 and x[1] != 'C', 'If output is AC, second character must not be C'

def test_c_not_last(run, x):
    out = run(x)
    if out == 'AC\n':
        assert x.rstrip('\n')[-1] != 'C', 'If output is AC, last character must not be C'

def test_uppercase_count(run, x):
    out = run(x)
    if out == 'AC\n':
        uppercase_count = sum(1 for ch in x if ch.isupper())
        assert uppercase_count == 2, 'If output is AC, there must be exactly two uppercase letters'

def test_other_lowercase(run, x):
    out = run(x)
    if out == 'AC\n':
        s = x.rstrip('\n')
        c_pos = s.find('C')
        for i, ch in enumerate(s):
            if i != 0 and i != c_pos:
                assert ch.islower(), f'If output is AC, character at index {i} must be lowercase'

def test_swap_first_c(run, x):
    out = run(x)
    if out == 'AC\n':
        s = x.rstrip('\n')
        c_pos = s.find('C')
        if 0 < c_pos < len(s):
            lst = list(s)
            lst[0], lst[c_pos] = lst[c_pos], lst[0]
            modified = ''.join(lst) + '\n'
            modified_out = run(modified)
            assert not (out == 'AC\n' and modified_out == 'AC\n'), 'Swapping first character with C should not both yield AC'

def test_uppercase_other(run, x):
    out = run(x)
    if out == 'AC\n':
        s = x.rstrip('\n')
        for i, ch in enumerate(s):
            if i != 0 and ch != 'C':
                lst = list(s)
                original = lst[i]
                lst[i] = 'X'  # change to another uppercase
                modified = ''.join(lst) + '\n'
                modified_out = run(modified)
                assert not (out == 'AC\n' and modified_out == 'AC\n'), f'Uppercasing character at {i} should not both yield AC'
                break

def test_c_position_range(run, x):
    out = run(x)
    if out == 'AC\n':
        s = x.rstrip('\n')
        c_pos = s.find('C')
        assert 2 <= c_pos <= len(s) - 2, 'If output is AC, C must be between index 2 and len(s)-2 inclusive'

