def test_yes_implies_swap_exists(run, x):
    out = run(x)
    if out != "YES\n":
        return
    # Parse input
    lines = x.strip().splitlines()
    if len(lines) < 2:
        return
    try:
        N = int(lines[0].strip())
        p = list(map(int, lines[1].split()))
    except:
        return
    if len(p) != N:
        return
    # Check if already sorted
    if all(p[i] == i+1 for i in range(N)):
        return  # OK
    # Try all swaps (including none? none would be sorted already, handled)
    found = False
    for i in range(N):
        for j in range(i+1, N):
            q = p.copy()
            q[i], q[j] = q[j], q[i]
            if all(q[k] == k+1 for k in range(N)):
                found = True
