    # Try all swaps
    for i in range(N):
        for j in range(i+1, N):
            q = p.copy()
            q[i], q[j] = q[j], q[i]
            if all(q[k] == k+1 for k in range(N)):
                assert False, f"Output NO but swapping ({i+1},{j+1}) sorts the permutation"


def test_small_n_exhaustive(run, x):
    # Only run on inputs with N <= 6 (since exhaustive up to 6! = 720 permutations is fine)
    lines = x.strip().splitlines()
    if len(lines) < 2:
        return
    try:
        N = int(lines[0].strip())
        p = list(map(int, lines[1].split()))
    except:
        return
    if len(p) != N:
        return
    if N > 6:
        return  # skip larger N
    # Generate all permutations of size N
    from itertools import permutations
    for perm in permutations(range(1, N+1)):
        # Build input string
        inp = f"{N}\n" + " ".join(map(str, perm)) + "\n"
        out = run(inp)
        # Check correctness: answer YES iff there exists a swap that sorts it (or already sorted)
        perm_list = list(perm)
        sorted_list = list(range(1, N+1))
        if perm_list == sorted_list:
            correct = "YES\n"
        else:
            ok = False
            for i in range(N):
                for j in range(i+1, N):
                    q = perm_list.copy()
                    q[i], q[j] = q[j], q[i]
                    if q == sorted_list:
                        ok = True
                        break
                if ok:
                    break
            correct = "YES\n" if ok else "NO\n"
        assert out == correct, f"For permutation {perm} got {repr(out)} expected {repr(correct)}"


def test_mismatch_count(run, x):
    lines = x.strip().splitlines()
    if len(lines) < 2:
        return
    try:
        N = int(lines[0].strip())
        p = list(map(int, lines[1].split()))
    except:
        return
    if len(p) != N:
        return
    mismatches = sum(1 for i in range(N) if p[i] != i+1)
    out = run(x)
    # Necessary conditions derived from spec: one swap fixes at most 2 mismatches.
    if mismatches == 0:
        assert out == "YES\n", f"Zero mismatches must output YES, got {repr(out)}"
    if mismatches >= 4:
        assert out == "NO\n", f"{mismatches} mismatches (>=4) must output NO, got {repr(out)}"


def test_two_symmetric_mismatch(run, x):
    lines = x.strip().splitlines()
    if len(lines) < 2:
        return
    try:
        N = int(lines[0].strip())
        p = list(map(int, lines[1].split()))
    except:
        return
    if len(p) != N:
        return
    # Find positions where p[i] != i+1
    mismatches = [i for i in range(N) if p[i] != i+1]
    if len(mismatches) != 2:
        return
    i, j = mismatches[0], mismatches[1]
    if p[i] == j+1 and p[j] == i+1:
        out = run(x)
        assert out == "YES\n", f"Symmetric two‑mismatch must output YES, got {repr(out)}"


def test_deterministic(run, x):
    out1 = run(x)
    out2 = run(x)
    assert out1 == out2, f"Two runs on same input gave different outputs: {repr(out1)} vs {repr(out2)}"


def test_valid_input_no_crash(run, x):
    # This test just ensures the program doesn't crash on valid input.
    # We consider an input valid if it meets constraints: N between 2 and 50, and p is a permutation of 1..N.
    lines = x.strip().splitlines()
    if len(lines) < 2:
        return  # Not a valid full input, but run might still handle; we don't want to crash test.
    try:
        N = int(lines[0].strip())
        p = list(map(int, lines[1].split()))
    except:
        return  # Not valid numbers, but we don't enforce here.
    if not (2 <= N <= 50):
        return
    if len(p) != N:
        return
    if set(p) != set(range(1, N+1)):
        return
    # If we got here, input is valid per spec.
    # Simply run and catch any exception.
    try:
        run(x)
    except Exception as e:
        assert False, f"Program crashed on valid input with exception: {e}"


def test_whitespace_invariance(run, x):
    # Normalize whitespace: collapse multiple spaces/tabs to single space, trim leading/trailing.
    lines = x.splitlines()
    if len(lines) < 2:
        return  # cannot normalize
    first = lines[0].strip()
    # second line: split on whitespace and rejoin with single space
    rest = " ".join(lines[1].split())
    normalized = first + "\n" + rest + "\n"
    out_orig = run(x)
    out_norm = run(normalized)
    assert out_orig == out_norm, f"Output differs after whitespace normalization: {repr(out_orig)} vs {repr(out_norm)}"

