def test_min_condition(run, x):
    S, T = x.strip().split('\n')
    out = run(x).strip()
    try:
        m = int(out)
    except ValueError:
        raise AssertionError('output not an integer')
    # compute min Hamming distance over all starting positions
    n, k = len(S), len(T)
    min_dist = k  # worst case
    for i in range(n - k + 1):
        d = sum(1 for j in range(k) if S[i + j] != T[j])
        if d < min_dist:
            min_dist = d
    # output must equal min_dist
    assert m == min_dist, f'output {m} does not equal minimal Hamming distance {min_dist}'

