tests_src:
def test_all_same_digits(run, x):
    n_str = run(x).strip()
    assert len(n_str) == 3 and n_str[0] == n_str[1] == n_str[2]

def test_ge_N(run, x):
    N = int(x.strip())
    n = int(run(x).strip())
    assert n >= N

def test_minimal_previous(run, x):
    n = int(run(x).strip())
    N = int(x.strip())
    if n > 111:
        prev = n - 111
        assert prev < N

def test_non_decreasing_forward(run, x):
    N = int(x.strip())
    if N < 999:
        n1 = int(run(x).strip())
        n2 = int(run(str(N+1)).strip())
        assert n2 >= n1

def test_non_decreasing_backward(run, x):
    N = int(x.strip())
    if N > 100:
        n1 = int(run(x).strip())
        n2 = int(run(str(N-1)).strip())
        assert n1 >= n2

def test_idempotence(run, x):
    n_str = run(x).strip()
    n2_str = run(n_str).strip()
    assert n2_str == n_str

def test_special_allsame(run, x):
    N = int(x.strip())
    if N % 111 == 0 and 100 <= N <= 999:
        n_str = run(x).strip()
        assert n_str == str(N)

def test_multiple_of_111(run, x):
    n = int(run(x).strip())
    assert n % 111 == 0

def test_range_111_999(run, x):
    n = int(run(x).strip())
    assert 111 <= n <= 999

def test_three_digits_no_leading_zeros(run, x):
    n_str = run(x).strip()
    assert len(n_str) == 3 and n_str.isdigit() and n_str[0] != '0'
    assert int(n_str) == int(run(x).strip())

