tests_src:
def test_valid_output(run, x):
    out = run(x).rstrip('\n')
    assert out in ('YYMM', 'MMYY', 'AMBIGUOUS', 'NA'), 'output must be one of the four allowed strings'

def test_YYMM_month_valid(run, x):
    out = run(x).rstrip('\n')
    if out == 'YYMM':
        month = int(x.strip()[2:])
        assert 1 <= month <= 12, 'last two digits must be a valid month for YYMM output'

def test_MMYY_month_valid(run, x):
    out = run(x).rstrip('\n')
    if out == 'MMYY':
        month = int(x.strip()[:2])
        assert 1 <= month <= 12, 'first two digits must be a valid month for MMYY output'

def test_AMBIGUOUS_both_valid(run, x):
    out = run(x).rstrip('\n')
    if out == 'AMBIGUOUS':
        m1 = int(x.strip()[:2])
        m2 = int(x.strip()[2:])
        assert 1 <= m1 <= 12 and 1 <= m2 <= 12, 'both two-digit parts must be valid months for AMBIGUOUS output'

def test_NA_neither_valid(run, x):
    out = run(x).rstrip('\n')
    if out == 'NA':
        m1 = int(x.strip()[:2])
        m2 = int(x.strip()[2:])
        assert not (1 <= m1 <= 12) and not (1 <= m2 <= 12), 'neither two-digit part may be a valid month for NA output'

def test_swap_consistency(run, x):
    s = x.strip()
    swapped = s[2:] + s[:2] + '\n'
    out1 = run(x).rstrip('\n')
    out2 = run(swapped).rstrip('\n')
    mapping = {'YYMM': 'MMYY', 'MMYY': 'YYMM', 'AMBIGUOUS': 'AMBIGUOUS', 'NA': 'NA'}
    assert out2 == mapping[out1], f'swapped input output {out2} does not match expected mapping from {out1}'

def test_symmetric_input(run, x):
    s = x.strip()
    if s[:2] == s[2:]:
        out = run(x).rstrip('\n')
        assert out in ('AMBIGUOUS', 'NA'), 'symmetric input cannot yield YYMM or MMYY'

def test_both_valid_not_NA(run, x):
    m1 = int(x.strip()[:2])
    m2 = int(x.strip()[2:])
    if 1 <= m1 <= 12 and 1 <= m2 <= 12:
        out = run(x).rstrip('\n')
        assert out != 'NA', 'both parts valid months ⇒ output cannot be NA'

def test_exactly_one_valid_not_AMBIGUOUS_or_NA(run, x):
    m1 = int(x.strip()[:2])
    m2 = int(x.strip()[2:])
    valid1 = 1 <= m1 <= 12
    valid2 = 1 <= m2 <= 12
    if valid1 != valid2:  # exactly one valid
        out = run(x).rstrip('\n')
        assert out in ('YYMM', 'MMYY'), f'exactly one valid month ⇒ output must be YYMM or MMYY, got {out}'

def test_neither_valid_is_NA(run, x):
    m1 = int(x.strip()[:2])
    m2 = int(x.strip()[2:])
    if not (1 <= m1 <= 12) and not (1 <= m2 <= 12):
        out = run(x).rstrip('\n')
        assert out == 'NA', 'neither part valid month ⇒ output must be NA'

