tests_src:
def test_bounds(run, x):
    out = run(x).strip()
    try:
        n = int(out)
    except ValueError:
        assert False, "output must be an integer"
    assert 0 <= n <= 3, "output must be between 0 and 3 inclusive"

def test_invariant(run, x):
    out = run(x).strip()
    try:
        n = int(out)
    except ValueError:
        assert False, "output must be an integer"
    assert n in {0, 1, 2, 3}, "output must be exactly one of 0,1,2,3"

def test_reversal(run, x):
    out1 = run(x).strip()
    # reverse the 3-character string (strip newline for reversal)
    s = x.strip()
    rev_s = s[::-1] + '\n'
    out2 = run(rev_s).strip()
    assert out1 == out2, f"reversed input gave {out2} != {out1}"

def test_monotonic_up(run, x):
    s = x.strip()
    out_orig = int(run(x).strip())
    for i, ch in enumerate(s):
        if ch == 'S':
            mod = s[:i] + 'R' + s[i+1:] + '\n'
            out_mod = int(run(mod).strip())
            assert out_mod >= out_orig, f"changing S at pos {i} to R decreased output"

def test_monotonic_down(run, x):
    s = x.strip()
    out_orig = int(run(x).strip())
    for i, ch in enumerate(s):
        if ch == 'R':
            mod = s[:i] + 'S' + s[i+1:] + '\n'
            out_mod = int(run(mod).strip())
            assert out_mod <= out_orig, f"changing R at pos {i} to S increased output"

def test_existence(run, x):
    s = x.strip()
    out = int(run(x).strip())
    if out == 0:
        assert 'R' not in s, "output 0 but input contains R"
    else:
        found = False
        for i in range(4 - out):
            if s[i:i+out] == 'R' * out:
                found = True
                break
        assert found, f"no contiguous substring of length {out} all R"

def test_maximality(run, x):
    s = x.strip()
    out = int(run(x).strip())
    if out < 3:
        for i in range(4 - (out+1)):
            if s[i:i+out+1] == 'R' * (out+1):
                assert False, f"found contiguous R substring of length {out+1} while output is {out}"
    # if out == 3, vacuously true

def test_output_3(run, x):
    s = x.strip()
    out = int(run(x).strip())
    if s == 'RRR':
        assert out == 3, "input is RRR but output is not 3"
    if out == 3:
        assert s == 'RRR', "output is 3 but input is not RRR"

def test_output_2(run, x):
    s = x.strip()
    out = int(run(x).strip())
    if 'RR' in s and 'RRR' not in s:
        assert out == 2, "input has RR but not RRR, output should be 2"
    if out == 2:
        assert 'RR' in s, "output is 2 but input lacks RR substring"
        assert 'RRR' not in s, "output is 2 but input contains RRR"

def test_output_1(run, x):
    s = x.strip()
    out = int(run(x).strip())
    if ('R' in s) and ('RR' not in s):
        assert out == 1, "input has R but no RR, output should be 1"
    if out == 1:
        assert 'R' in s, "output is 1 but input has no R"
        assert 'RR' not in s, "output is 1 but input contains RR"

