    },
    {
      "name": "test_metamorphic_append",
      "intent": "Append the sequence [4,8,15,16,23,42] to the input array to form a new valid input. Run the program on both the original and modified inputs, obtaining outputs r and r'. Since adding a complete sequence cannot increase the minimum number of removals needed, we must have r' <= r. A violation would be r' > r."
    },
    {
      "name": "test_metamorphic_prepend",
      "intent": "Prepend the sequence [4,8,15,16,23,42] to the input array to form a new valid input. Run the program on both, obtaining r and r'. Similarly, r' <= r must hold. A violation would be r' > r."
    },
    {
      "name": "test_small_bruteforce",
