}

{
  "rationale": "Each test corresponds to one intent from the plan, relying only on the specification. Where the plan required computing exact answers, we replaced with verifiable properties: bounds, divisibility, feasibility via greedy, and metamorphic relations justified by monotonicity (appending/prepending a full sequence cannot increase removals). For brute-force on small n (intent 8), we use exhaustive verification only when n ≤ 15. For optimality (intent 10), we check that k+1 sequences are not feasible using the greedy algorithm. All properties are decidable without knowing the correct answer.",
  "tests": [
    {
      "name": "test_nonnegative",
