    },
    {
      "name": "test_length_multiple_of_6",
      "source": "def test_length_multiple_of_6(run, x):
    lines = x.strip().split('\n')
    n = int(lines[0])
    out = run(x)
    r = int(out.strip())
    assert (n - r) % 6 == 0, f'remaining length {n-r} not divisible by 6'"
    },
    {
      "name": "test_lower_bound_freq",
      "source": "def test_lower_bound_freq(run, x):
    lines = x.strip().split('\n')
    if len(lines) < 2:
        a = []
    else:
        a = list(map(int, lines[1].split()))
    from collections import Counter
    cnt = Counter(a)
    min_freq = min(cnt.values()) if cnt else 0
    n = len(a)
    lower = n - 6 * min_freq
    out = run(x)
    r = int(out.strip())
    assert r >= lower, f'output {r} < lower bound {lower} from frequency'"
    },
    {
      "name": "test_upper_bound_greedy",
      "source": "def test_upper_bound_greedy(run, x):
    lines = x.strip().split('\n')
    if len(lines) < 2:
        a = []
    else:
        a = list(map(int, lines[1].split()))
    # greedy extraction of sequences
    seq = [4, 8, 15, 16, 23, 42]
    a_copy = a[:]
    sequences = 0
    while True:
        pos = -1
        ok = True
        for val in seq:
            pos = next((i for i in range(pos+1, len(a_copy)) if a_copy[i]==val), None)
            if pos is None:
                ok = False
                break
        if not ok:
            break
        # remove elements at indices found (from largest to smallest)
        removed = []
        for val in seq:
            for i in range(len(a_copy)):
                if a_copy[i] == val and i not in removed:
                    removed.append(i)
                    break
        removed.sort(reverse=True)
        for idx in removed:
            a_copy.pop(idx)
        sequences += 1
    upper = len(a) - 6 * sequences
    out = run(x)
    r = int(out.strip())
    assert r <= upper, f'output {r} > upper bound {upper} from greedy'"
    },
    {
      "name": "test_metamorphic_append",
      "source": "def test_metamorphic_append(run, x):
