        orig = ''
    else:
        orig = lines[1]
    # append full sequence
    added = '4 8 15 16 23 42'
    new_input = f'{n+6}\n{orig} {added}'.strip() if orig else f'{n+6}\n{added}'
    r = int(run(x).strip())
    r2 = int(run(new_input).strip())
    assert r2 <= r, f'append increased removals: {r2} > {r}'"
    },
    {
      "name": "test_metamorphic_prepend",
      "source": "def test_metamorphic_prepend(run, x):
    lines = x.strip().split('\n')
    n = int(lines[0])
    if len(lines) < 2:
        orig = ''
    else:
        orig = lines[1]
    added = '4 8 15 16 23 42'
    new_input = f'{n+6}\n{added} {orig}'.strip() if orig else f'{n+6}\n{added}'
    r = int(run(x).strip())
    r2 = int(run(new_input).strip())
    assert r2 <= r, f'prepend increased removals: {r2} > {r}'"
    },
    {
      "name": "test_small_bruteforce",
      "source": "def test_small_bruteforce(run, x):
    lines = x.strip().split('\n')
    n = int(lines[0])
    if n > 15:
        return  # skip, as per plan
    if len(lines) < 2:
        a = []
    else:
        a = list(map(int, lines[1].split()))
    seq = [4,8,15,16,23,42]
    best = 0
    from itertools import combinations
    for keep in range(0, n+1):
        for idxs in combinations(range(n), keep):
            kept = [a[i] for i in idxs]
            # check if kept can be partitioned into the required sequences
            cnt = {}
            for val in kept:
                cnt[val] = cnt.get(val,0)+1
            # necessary condition: equal counts of each number
            if len(set(cnt.values())) != 1:
                continue
            # try greedy left-to-right matching
            stages = [0,0,0,0,0,0]  # count of partial sequences at each stage
            for val in kept:
                pos = seq.index(val)
                if pos == 0:
                    stages[0] += 1
                else:
                    if stages[pos-1] > 0:
                        stages[pos-1] -= 1
                        stages[pos] += 1
            if stages[5] == keep//6:
                best = max(best, keep)
    expected = n - best
    out = run(x)
    r = int(out.strip())
    assert r == expected, f'brute force says {expected}, got {r}'"
    },
    {
      "name": "test_feasibility",
      "source": "def test_feasibility(run, x):
    lines = x.strip().split('\n')
    n = int(lines[0])
    if len(lines) < 2:
        a = []
    else:
        a = list(map(int, lines[1].split()))
    out = run(x)
    r = int(out.strip())
    k = (n - r) // 6
    # greedy feasibility check
    stages = [0,0,0,0,0,0]  # counts of partial sequences at each stage
    for val in a:
        if val == 4:
            stages[0] += 1
        elif val == 8:
            if stages[0] > 0:
                stages[0] -= 1
                stages[1] += 1
        elif val == 15:
            if stages[1] > 0:
                stages[1] -= 1
                stages[2] += 1
        elif val == 16:
            if stages[2] > 0:
                stages[2] -= 1
                stages[3] += 1
        elif val == 23:
            if stages[3] > 0:
                stages[3] -= 1
                stages[4] += 1
        elif val == 42:
            if stages[4] > 0:
                stages[4] -= 1
                stages[5] += 1
    assert stages[5] >= k, f'only {stages[5]} complete sequences, need {k}'"
    },
    {
      "name": "test_optimality",
      "source": "def test_optimality(run, x):
    lines = x.strip().split('\n')
    n = int(lines[0])
    if len(lines) < 2:
        a = []
    else:
        a = list(map(int, lines[1].split()))
    out = run(x)
    r = int(out.strip())
    k = (n - r) // 6
    # check that k+1 sequences is not feasible with greedy limited to k+1 starts
    max_start = k+1
    stages = [0,0,0,0,0,0]
    for val in a:
        if val == 4:
            if stages[0] + stages[1] + stages[2] + stages[3] + stages[4] + stages[5] < max_start:
                stages[0] += 1
        elif val == 8:
            if stages[0] > 0:
