def test_equation(run, x):
    a, b, c = map(int, x.strip().split())
    out = run(x)
    lines = out.strip().split('\n')
    if len(lines) == 0 or lines[0].strip() == '0':
        return
    n = int(lines[0])
    if len(lines) == 1:
        return
    nums = list(map(int, lines[1].split()))
    for val in nums:
        if not (0 < val < 10**9):
            continue
        s = sum(int(d) for d in str(val))
        if val != b * (s ** a) + c:
            assert False, f'Solution {val} fails equation'


def test_completeness(run, x):
    a, b, c = map(int, x.strip().split())
    out = run(x)
    lines = out.strip().split('\n')
    if len(lines) == 0:
        return
    n = int(lines[0])
    if n == 0:
        solutions = []
    else:
        solutions = list(map(int, lines[1].split()))
    for d in range(1, 82):
        cand = b * (d ** a) + c
        if 0 < cand < 10**9:
            if sum(int(dig) for dig in str(cand)) == d:
                if cand not in solutions:
                    assert False, f'Missing solution {cand}'


def test_increasing(run, x):
    out = run(x)
    lines = out.strip().split('\n')
    if len(lines) == 0 or lines[0].strip() == '0':
        return
    n = int(lines[0])
    if len(lines) < 2:
        return
    nums = list(map(int, lines[1].split()))
    for i in range(len(nums)-1):
        if nums[i] >= nums[i+1]:
            assert False, f'Not strictly increasing: {nums[i]} >= {nums[i+1]}'


def test_range(run, x):
    out = run(x)
    lines = out.strip().split('\n')
    if len(lines) == 0 or lines[0].strip() == '0':
        return
    n = int(lines[0])
    if len(lines) < 2:
        return
    nums = list(map(int, lines[1].split()))
    for val in nums:
        if not (0 < val < 10**9):
            assert False, f'Solution {val} out of range'


def test_count_match(run, x):
    out = run(x)
    lines = out.strip().split('\n')
    if len(lines) == 0:
        return
    n_line = lines[0].strip()
    n = int(n_line)
    if n == 0:
        if len(lines) != 1:
            assert False, 'Extra output when n=0'
    else:
        if len(lines) != 2:
            assert False, 'Expected exactly two lines'
        nums = list(map(int, lines[1].split()))
        if len(nums) != n:
            assert False, f'Count mismatch: expected {n} numbers, got {len(nums)}'


def test_max_solutions(run, x):
    out = run(x)
    lines = out.strip().split('\n')
    if len(lines) == 0:
        return
    n = int(lines[0].strip())
    if n > 81:
        assert False, f'Too many solutions: {n} > 81'


def test_digit_sum_range(run, x):
    out = run(x)
    lines = out.strip().split('\n')
    if len(lines) == 0 or lines[0].strip() == '0':
        return
    n = int(lines[0])
    if len(lines) < 2:
        return
    nums = list(map(int, lines[1].split()))
    for val in nums:
        s = sum(int(d) for d in str(val))
        if not (1 <= s <= 81):
            assert False, f'Digit sum {s} out of range for {val}'


def test_unique_digit_sums(run, x):
    out = run(x)
    lines = out.strip().split('\n')
    if len(lines) == 0 or lines[0].strip() == '0':
        return
    n = int(lines[0])
    if len(lines) < 2:
        return
    nums = list(map(int, lines[1].split()))
    seen = set()
    for val in nums:
        s = sum(int(d) for d in str(val))
        if s in seen:
            assert False, f'Duplicate digit sum {s}'
        seen.add(s)


def test_no_duplicates(run, x):
    out = run(x)
    lines = out.strip().split('\n')
    if len(lines) == 0 or lines[0].strip() == '0':
        return
    n = int(lines[0])
    if len(lines) < 2:
        return
    nums = list(map(int, lines[1].split()))
    if len(nums) != len(set(nums)):
        assert False, 'Duplicate solutions'


def test_format(run, x):
    out = run(x)
    lines = out.rstrip('\n').split('\n')
    if len(lines) == 0:
        assert False, 'Empty output'
    first = lines[0].strip()
    try:
        n = int(first)
    except:
        assert False, 'First line not an integer'
    if n == 0:
        if len(lines) != 1:
            assert False, 'Extra lines when n=0'
        if out != first + '\n' and out != first:
            assert False, 'Extra whitespace when n=0'
    else:
        if len(lines) != 2:
            assert False, 'Expected exactly two lines'
        second = lines[1]
        if second.startswith(' ') or second.endswith(' '):
            assert False, 'Leading/trailing spaces in second line'
        nums = second.split()
        if any(not s.strip().isdigit() for s in nums):
            assert False, 'Non‑integer in second line'
        if len(nums) != n:
            assert False, 'Count mismatch'
        if '  ' in second:
            assert False, 'Multiple consecutive spaces'

