    },
    {
      "name": "test_n_one",
      "source": "def test_n_one(run, x):
    import sys
    MOD = 998244353
    n, m, k = map(int, x.strip().split())
    if n == 1:
        out = run(x).strip()
        assert k == 0
        assert int(out) % MOD == m % MOD"
    },
    {
      "name": "test_brute_small",
      "source": "def test_brute_small(run, x):
    import sys
    MOD = 998244353
    n, m, k = map(int, x.strip().split())
    if n <= 8 and m <= 8:
        total = 0
        from itertools import product
        for colors in product(range(m), repeat=n):
