def test_certificate_collision(run, x):
    out = run(x).strip()
    if out == '-1':
        return
    t = int(out)
    # parse input
    lines = x.strip().split('\n')
    n = int(lines[0])
    dirs = lines[1].strip()
    coords = list(map(int, lines[2].split()))
    # compute positions at time t
    pos_t = []
    for i in range(n):
        if dirs[i] == 'R':
            pos_t.append(coords[i] + t)
        else:
            pos_t.append(coords[i] - t)
    # check at least two equal
    if len(set(pos_t)) == n:
        raise AssertionError('No collision at time t')
    # check distinct at time t-1 if t>0
    if t > 0:
        pos_t1 = []
        for i in range(n):
            if dirs[i] == 'R':
                pos_t1.append(coords[i] + (t-1))
            else:
                pos_t1.append(coords[i] - (t-1))
        if len(set(pos_t1)) != n:
            raise AssertionError('Collision already at time t-1')


def test_certificate_no_collision(run, x):
    out = run(x).strip()
    if out != '-1':
        return
    # parse input
    lines = x.strip().split('\n')
    n = int(lines[0])
    dirs = lines[1].strip()
    # if any adjacent R-L exists, collision is possible (though not guaranteed for non‑adjacent)
    # According to spec, if there is no adjacent R-L pair, then no collision can happen.
    for i in range(n-1):
        if dirs[i] == 'R' and dirs[i+1] == 'L':
            raise AssertionError('Adjacent R-L exists but output is -1')


def test_translation_invariance(run, x):
    lines = x.strip().split('\n')
    n = int(lines[0])
    dirs = lines[1].strip()
    coords = list(map(int, lines[2].split()))
    # add an even constant 2 (still even, coordinates remain even, order unchanged)
    new_coords = [c + 2 for c in coords]
    new_input = f'{n}\n{dirs}\n' + ' '.join(map(str, new_coords))
    out_orig = run(x).strip()
    out_trans = run(new_input).strip()
    if out_orig != out_trans:
        raise AssertionError('Output changed under translation')


def test_mirror_invariance(run, x):
    lines = x.strip().split('\n')
    n = int(lines[0])
    dirs = lines[1].strip()
    coords = list(map(int, lines[2].split()))
    max_x = coords[-1]
    new_coords = []
    new_dirs = []
    for i in range(n-1, -1, -1):
        new_coords.append(max_x - coords[i])
        new_dirs.append('L' if dirs[i] == 'R' else 'R')
    # new_coords are still even because max_x and each coords[i] are even
    # order is reversed, but the list is increasing because we mirrored.
    new_input = f'{n}\n' + ''.join(new_dirs) + '\n' + ' '.join(map(str, new_coords))
    out_orig = run(x).strip()
    out_mirror = run(new_input).strip()
    if out_orig != out_mirror:
        raise AssertionError('Output changed under mirror')


