tests_src:
def test_output_integer(run, x):
    out = run(x).strip()
    # The specification states the answer is always an integer.
    try:
        int(out)
    except ValueError:
        assert False, f'Output "{out}" is not an integer.'

def test_arithmetic_certificate(run, x):
    a = list(map(int, x.strip().split()))
    if len(a) != 4:
        return
    d = a[1] - a[0]
    if a[2] - a[1] == d and a[3] - a[2] == d:
        expected = a[3] + d
        out = run(x).strip()
        assert out == str(expected), f'Arithmetic progression, expected {expected}, got {out}.'

def test_geometric_certificate_integer_next(run, x):
    a = list(map(int, x.strip().split()))
    if len(a) != 4:
        return
    if a[0] == 0:
        return  # first must be nonzero for geometric progression.
    if a[1] == 0:
        return  # ratio zero not allowed (q ≠ 0).
    q_num = a[1]
    q_den = a[0]
    # Check ratio equality with integer arithmetic to avoid floats.
    if a[1] * a[2] == a[0] * a[3] and a[2] * a[2] == a[1] * a[3]:  # a1*a3==a2^2 and a2*a4==a3^2
        # Actually simpler: check a1 * r^2 == a3 and a1 * r^3 == a4 where r = a1/a0.
        # Use cross multiplication: a1/a0 == a2/a1 == a3/a2.
        if a[1] * a[2] == a[0] * a[3] and a[2] * a[2] == a[1] * a[3]:
            # Compute ratio as reduced fraction.
            # q = a[1] / a[0]
            # Check q ≠ 1.
            if a[1] == a[0]:
                return  # ratio 1 not allowed.
            # Next term = a[3] * q.
            # q = a[1] / a[0] as fraction.
            num = a[3] * a[1]
            den = a[0]
            if num % den == 0:
                expected = num // den
                out = run(x).strip()
                assert out == str(expected), f'Geometric progression with integer next, expected {expected}, got {out}.'

def test_geometric_certificate_noninteger_next(run, x):
    a = list(map(int, x.strip().split()))
    if len(a) != 4:
        return
    if a[0] == 0:
        return
    if a[1] == 0:
        return
    # Check geometric progression: a1/a0 == a2/a1 == a3/a2.
    if a[1] * a[2] == a[0] * a[3] and a[2] * a[2] == a[1] * a[3]:
        if a[1] == a[0]:
            return  # ratio 1 not allowed.
        # Compute next term.
        num = a[3] * a[1]
        den = a[0]
        if num % den != 0:
            out = run(x).strip()
            assert out == '42', f'Geometric progression with non‑integer next, expected 42, got {out}.'

def test_neither_progression(run, x):
    a = list(map(int, x.strip().split()))
    if len(a) != 4:
        return
    d = a[1] - a[0]
    arithmetic = (a[2] - a[1] == d and a[3] - a[2] == d)
    geometric = False
    if a[0] != 0 and a[1] != 0:
        # Check a1/a0 == a2/a1 == a3/a2 using cross‑multiplication.
        if a[1] * a[2] == a[0] * a[3] and a[2] * a[2] == a[1] * a[3]:
            if a[1] != a[0]:  # ratio ≠ 1
                geometric = True
    if not arithmetic and not geometric:
        out = run(x).strip()
        assert out == '42', f'Neither progression, expected 42, got {out}.'

def test_arithmetic_shift_invariance(run, x):
    a = list(map(int, x.strip().split()))
    if len(a) != 4:
        return
    d = a[1] - a[0]
    if a[2] - a[1] == d and a[3] - a[2] == d:
        # Shift by a constant that keeps numbers in [1,1000].
        # We choose shift = 5, which is small enough.
        shift = 5
        shifted = [v + shift for v in a]
        # Ensure shifted numbers are still within [1,1000] (spec says input numbers are between 1 and 1000).
        if all(1 <= v <= 1000 for v in shifted):
            inp_orig = ' '.join(map(str, a))
            inp_shifted = ' '.join(map(str, shifted))
            out_orig = run(inp_orig).strip()
            out_shifted = run(inp_shifted).strip()
            # If original output is 42 (next not integer?), shifting an arithmetic progression should still produce integer next.
            # But spec says if next not integer, output 42. Arithmetic progression always gives integer next because d is integer.
            # So we can assert that out_shifted == str(int(out_orig) + shift) if out_orig != '42'.
            if out_orig != '42':
                expected_shifted = int(out_orig) + shift
                assert out_shifted == str(expected_shifted), f'Shift invariance failed: original {out_orig}, shifted got {out_shifted}, expected {expected_shifted}.'
            else:
                # original gave 42, but arithmetic progression should not give 42. So this case shouldn't happen.
                # If it does, the test fails because original already wrong.
                assert False, f'Arithmetic progression gave 42, which is invalid.'

def test_geometric_scaling_invariance(run, x):
    a = list(map(int, x.strip().split()))
    if len(a) != 4:
        return
    if a[0] == 0:
        return
    if a[1] == 0:
        return
    # Check geometric progression.
    if a[1] * a[2] == a[0] * a[3] and a[2] * a[2] == a[1] * a[3]:
        if a[1] == a[0]:
            return  # ratio 1 not allowed.
        # Scale by factor 2 (integer) if possible within [1,1000].
        factor = 2
        scaled = [v * factor for v in a]
        if all(1 <= v <= 1000 for v in scaled):
            inp_orig = ' '.join(map(str, a))
            inp_scaled = ' '.join(map(str, scaled))
            out_orig = run(inp_orig).strip()
            out_scaled = run(inp_scaled).strip()
            if out_orig != '42':
                expected_scaled = int(out_orig) * factor
                assert out_scaled == str(expected_scaled), f'Scaling invariance failed: original {out_orig}, scaled got {out_scaled}, expected {expected_scaled}.'
            else:
                # original gave 42, but geometric progression with integer next should not.
                # If next is non‑integer, scaling by integer may keep it non‑integer, so still 42.
                # But we cannot know; safer to skip.
                pass

def test_output_consistency(run, x):
    a = list(map(int, x.strip().split()))
    if len(a) != 4:
        return
    out = run(x).strip()
    if out == '42':
        return  # 42 is allowed for any input.
    # If output is not 42, it must be the next term of either arithmetic or geometric progression.
    # So the sequence must satisfy one of the two.
    d = a[1] - a[0]
    arithmetic = (a[2] - a[1] == d and a[3] - a[2] == d)
    geometric = False
    if a[0] != 0 and a[1] != 0:
        if a[1] * a[2] == a[0] * a[3] and a[2] * a[2] == a[1] * a[3]:
            if a[1] != a[0]:
                geometric = True
    assert arithmetic or geometric, f'Output {out} is not 42, but sequence is neither arithmetic nor geometric.'

def test_bounded_output(run, x):
    out = run(x).strip()
    val = int(out)
    # Input numbers are between 1 and 1000. Arithmetic next term can be up to 1000 + 999*3? Actually d up to 999.
    # Geometric next term can be up to 1000 * (1000/1) = 1e6, but with integer ratio.
    # We set safe bound ±10^7.
    assert -10_000_000 <= val <= 10_000_000, f'Output {val} out of reasonable bounds.'

def test_constant_sequence(run, x):
    a = list(map(int, x.strip().split()))
    if len(a) != 4:
        return
    if a[0] == a[1] == a[2] == a[3]:
        out = run(x).strip()
        expected = a[0]
        assert out == str(expected), f'Constant sequence, expected {expected}, got {out}.'

