def test_format(run, x):
    out = run(x)
    if out == 'IMPOSSIBLE\n':
        return
    # otherwise must be a path of length k ending with newline
    lines = x.strip().split('\n')
    n, m, k = map(int, lines[0].split())
    assert len(out) == k + 1
    assert out[-1] == '\n'
    path = out[:-1]
    assert all(c in 'DLRU' for c in path)

def test_valid_path(run, x):
    out = run(x)
    if out == 'IMPOSSIBLE\n':
        return
    # parse maze and start position
    lines = x.strip().split('\n')
    n, m, k = map(int, lines[0].split())
    maze = lines[1:]
    start = None
    for i in range(n):
        for j in range(m):
            if maze[i][j] == 'X':
                start = (i, j)
                break
        if start:
            break
    # simulate
    i, j = start
    path = out[:-1]
    for step, c in enumerate(path):
        if c == 'D':
            ni, nj = i + 1, j
        elif c == 'U':
            ni, nj = i - 1, j
        elif c == 'R':
            ni, nj = i, j + 1
        elif c == 'L':
            ni, nj = i, j - 1
        # check bounds
        if not (0 <= ni < n and 0 <= nj < m):
            assert False, f'step {step}: out of bounds'
        cell = maze[ni][nj]
        if cell not in ('.', 'X'):
            assert False, f'step {step}: obstacle'
        i, j = ni, nj
    # must return to start
    assert (i, j) == start

def test_displacement(run, x):
    out = run(x)
    if out == 'IMPOSSIBLE\n':
        return
    path = out[:-1]
    d = path.count('D') - path.count('U')
    r = path.count('R') - path.count('L')
    assert d == 0 and r == 0

def test_length(run, x):
    out = run(x)
    if out == 'IMPOSSIBLE\n':
        return
    lines = x.strip().split('\n')
    k = int(lines[0].split()[2])
    assert len(out) == k + 1
    path = out[:-1]
    assert len(path) == k

def test_odd_k(run, x):
    lines = x.strip().split('\n')
    k = int(lines[0].split()[2])
    if k % 2 == 1:
        assert run(x) == 'IMPOSSIBLE\n', 'odd k must be impossible'

def test_no_neighbor(run, x):
    # parse maze
    lines = x.strip().split('\n')
    n, m, k = map(int, lines[0].split())
    maze = lines[1:]
    # find start
    start = None
    for i in range(n):
        for j in range(m):
            if maze[i][j] == 'X':
                start = (i, j)
                break
        if start:
            break
    # check four directions
    dirs = [(1,0), (-1,0), (0,1), (0,-1)]
    has_empty = False
    for di, dj in dirs:
        ni, nj = start[0] + di, start[1] + dj
        if 0 <= ni < n and 0 <= nj < m and maze[ni][nj] in ('.', 'X'):
            has_empty = True
            break
    if not has_empty:
        # start cell isolated => no cycle possible
        assert run(x) == 'IMPOSSIBLE\n'

def test_upper_bound(run, x):
    out = run(x)
    if out == 'IMPOSSIBLE\n':
        return
    lines = x.strip().split('\n')
    n, m, k = map(int, lines[0].split())
    maze = lines[1:]
    # find start
    start = None
    for i in range(n):
        for j in range(m):
            if maze[i][j] == 'X':
                start = (i, j)
                break
        if start:
            break
    # lexicographically smallest direction D<L<R<U
    order = [('D',1,0), ('L',0,-1), ('R',0,1), ('U',-1,0)]
    best_dir = None
    for ch, di, dj in order:
        ni, nj = start[0] + di, start[1] + dj
        if 0 <= ni < n and 0 <= nj < m and maze[ni][nj] in ('.', 'X'):
            best_dir = ch
            break
    # construct trivial cycle: best_dir + opposite repeated k//2 times
    opposite = {'D':'U', 'U':'D', 'L':'R', 'R':'L'}
    trivial = (best_dir + opposite[best_dir]) * (k // 2)
    path = out[:-1]
    # lexicographically minimal path must be <= trivial
    assert path <= trivial

def test_impossible_necessary(run, x):
    out = run(x)
    if out != 'IMPOSSIBLE\n':
        return
    lines = x.strip().split('\n')
    n, m, k = map(int, lines[0].split())
    maze = lines[1:]
    # find start
    start = None
    for i in range(n):
        for j in range(m):
            if maze[i][j] == 'X':
                start = (i, j)
                break
        if start:
            break
    # check four directions
    dirs = [(1,0), (-1,0), (0,1), (0,-1)]
    has_empty = False
    for di, dj in dirs:
        ni, nj = start[0] + di, start[1] + dj
        if 0 <= ni < n and 0 <= nj < m and maze[ni][nj] in ('.', 'X'):
            has_empty = True
            break
    # if output is impossible, then either k is odd or start isolated
    assert k % 2 == 1 or not has_empty, 'IMPOSSIBLE output but k even and neighbor exists'

def test_no_impossible_why(run, x):
    out = run(x)
    # plan says: catch the specific erroneous output 'IMPOSSIBLE WHY'
    assert 'IMPOSSIBLE WHY' not in out

def test_existence(run, x):
    lines = x.strip().split('\n')
    n, m, k = map(int, lines[0].split())
    if k % 2 != 0:
        return
    maze = lines[1:]
    # find start
    start = None
    for i in range(n):
        for j in range(m):
            if maze[i][j] == 'X':
                start = (i, j)
                break
        if start:
            break
    # check four directions
    dirs = [(1,0), (-1,0), (0,1), (0,-1)]
    has_empty = False
    for di, dj in dirs:
        ni, nj = start[0] + di, start[1] + dj
        if 0 <= ni < n and 0 <= nj < m and maze[ni][nj] in ('.', 'X'):
            has_empty = True
            break
    if has_empty:
        # a cycle exists (e.g., bounce between start and that neighbor)
        out = run(x)
        assert out != 'IMPOSSIBLE\n'

