    if not out:
        raise AssertionError('empty output')
    T = int(out)
    U = min(max(pos - 1 for pos in prizes), max(1_000_000 - pos for pos in prizes))
    if T > U:
        raise AssertionError(f'T={T} > upper bound {U}')"
    },
    {
      "name": "test_symmetry",
      "source": "def test_symmetry(run, x):
    lines = x.strip().split('\n')
    n = int(lines[0])
