def test_lower_bound(run, x):
    import math
    n, a, b = map(int, x.strip().split())
    k = int(run(x).strip())
    lower = math.ceil((4 * a + 2 * b) / n)
    assert k >= lower, f"k={k} < ceil((4a+2b)/n)={lower}"

def test_upper_bound(run, x):
    k = int(run(x).strip())
    assert k <= 6, f"k={k} > 6"

def test_integer(run, x):
    out = run(x).strip()
    k = int(out)  # raises ValueError if not integer
    assert k >= 1, f"k={k} < 1"

def test_examples(run, x):
    examples = [
        ("8\n1\n2\n", "1\n"),
        ("5\n3\n4\n", "6\n"),
        ("6\n4\n2\n", "4\n"),
        ("20\n5\n6\n", "2\n")
    ]
    for inp, exp in examples:
        if x == inp:
            assert run(x) == exp, f"example mismatch: got {run(x)!r}, expected {exp!r}"

def test_monotonic_n(run, x):
    n, a, b = map(int, x.strip().split())
    if n < 1000:
        modified = f"{n+1}\n{a}\n{b}\n"
        k_orig = int(run(x).strip())
        k_mod = int(run(modified).strip())
        assert k_mod <= k_orig, f"n increased from {n} to {n+1} but k increased from {k_orig} to {k_mod}"

def test_monotonic_a(run, x):
    n, a, b = map(int, x.strip().split())
    if a > 1:
        modified = f"{n}\n{a-1}\n{b}\n"
        k_orig = int(run(x).strip())
        k_mod = int(run(modified).strip())
        assert k_mod <= k_orig, f"a decreased from {a} to {a-1} but k increased from {k_orig} to {k_mod}"

def test_monotonic_b(run, x):
    n, a, b = map(int, x.strip().split())
    if b > 1:
        modified = f"{n}\n{a}\n{b-1}\n"
        k_orig = int(run(x).strip())
        k_mod = int(run(modified).strip())
        assert k_mod <= k_orig, f"b decreased from {b} to {b-1} but k increased from {k_orig} to {k_mod}"

def test_certificate(run, x):
    import itertools, math
    n, a, b = map(int, x.strip().split())
    k = int(run(x).strip())
    pieces = [a]*4 + [b]*2
    # check k bars suffice
    found = False
    for assignment in itertools.product(range(k), repeat=6):
        bars = [0]*k
        ok = True
        for piece, bar_idx in zip(pieces, assignment):
            bars[bar_idx] += piece
            if bars[bar_idx] > n:
                ok = False
                break
        if ok:
            found = True
            break
    assert found, f"k={k} bars insufficient for pieces {pieces} with bar length {n}"
    # check k-1 bars insufficient (if k>1)
    if k > 1:
        sufficient = False
        for assignment in itertools.product(range(k-1), repeat=6):
            bars = [0]*(k-1)
            ok = True
            for piece, bar_idx in zip(pieces, assignment):
                bars[bar_idx] += piece
                if bars[bar_idx] > n:
                    ok = False
                    break
            if ok:
                sufficient = True
                break
        assert not sufficient, f"k-1={k-1} bars sufficient, so k={k} is not minimal"

def test_total_length_trivial(run, x):
    n, a, b = map(int, x.strip().split())
    if n >= 4*a + 2*b:
        k = int(run(x).strip())
        assert k == 1, f"n={n} >= 4a+2b={4*a+2*b} but k={k} != 1"

def test_special_case_all_full(run, x):
    n, a, b = map(int, x.strip().split())
    if a == n and b == n:
        k = int(run(x).strip())
        assert k == 6, f"a=b=n={n} but k={k} != 6"

