    q = s[1:].count('?')
    out = run(x).strip()
    ans_str = out.strip()
    trailing = len(ans_str) - len(ans_str.rstrip('0'))
    assert trailing >= q, f'Answer must have at least {q} trailing zeros'"
    },
    {
      "name": "test_swap_AB",
      "source": "def test_swap_AB(run, x):
    s = x.strip()
    s2 = s.replace('A', 'X').replace('B', 'A').replace('X', 'B')
    out1 = run(s).strip()
