    },
    {
      "name": "test_no_letters_formula",
      "source": "def test_no_letters_formula(run, x):
    s = x.strip()
    if any(c in 'ABCDEFGHIJ' for c in s):
        return  # skip if letters present
    q = s[1:].count('?')
    if s[0] == '?':
        expected = 9 * (10 ** q)
    else:
        expected = 10 ** q
    out = run(s).strip()
    ans = int(out)
    assert ans == expected, f'For no‑letters hint, answer must be {expected}'"
    },
