      "name": "test_small_brute_force",
      "source": "def test_small_brute_force(run, x):
    s = x.strip()
    if len(s) > 5:
        return  # skip large inputs
    # brute‑force enumeration
    letters = [c for c in s if 'A' <= c <= 'J']
    distinct = list(dict.fromkeys(letters))
    from itertools import product
    count = 0
    for dig in product('0123456789', repeat=len(distinct)):
        if len(set(dig)) != len(dig):
            continue
        mapping = {distinct[i]: dig[i] for i in range(len(distinct))}
        t = []
        for ch in s:
            if ch == '?':
                t.append('0')
            elif '0' <= ch <= '9':
                t.append(ch)
            else:
                t.append(mapping[ch])
        if t[0] == '0':
            continue
        count += 1
    out = run(s).strip()
    ans = int(out)
    assert ans == count, f'Brute‑force count is {count}'"
