tests_src:
def test_single_character(run, x):
    output = run(x)
    assert len(output.strip()) == 1

def test_digit(run, x):
    output = run(x)
    assert output.strip() in '0123456789'

def test_first_nine(run, x):
    n = int(x.strip())
    if 1 <= n <= 9:
        output = run(x).strip()
        assert output == str(n)

def test_position_10(run, x):
    if x.strip() == '10':
        output = run(x).strip()
        assert output == '1'

def test_position_11(run, x):
    if x.strip() == '11':
        output = run(x).strip()
        assert output == '0'

def test_position_12(run, x):
    if x.strip() == '12':
        output = run(x).strip()
        assert output == '1'

def test_no_zero_in_first_nine(run, x):
    n = int(x.strip())
    if 1 <= n <= 9:
        output = run(x).strip()
        assert output != '0'

def test_metamorphic_increment(run, x):
    n = int(x.strip())
    if 1 <= n <= 8:
        out_n = run(x).strip()
        out_next = run(str(n+1)).strip()
        # Digits are consecutive from '1' to '9'
        assert ord(out_next) - ord(out_n) == 1

def test_metamorphic_two_digit_start(run, x):
    if x.strip() == '10':
        out10 = run('10').strip()
        out11 = run('11').strip()
        # They should form the two-digit number "10"
        assert out10 + out11 == '10'

def test_large_n_digit(run, x):
    if x.strip() == '1000':
        output = run(x).strip()
        assert output in '0123456789'

