    },
    {
      "name": "test_swap_B_D",
      "intent": "Swap the descriptions of B and D. If original output was 'B', new must be 'D'; if 'D', new must be 'B'; if 'A' or 'C', unchanged."
    },
    {
      "name": "test_replace_with_as",
      "intent": "Replace each description with a string of lowercase 'a' characters of the same length. Since the algorithm depends only on lengths, the output must remain the same."
