    },
    {
      "name": "test_step",
      "intent": "If there are at least two numbers in the output, the difference between each consecutive pair must be exactly k, since valid x form an arithmetic progression with step k."
    },
    {
      "name": "test_minimal",
      "intent": "The first number in the output must be the smallest possible x: either subtracting k gives a number less than 1 or that number's sum with y would exceed n, ensuring no smaller valid x exists."
