{
  "rationale": "Each test implements the intent as described, using only properties derivable from the specification. Strengths/weaknesses: (1) suffix_match, year_min, year_ge_int, output_line_count are direct invariants. (2) single_digit, two_digit_lower_bound, three_digit_lower_bound are bounds derived from the earliest usage years. (3) reorder_independence, duplicate_abbreviation, split_input are metamorphic relations justified by the specification: outputs depend only on individual abbreviations, not order or grouping. Where the plan was vague (e.g., reorder_independence's exact swapping), we used a safe variant that must hold for any correct solution. The weakest test is year_min, as it's a very loose bound; if dropping one, it would be that, but it's still valid.",
  "tests": [
    {
      "name": "test_suffix_match",
      "source": "def test_suffix_match(run, x):
    lines = x.strip().split('\n')
    n = int(lines[0])
    out_lines = run(x).strip().split('\n')
    if len(out_lines) != n:
        return  # let other test catch line count
    for i in range(n):
        abbr = lines[i+1]
        # extract y: everything after IAO'
        if not abbr.startswith("IAO'"):
            continue
        y = abbr[4:]
        year = out_lines[i].strip()
        if not y or not year:
            continue
        # year must end with y exactly
        if not year.endswith(y):
            assert False, f"Year {year} does not end with {y}"
        # also ensure that if y has leading zeros, they appear in suffix
        # year[-len(y):] should equal y
        if year[-len(y):] != y:
            assert False, f"Year suffix mismatch: {year[-len(y):]} vs {y}""
    },
    {
      "name": "test_year_min",
      "source": "def test_year_min(run, x):
    lines = x.strip().split('\n')
    n = int(lines[0])
    out_lines = run(x).strip().split('\n')
    if len(out_lines) != n:
        return  # let other test catch line count
    for y_str in out_lines:
        year = int(y_str.strip())
        assert year >= 1989, f"Year {year} is less than 1989""
    },
    {
      "name": "test_year_ge_int",
      "source": "def test_year_ge_int(run, x):
    lines = x.strip().split('\n')
    n = int(lines[0])
    out_lines = run(x).strip().split('\n')
    if len(out_lines) != n:
        return
    for i in range(n):
        abbr = lines[i+1]
        if not abbr.startswith("IAO'"):
            continue
        y = abbr[4:]
        if not y:
            continue
        val = int(y)  # leading zeros are ignored, which matches spec: "interpret y as a decimal number"
        year = int(out_lines[i].strip())
        assert year >= val, f"Year {year} is less than integer value {val} of y={y}""
    },
    {
      "name": "test_single_digit",
      "source": "def test_single_digit(run, x):
    lines = x.strip().split('\n')
    n = int(lines[0])
    out_lines = run(x).strip().split('\n')
    if len(out_lines) != n:
        return
    for i in range(n):
        abbr = lines[i+1]
        if not abbr.startswith("IAO'"):
            continue
        y = abbr[4:]
        if len(y) == 1:
            d = int(y)
            expected_year = 1989 + (d - 9) % 10
            year = int(out_lines[i].strip())
            assert year == expected_year, f"Single digit {d}: expected {expected_year}, got {year}""
    },
    {
      "name": "test_two_digit_lower_bound",
      "source": "def test_two_digit_lower_bound(run, x):
    lines = x.strip().split('\n')
    n = int(lines[0])
    out_lines = run(x).strip().split('\n')
    if len(out_lines) != n:
        return
    for i in range(n):
        abbr = lines[i+1]
        if not abbr.startswith("IAO'"):
            continue
        y = abbr[4:]
        if len(y) == 2:
            year = int(out_lines[i].strip())
            assert year >= 1999, f"Two-digit y={y}: year {year} < 1999""
    },
    {
      "name": "test_three_digit_lower_bound",
      "source": "def test_three_digit_lower_bound(run, x):
    lines = x.strip().split('\n')
    n = int(lines[0])
    out_lines = run(x).strip().split('\n')
    if len(out_lines) != n:
        return
    for i in range(n):
        abbr = lines[i+1]
        if not abbr.startswith("IAO'"):
            continue
        y = abbr[4:]
        if len(y) == 3:
            year = int(out_lines[i].strip())
            assert year >= 2099, f"Three-digit y={y}: year {year} < 2099""
    },
    {
      "name": "test_reorder_independence",
      "source": "def test_reorder_independence(run, x):
    lines = x.strip().split('\n')
    n = int(lines[0])
    if n < 2:
        return  # need at least two abbreviations to swap
    # swap positions 1 and 2 (the first two abbreviations after n)
    swapped_lines = lines[:1] + [lines[2], lines[1]] + lines[3:]
    swapped_input = '\n'.join(swapped_lines)
    orig_output = run(x).strip().split('\n')
    swapped_output = run(swapped_input).strip().split('\n')
    if len(orig_output) != n or len(swapped_output) != n:
        return  # line count test will catch
    # The outputs should be swapped in the same positions
    assert orig_output[0] == swapped_output[1], f"Reordering mismatch: {orig_output[0]} vs {swapped_output[1]}"
    assert orig_output[1] == swapped_output[0], f"Reordering mismatch: {orig_output[1]} vs {swapped_output[0]}"
    # For remaining lines, they should be equal
    for i in range(2, n):
        assert orig_output[i] == swapped_output[i], f"Reordering mismatch at index {i}""
    },
    {
      "name": "test_duplicate_abbreviation",
      "source": "def test_duplicate_abbreviation(run, x):
    lines = x.strip().split('\n')
