def test_bound(run, x):
    # The output must be an integer between 1 and 9 * 10^(len(s)-1) inclusive.
    s = x.strip()
    max_val = 9 * (10 ** (len(s) - 1))
    out = run(x).strip()
    try:
        val = int(out)
    except ValueError:
        assert False, f'Output not an integer: {out}'
    assert 1 <= val <= max_val, f'Output {val} out of bounds for length {len(s)}'


def test_div9(run, x):
    # If first character is not a digit, output must be divisible by 9.
    s = x.strip()
    if s[0].isdigit():
        return  # nothing to check
    out = run(x).strip()
    try:
        val = int(out)
    except ValueError:
        assert False, f'Output not an integer: {out}'
    assert val % 9 == 0, f'Output {val} not divisible by 9 when first char is non‑digit'


def test_div10(run, x):
    # Count '?' characters, excluding the first if it is '?'.
    s = x.strip()
    count = 0
    for i, ch in enumerate(s):
        if ch == '?':
            if i == 0:
                continue
            count += 1
    if count == 0:
        return  # trivial divisibility
    out = run(x).strip()
    try:
        val = int(out)
    except ValueError:
        assert False, f'Output not an integer: {out}'
    assert val % (10 ** count) == 0, f'Output {val} not divisible by 10^{count}'


def test_swap_non_first(run, x):
    # Swap two characters that are not the first character.
    s = x.strip()
    if len(s) < 3:
        return  # not enough characters to swap non‑first
    # Choose positions 1 and len(s)-1 (both non‑first).
    i, j = 1, len(s) - 1
    if i == j:
        j = 2  # fallback if length == 3
    lst = list(s)
    lst[i], lst[j] = lst[j], lst[i]
    t = ''.join(lst)
    # The modified hint must be valid (first character not '0' by guarantee).
    out_s = run(x).strip()
    out_t = run(t).strip()
    try:
        val_s = int(out_s)
        val_t = int(out_t)
    except ValueError:
        assert False, f'Output not integer: {out_s} or {out_t}'
    assert val_s == val_t, f'Swapping non‑first characters changed count: {val_s} vs {val_t}'


def test_swap_letters(run, x):
    # Pick two distinct letters that appear, swap all occurrences.
    s = x.strip()
    letters = [ch for ch in s if 'A' <= ch <= 'J']
    distinct = list(set(letters))
    if len(distinct) < 2:
        return  # need at least two letters
    a, b = distinct[0], distinct[1]
    t = s.translate(str.maketrans({a: b, b: a}))
    out_s = run(x).strip()
    out_t = run(t).strip()
    try:
        val_s = int(out_s)
        val_t = int(out_t)
    except ValueError:
        assert False, f'Output not integer: {out_s} or {out_t}'
    assert val_s == val_t, f'Swapping letters {a} and {b} changed count: {val_s} vs {val_t}'


def test_replace_question_with_digit(run, x):
    # Replace every '?' with '1' and assert the new count ≤ original.
    s = x.strip()
    if '?' not in s:
        return
    t = s.replace('?', '1')
    # t is valid because '1' is a digit and not '0', and first character stays non‑zero.
    out_s = run(x).strip()
    out_t = run(t).strip()
    try:
        val_s = int(out_s)
        val_t = int(out_t)
    except ValueError:
        assert False, f'Output not integer: {out_s} or {out_t}'
    assert val_t <= val_s, f'Replacing ? with 1 increased count: {val_t} > {val_s}'


def test_all_digits(run, x):
    # If hint contains only digits, output must be 1.
    s = x.strip()
    if all(ch.isdigit() for ch in s):
        out = run(x).strip()
        try:
            val = int(out)
        except ValueError:
            assert False, f'Output not an integer: {out}'
        assert val == 1, f'All‑digits hint should give 1, got {val}'


def test_single_question_first(run, x):
    # If hint is exactly '?', output must be 9.
    if x.strip() == '?':
        out = run(x).strip()
        try:
            val = int(out)
        except ValueError:
            assert False, f'Output not an integer: {out}'
