        out = run(x).strip()
        try:
            val = int(out)
        except ValueError:
            assert False, f'Output not an integer: {out}'
        assert val == 9, f'Single letter {s} should give 9, got {val}'


def test_brute_force_short(run, x):
    # For hints of length ≤5, brute‑force count and compare.
    s = x.strip()
    if len(s) > 5:
        return  # skip for longer hints (plan says length at most 5)
    letters = [ch for ch in s if 'A' <= ch <= 'J']
    letter_to_digit = {}
    digit_used = [False] * 10
    def dfs(pos):
        if pos == len(s):
            # Check first digit non‑zero
            first = digit_seq[0]
            if first == 0:
                return 0
            else:
                return 1
        total = 0
        ch = s[pos]
        if ch.isdigit():
            digit_seq.append(int(ch))
            total += dfs(pos + 1)
            digit_seq.pop()
        elif ch == '?':
            for d in range(10):
                digit_seq.append(d)
                total += dfs(pos + 1)
                digit_seq.pop()
        else:  # letter
            if ch in letter_to_digit:
                digit_seq.append(letter_to_digit[ch])
                total += dfs(pos + 1)
                digit_seq.pop()
            else:
                for d in range(10):
                    if digit_used[d]:
                        continue
                    digit_used[d] = True
                    letter_to_digit[ch] = d
                    digit_seq.append(d)
                    total += dfs(pos + 1)
                    digit_seq.pop()
                    del letter_to_digit[ch]
                    digit_used[d] = False
        return total
    digit_seq = []
    expected = dfs(0)
    out = run(x).strip()
    try:
        val = int(out)
    except ValueError:
        assert False, f'Output not an integer: {out}'
    assert val == expected, f'Brute‑force mismatch: got {val}, expected {expected}'

