def test_nonnegative_integer(run, x):
    out = run(x).strip()
    # Must be a single integer, no extra whitespace/newlines
    lines = out.splitlines()
    assert len(lines) == 1, "Output must be exactly one line"
    val = lines[0].strip()
    assert val.isdigit() or (val[0] == '-' and val[1:].isdigit()), "Output must be an integer"
    n = int(val)
    assert n >= 0, "Output must be non‑negative"


def test_upper_bound_tight(run, x):
    A, B, C, D = map(int, x.strip().split())
    total_pairs = (B - A + 1) * (C - B + 1)
    z_max = min(D, B + C - 1)
    if z_max >= C:
        max_z_count = z_max - C + 1
    else:
        max_z_count = 0
    upper = total_pairs * max_z_count
    out = int(run(x).strip())
    assert out <= upper, f"Answer {out} exceeds upper bound {upper}"


def test_lower_bound_all(run, x):
    A, B, C, D = map(int, x.strip().split())
    total_pairs = (B - A + 1) * (C - B + 1)
    z_limit = min(D, A + B - 1)
    if z_limit >= C:
        min_z_count = z_limit - C + 1
    else:
        min_z_count = 0
    lower = total_pairs * min_z_count
    out = int(run(x).strip())
    assert out >= lower, f"Answer {out} below lower bound {lower}"


def test_metamorphic_decrease_A(run, x):
    A, B, C, D = map(int, x.strip().split())
    if A > 1:
        new_input = f"{A-1} {B} {C} {D}"
        orig_out = int(run(x).strip())
        new_out = int(run(new_input).strip())
        assert new_out >= orig_out, f"Decreasing A should not decrease count, got {new_out} < {orig_out}"


def test_metamorphic_increase_D(run, x):
    A, B, C, D = map(int, x.strip().split())
    if D < 500000:
        new_input = f"{A} {B} {C} {D+1}"
        orig_out = int(run(x).strip())
        new_out = int(run(new_input).strip())
        assert new_out >= orig_out, f"Increasing D should not decrease count, got {new_out} < {orig_out}"


def test_certificate_all_triangles(run, x):
    A, B, C, D = map(int, x.strip().split())
    if A + B > D:
        total = (B - A + 1) * (C - B + 1) * (D - C + 1)
        out = int(run(x).strip())
        assert out == total, f"When A+B>{D}, all triples are triangles, expected {total}, got {out}"


def test_certificate_equilateral(run, x):
    A, B, C, D = map(int, x.strip().split())
    if A == B == C == D:
        out = int(run(x).strip())
        assert out == 1, f"Only equilateral triangle possible, expected 1, got {out}"


def test_brute_force_small(run, x):
    A, B, C, D = map(int, x.strip().split())
    total_triples = (B - A + 1) * (C - B + 1) * (D - C + 1)
    if total_triples <= 100000:
        out = int(run(x).strip())
        count = 0
        for xv in range(A, B + 1):
            for yv in range(B, C + 1):
                for zv in range(C, D + 1):
                    if xv + yv > zv:
                        count += 1
        assert out == count, f"Brute force count {count} does not match answer {out}"


def test_lower_bound_at_least_one(run, x):
    A, B, C, D = map(int, x.strip().split())
    if A + B > C:
        out = int(run(x).strip())
        assert out >= 1, f"At least one triangle exists (A,B,C), but answer is {out}"


def test_certificate_A_eq_B_eq_C(run, x):
    A, B, C, D = map(int, x.strip().split())
    if A == B == C:
        z_max = min(D, 2 * A - 1)
        expected = max(0, z_max - A + 1)
        out = int(run(x).strip())
        assert out == expected, f"When A=B=C, expected {expected}, got {out}"

