{
  "rationale": "The tests combine invariants (non-negative integer, at least one triangle), bounds (upper bound from total triples, lower bounds from specific triangle types), metamorphic relations (monotonicity in A and D), and exact checks for small inputs and known examples. These catch common errors like off-by-one, incorrect prefix sums, and mishandled boundaries. The lower bound tests are cheap to compute and provide additional validation. If a test must be dropped, test_small_double_sum is somewhat redundant with test_small_exact but catches errors specific to the double-sum method.",
  "plan": [
    {
      "name": "test_non_negative_integer",
      "intent": "Parse the output as an integer and assert it is non‑negative. A violation is a negative number or non‑integer output."
    },
    {
      "name": "test_at_least_one",
      "intent": "Assert the output integer is at least 1, because for any valid input the triple (B, C, C) always satisfies the triangle inequality. A violation is an output of 0 or less."
    },
    {
      "name": "test_upper_bound",
      "intent": "Compute U = (B‑A+1) * (C‑B+1) * (D‑C+1), the total number of triples ignoring the triangle inequality. Assert the output ≤ U. A violation means the count exceeds the possible number of triples."
    },
    {
      "name": "test_monotonic_A",
      "intent": "If A > 1 and A < B, construct a second input with A decreased by 1 (keeping other values unchanged). Run the program on both inputs and assert the output for the decreased A is not smaller than the original. A violation would mean decreasing A reduced the count, contradicting monotonicity."
    },
    {
      "name": "test_monotonic_D",
      "intent": "If D < 500000, construct a second input with D increased by 1. Run the program on both and assert the output for increased D is not smaller. A violation would mean increasing D reduced the count, contradicting monotonicity."
    },
    {
      "name": "test_small_exact",
      "intent": "If the total number of triples (U as above) is at most 1,000,000, compute the exact count by brute force: iterate over all x, y, z in the ranges and count those with x+y > z. Assert the output equals this count. A violation indicates a wrong answer for a small, tractable input."
    },
    {
      "name": "test_small_double_sum",
      "intent": "If (B‑A+1)*(C‑B+1) ≤ 1,000,000, compute the count by iterating over x and y and adding the number of z in [C, D] with z < x+y. Assert the output equals this sum. A violation catches errors that might not appear in the full brute‑force check."
    },
    {
      "name": "test_examples",
      "intent": "If the input exactly matches one of the three examples given in the problem statement, assert the output matches the expected output from the statement. A violation means the program fails on the provided examples."
    },
    {
      "name": "test_lower_bound_eq_x_y",
      "intent": "Compute L = max(0, min(D, 2*B‑1) – C + 1), the number of triangles with x = y = B. Assert the output ≥ L. A violation means the count is smaller than this easily computable lower bound."
    },
    {
      "name": "test_lower_bound_y_z",
      "intent": "Compute L2 = sum_{y=B}^{min(C,D)} max(0, min(B,y) – A + 1), the number of triangles with y = z. Assert the output ≥ L2. A violation means the count is smaller than this efficiently computable lower bound."
    }
  ]
}

{
  "rationale": "The plan's intents are implemented as property tests justified by the specification. Where intents required comparing two runs (monotonicity), we ensure the modified inputs remain valid. For upper/lower bounds, we compute directly from the input. For small exact checks, we brute force only when the specification's ranges guarantee feasibility (using the provided inputs' sizes). The metamorphic relations rely on the specification's statement that increasing A or decreasing D cannot remove triples, so counts are monotone non-decreasing in those directions. The invariants (non‑negative, at least one) are direct from the problem: number of triangles is always ≥1 (since (B,C,C) always works) and is a count. The examples check is a direct certificate. We avoid recomputing the full answer for large inputs; instead we compute partial sums or bounds that are cheap. We drop nothing; each test implements one numbered intent with the strictest feasible claim.",
  "tests": [
    {
      "name": "test_non_negative_integer",
      "source": "def test_non_negative_integer(run, x):
    out = run(x).strip()
    # Must be an integer
    n = int(out)
    # Must be non‑negative (it's a count of triangles)
    assert n >= 0, f'output {n} is negative'"
    },
    {
      "name": "test_at_least_one",
      "source": "def test_at_least_one(run, x):
    out = run(x).strip()
    n = int(out)
    # (B, C, C) always satisfies the triangle inequality because 2*C > C.
    # Since A ≤ B ≤ C, such a triple exists and is counted.
    assert n >= 1, f'output {n} is less than 1'"
    },
    {
      "name": "test_upper_bound",
      "source": "def test_upper_bound(run, x):
    a,b,c,d = map(int, x.strip().split())
    total_triples = (b - a + 1) * (c - b + 1) * (d - c + 1)
