    n = int(out)
    assert n <= total_triples, f'output {n} exceeds total possible triples {total_triples}'"
    },
    {
      "name": "test_monotonic_A",
      "source": "def test_monotonic_A(run, x):
    a,b,c,d = map(int, x.strip().split())
    if a > 1 and a < b:
        # valid because A is at least 1, and we keep A ≤ B
        modified = f'{a-1} {b} {c} {d}\n'
        orig_out = int(run(x).strip())
        mod_out = int(run(modified).strip())
        # decreasing A cannot reduce the number of valid triples
        assert mod_out >= orig_out, f'decreasing A from {a} to {a-1} reduced count'"
    },
    {
      "name": "test_monotonic_D",
      "source": "def test_monotonic_D(run, x):
    a,b,c,d = map(int, x.strip().split())
    if d < 500000:
        # valid because D ≤ 5e5, increasing by 1 stays in range
        modified = f'{a} {b} {c} {d+1}\n'
        orig_out = int(run(x).strip())
        mod_out = int(run(modified).strip())
        # increasing D cannot reduce the number of valid triples
        assert mod_out >= orig_out, f'increasing D from {d} to {d+1} reduced count'"
    },
    {
      "name": "test_small_exact",
      "source": "def test_small_exact(run, x):
    a,b,c,d = map(int, x.strip().split())
    total_triples = (b - a + 1) * (c - b + 1) * (d - c + 1)
    # Only brute force when the total triples is ≤ 1 000 000
    if total_triples <= 1_000_000:
        out = int(run(x).strip())
        count = 0
        for xv in range(a, b+1):
            for yv in range(b, c+1):
                for zv in range(c, d+1):
                    if xv + yv > zv:
                        count += 1
        assert out == count, f'expected {count}, got {out}'"
    },
    {
      "name": "test_small_double_sum",
      "source": "def test_small_double_sum(run, x):
    a,b,c,d = map(int, x.strip().split())
    if (b - a + 1) * (c - b + 1) <= 1_000_000:
        out = int(run(x).strip())
        count = 0
        for xv in range(a, b+1):
            for yv in range(b, c+1):
                # number of z with c ≤ z ≤ d and z < xv + yv
                max_z = min(d, xv + yv - 1)
                if max_z >= c:
                    count += max_z - c + 1
        assert out == count, f'expected {count}, got {out}'"
    },
    {
      "name": "test_examples",
      "source": "def test_examples(run, x):
    # compare against the three given examples
    examples = {
        '1 2 3 4\n': 4,
        '1 2 2 5\n': 3,
        '500000 500000 500000 500000\n': 1,
    }
    if x in examples:
        out = int(run(x).strip())
        expected = examples[x]
        assert out == expected, f'example {x.strip()} expects {expected}, got {out}'"
    },
    {
      "name": "test_lower_bound_eq_x_y",
      "source": "def test_lower_bound_eq_x_y(run, x):
    a,b,c,d = map(int, x.strip().split())
    # triangles with x = y = B
    # x = B, y = B, need z in [C, D] with z < 2*B
    max_z = min(d, 2*b - 1)
    if max_z >= c:
        lower = max_z - c + 1
    else:
        lower = 0
    out = int(run(x).strip())
    assert out >= lower, f'output {out} less than lower bound {lower} from x=y=B'"
    },
    {
      "name": "test_lower_bound_y_z",
      "source": "def test_lower_bound_y_z(run, x):
    a,b,c,d = map(int, x.strip().split())
    # triangles with y = z
    lower = 0
    for y in range(b, min(c, d) + 1):
        # need x in [A, min(B, y)] such that x + y > y  => x > 0 (always true for x >= 1)
        # actually triangle inequality for y = z reduces to x + y > y => x > 0, always satisfied.
        # So all x in [A, min(B, y)] work.
        max_x = min(b, y)
        if max_x >= a:
            lower += max_x - a + 1
    out = int(run(x).strip())
    assert out >= lower, f'output {out} less than lower bound {lower} from y=z'"
    }
  ]
}

