def test_remove_duplicate(run, x):
    lines = x.strip().split('\n')
    n, k = map(int, lines[0].split())
    if k < 2:
        return
    # find first duplicate
    seen = set()
    dup_idx = -1
    for i in range(1, k+1):
        sig = lines[i]
        if sig in seen:
            dup_idx = i
            break
        seen.add(sig)
    if dup_idx == -1:
        return
    modified = f"{n} {k-1}\n"
    for j in range(1, k+1):
        if j != dup_idx:
            modified += lines[j] + '\n'
    out1 = run(x).strip()
    out2 = run(modified).strip()
    assert out1 == out2, f"Removing duplicate changed output: {out1} vs {out2}"

def test_implication_addition(run, x):
    lines = x.strip().split('\n')
    n, k = map(int, lines[0].split())
    le_constraints = []
    for i in range(1, k+1):
        parts = lines[i].split()
        if parts[1] == '<=':
            le_constraints.append((int(parts[0]), int(parts[2])))
    # transitivity
    new_le = None
    for a, b in le_constraints:
        for c, d in le_constraints:
            if b == c:
                # a ≤ b, b ≤ d → a ≤ d
                if (a, d) not in le_constraints:
                    new_le = (a, d)
                    break
        if new_le:
            break
    if new_le:
        modified = f"{n} {k+1}\n"
        for i in range(1, k+1):
            modified += lines[i] + '\n'
        modified += f"{new_le[0]} <= {new_le[1]}"
        out1 = run(x).strip()
        out2 = run(modified).strip()
        assert out1 == out2, f"Adding transitive ≤ changed output: {out1} vs {out2}"

def test_output_format(run, x):
    out = run(x)
    # must be exactly one integer followed by optional newline
    stripped = out.strip()
    assert stripped.isdigit() or (stripped[0] == '-' and stripped[1:].isdigit()), f"Output not a valid integer: {out}"
    # no extra whitespace
    lines = out.splitlines()
    assert len(lines) == 1 or (len(lines) == 2 and lines[1] == ''), f"Extra lines in output: {out}"
    assert out == stripped + '\n' or out == stripped, f"Whitespace mismatch: {repr(out)}"

