tests_src:
def test_output_format(run, x):
    out = run(x).strip()
    if out == 'Infinity' or out == 'Impossible':
        return
    # must be an integer, possibly negative
    try:
        int(out)
    except ValueError:
        assert False, f'Invalid output: {repr(out)}'

def test_infinity_iff_no_div2(run, x):
    out = run(x).strip()
    lines = x.strip().split('\n')
    n = int(lines[0])
    has_div2 = any(int(line.split()[1]) == 2 for line in lines[1:])
    if out == 'Infinity':
        assert not has_div2, f'Infinity output but there is division 2 contest'
    else:
        if not has_div2:
            assert False, f'No division 2 contest but output is {out}, not Infinity'

def test_impossible_iff_infeasible(run, x):
    lines = x.strip().split('\n')
    n = int(lines[0])
    c = []
    d = []
    for line in lines[1:]:
        parts = list(map(int, line.split()))
        c.append(parts[0])
        d.append(parts[1])
    prefix = 0
    L = -10**18  # -inf
    U = 10**18   # +inf
    for i in range(n):
        if d[i] == 1:
            # rating before contest i >= 1900 -> initial rating >= 1900 - prefix
            lb = 1900 - prefix
            if lb > L:
                L = lb
        else:  # d[i]==2
            # rating before contest i <= 1899 -> initial rating <= 1899 - prefix
            ub = 1899 - prefix
            if ub < U:
                U = ub
        prefix += c[i]
    out = run(x).strip()
    feasible = L <= U
    if out == 'Impossible':
        assert not feasible, f'Impossible output but feasible (L={L}, U={U})'
    else:
        if not feasible:
            assert False, f'Infeasible (L={L}, U={U}) but output is {out}, not Impossible'

def test_integer_feasibility(run, x):
    out = run(x).strip()
    if out == 'Infinity' or out == 'Impossible':
        return
    R = int(out)
    lines = x.strip().split('\n')
    n = int(lines[0])
    c = []
    d = []
    for line in lines[1:]:
        parts = list(map(int, line.split()))
        c.append(parts[0])
        d.append(parts[1])
    total = sum(c)
    r1 = R - total  # initial rating
    prefix = 0
    for i in range(n):
        rating_before = r1 + prefix
        if d[i] == 1:
            assert rating_before >= 1900, f'Contest {i+1} div1 but rating before {rating_before} < 1900'
        else:
            assert rating_before <= 1899, f'Contest {i+1} div2 but rating before {rating_before} > 1899'
        prefix += c[i]

def test_maximality(run, x):
    out = run(x).strip()
    if out == 'Infinity' or out == 'Impossible':
        return
    R = int(out)
    lines = x.strip().split('\n')
    n = int(lines[0])
    c = []
    d = []
    for line in lines[1:]:
        parts = list(map(int, line.split()))
        c.append(parts[0])
        d.append(parts[1])
    total = sum(c)
    r1 = R - total
    # check that r1+1 violates at least one constraint
    prefix = 0
    ok = True
    for i in range(n):
        rating_before = r1 + 1 + prefix
        if d[i] == 1:
            if rating_before < 1900:
                ok = False
                break
        else:
            if rating_before > 1899:
                ok = False
                break
        prefix += c[i]
    assert not ok, f'Increasing initial rating by 1 still satisfies all constraints'

def test_append_div2_non_increasing(run, x):
    lines = x.strip().split('\n')
    n = int(lines[0])
    modified = f'{n+1}\n' + '\n'.join(lines[1:] + ['0 2'])
    out1 = run(x).strip()
    out2 = run(modified).strip()
    def map_out(s):
        if s == 'Infinity':
            return 10**9
        if s == 'Impossible':
            return -10**9
        return int(s)
    m1 = map_out(out1)
    m2 = map_out(out2)
    assert m2 <= m1, f'Appending div2 contest increased mapped output: {m1} -> {m2}'

def test_append_div1_non_increasing(run, x):
    lines = x.strip().split('\n')
    n = int(lines[0])
    modified = f'{n+1}\n' + '\n'.join(lines[1:] + ['0 1'])
    out1 = run(x).strip()
    out2 = run(modified).strip()
    def map_out(s):
        if s == 'Infinity':
            return 10**9
        if s == 'Impossible':
            return -10**9
        return int(s)
    m1 = map_out(out1)
    m2 = map_out(out2)
    assert m2 <= m1, f'Appending div1 contest increased mapped output: {m1} -> {m2}'

def test_all_zero_changes(run, x):
    lines = x.strip().split('\n')
    n = int(lines[0])
    c = []
    d = []
    for line in lines[1:]:
        parts = list(map(int, line.split()))
        c.append(parts[0])
        d.append(parts[1])
    if all(ci == 0 for ci in c):
        out = run(x).strip()
        has1 = any(di == 1 for di in d)
        has2 = any(di == 2 for di in d)
        if has1 and has2:
            assert out == 'Impossible', f'All zero changes, mixed divisions -> Impossible, got {out}'
        elif has1:
            assert out == 'Infinity', f'All zero changes, all div1 -> Infinity, got {out}'
        else:  # all div2
            assert out == '1899', f'All zero changes, all div2 -> 1899, got {out}'

def test_single_contest(run, x):
    lines = x.strip().split('\n')
    n = int(lines[0])
    if n != 1:
        return
    c, d = map(int, lines[1].split())
    out = run(x).strip()
    if d == 1:
        assert out == 'Infinity', f'Single contest div1 -> Infinity, got {out}'
    else:
        expected = str(1899 + c)
        assert out == expected, f'Single contest div2 -> {expected}, got {out}'

def test_consistency_feasibility(run, x):
    out = run(x).strip()
    if out == 'Infinity' or out == 'Impossible':
        return
    lines = x.strip().split('\n')
    n = int(lines[0])
    c = []
    d = []
    for line in lines[1:]:
        parts = list(map(int, line.split()))
        c.append(parts[0])
        d.append(parts[1])
    prefix = 0
    L = -10**18
    U = 10**18
    for i in range(n):
        if d[i] == 1:
            lb = 1900 - prefix
            if lb > L:
                L = lb
        else:
            ub = 1899 - prefix
            if ub < U:
                U = ub
        prefix += c[i]
    assert L <= U, f'Integer output {out} but infeasible bounds L={L}, U={U}'

