def test_check_day_capacity(run, x):
    lines = x.strip().split('\n')
    n_d = list(map(int, lines[0].split()))
    n, d = n_d[0], n_d[1]
    a = list(map(int, lines[1].split()))
    pref = 0
    min_cap = d  # minimal d - pref[j] for j <= i
    for i, v in enumerate(a):
        pref += v
        if v == 0:
            low = max(0, -pref)
            if low > min_cap:
                out = run(x).strip()
                if out != '-1':
                    raise AssertionError('Required low > capacity on check day but output not -1')
        # update min_cap for future days
        if d - pref < min_cap:
            min_cap = d - pref


def test_prefix_monotonicity(run, x):
    lines = x.strip().split('\n')
    n_d = list(map(int, lines[0].split()))
    n, d = n_d[0], n_d[1]
    if n <= 1:
        return  # no prefix to compare
    prefix_lines = f'{n-1} {d}\n' + ' '.join(map(str, list(map(int, lines[1].split()))[:-1]))
    out_full = run(x).strip()
    out_prefix = run(prefix_lines).strip()
    if out_prefix == '-1':
        if out_full != '-1':
            raise AssertionError('Prefix output -1 but full output is not -1')
