        # both are non‑negative integers
        val_full = int(out_full)
        val_prefix = int(out_prefix)
        if val_full < val_prefix:
            raise AssertionError('Full output integer smaller than prefix output')


def test_increase_d(run, x):
    lines = x.strip().split('\n')
    n_d = list(map(int, lines[0].split()))
    n, d = n_d[0], n_d[1]
    a = list(map(int, lines[1].split()))
    new_input = f'{n} {d+1}\n' + ' '.join(map(str, a))
