    if out_orig != '-1':
        if out_new == '-1':
            raise AssertionError('Original not -1, but increased d gives -1')
        val_orig = int(out_orig)
        val_new = int(out_new)
        if val_new > val_orig:
            raise AssertionError('Increased d yields larger deposit count')
    else:
        if out_new != '-1':
            raise AssertionError('Original -1, but increased d gives not -1')


