    lines = x.strip().split('\n')
    n_d = list(map(int, lines[0].split()))
    n, d = n_d[0], n_d[1]
    a = list(map(int, lines[1].split()))
    if any(v == 0 for v in a):
        return  # not applicable
    pref = 0
    max_pref = -10**18
    for v in a:
        pref += v
        if pref > max_pref:
            max_pref = pref
    out = run(x).strip()
    if max_pref > d:
        if out != '-1':
            raise AssertionError('No zeros, max pref > d, but output not -1')
    else:
        if out != '0':
            raise AssertionError('No zeros, max pref ≤ d, but output not 0')


