    if out == '-1':
        return
    val = int(out)
    lines = x.strip().split('\n')
    a = list(map(int, lines[1].split()))
    zero_count = sum(1 for v in a if v == 0)
    if val > zero_count:
        raise AssertionError('Deposit count exceeds number of check days')


