    out = run(x)
    # Must be exactly one line, optional surrounding whitespace
    lines = out.strip().split('\n')
    if len(lines) != 1:
        raise AssertionError('Output has more than one line')
    line = lines[0].strip()
    # Must be a single integer
    try:
        int(line)
    except ValueError:
        raise AssertionError('Output line is not an integer')


