    },
    {
      "name": "test_zero_by_condition",
      "source": "def test_zero_by_condition(run, x):
    X_str, Y_str = x.strip().split()
    X, Y = int(X_str), int(Y_str)
    if (2*Y - X) % 3 != 0 or (2*X - Y) % 3 != 0:
