    },
    {
      "name": "test_negative_moves_zero",
      "source": "def test_negative_moves_zero(run, x):
    X_str, Y_str = x.strip().split()
    X, Y = int(X_str), int(Y_str)
    if (2*Y - X) % 3 == 0 and (2*X - Y) % 3 == 0:
        a = (2*Y - X) // 3
        b = (2*X - Y) // 3
        if a < 0 or b < 0:
            out = run(x).strip()
            assert out == '0', 'negative move counts mean unreachable'"
    },
    {
      "name": "test_single_move_type",
      "source": "def test_single_move_type(run, x):
    X_str, Y_str = x.strip().split()
    X, Y = int(X_str), int(Y_str)
    if (2*Y - X) % 3 == 0 and (2*X - Y) % 3 == 0:
        a = (2*Y - X) // 3
        b = (2*X - Y) // 3
        if a >= 0 and b >= 0 and (a == 0 or b == 0):
            out = run(x).strip()
            assert out == '1', 'only one move type possible, exactly one way'"
    },
    {
      "name": "test_symmetry",
      "source": "def test_symmetry(run, x):
    X_str, Y_str = x.strip().split()
    X, Y = int(X_str), int(Y_str)
    # swap coordinates
    swapped_input = f'{Y} {X}\n'
    out1 = run(x).strip()
    out2 = run(swapped_input).strip()
    assert out1 == out2, 'swapping coordinates must give same count'"
    },
    {
      "name": "test_recurrence",
      "source": "def test_recurrence(run, x):
    X_str, Y_str = x.strip().split()
    X, Y = int(X_str), int(Y_str)
    # check reachable first
    if (2*Y - X) % 3 == 0 and (2*X - Y) % 3 == 0:
        a = (2*Y - X) // 3
        b = (2*X - Y) // 3
        if a >= 0 and b >= 0:
            # only test if predecessor points are within the given input constraints? 
            # The specification says 1 ≤ X, Y ≤ 1e6, but the recurrence is defined for all points.
            # We restrict to points where both predecessors are also within the positive range
            # to stay within valid inputs.
            if X-1 >= 1 and Y-2 >= 1:
                prev1 = f'{X-1} {Y-2}\n'
                out_prev1 = int(run(prev1).strip())
            else:
                out_prev1 = 0
            if X-2 >= 1 and Y-1 >= 1:
                prev2 = f'{X-2} {Y-1}\n'
                out_prev2 = int(run(prev2).strip())
            else:
                out_prev2 = 0
            MOD = 10**9 + 7
            expected = (out_prev1 + out_prev2) % MOD
            out_curr = int(run(x).strip())
            assert out_curr == expected, f'recurrence relation failed: f(X,Y) = f(X-1,Y-2) + f(X-2,Y-1)'"
    },
    {
      "name": "test_small_enumerate",
      "source": "def test_small_enumerate(run, x):
    X_str, Y_str = x.strip().split()
    X, Y = int(X_str), int(Y_str)
    if X + Y <= 30:
        # DP over grid up to X+Y
        max_coord = max(X, Y) + 3
        dp = [[0]*(max_coord+1) for _ in range(max_coord+1)]
        MOD = 10**9+7
        dp[0][0] = 1
        for i in range(max_coord+1):
            for j in range(max_coord+1):
                if i+1 <= max_coord and j+2 <= max_coord:
                    dp[i+1][j+2] = (dp[i+1][j+2] + dp[i][j]) % MOD
                if i+2 <= max_coord and j+1 <= max_coord:
                    dp[i+2][j+1] = (dp[i+2][j+1] + dp[i][j]) % MOD
        expected = dp[X][Y] % MOD
        out = int(run(x).strip())
        assert out == expected, f'DP enumeration disagrees for small sum'"
    },
    {
      "name": "test_parity_for_symmetric",
      "source": "def test_parity_for_symmetric(run, x):
    X_str, Y_str = x.strip().split()
    X, Y = int(X_str), int(Y_str)
