        a = (2*Y - X) // 3
        b = (2*X - Y) // 3
        if a >= 0 and b >= 0 and a == b and a >= 1:
            out = int(run(x).strip())
            assert out % 2 == 0, f'when a=b≥1, C(2a,a) is even, so answer must be even'"
    },
    {
      "name": "test_binomial_small",
      "source": "def test_binomial_small(run, x):
    X_str, Y_str = x.strip().split()
    X, Y = int(X_str), int(Y_str)
    if (2*Y - X) % 3 == 0 and (2*X - Y) % 3 == 0:
        a = (2*Y - X) // 3
        b = (2*X - Y) // 3
        if a >= 0 and b >= 0 and a + b <= 30:
            import math
            MOD = 10**9 + 7
            expected = math.comb(a + b, a) % MOD
            out = int(run(x).strip())
            assert out == expected, f'binomial formula disagrees for small a+b'"
    },
    {
      "name": "test_invariant_nonzero_if_reachable",
      "source": "def test_invariant_nonzero_if_reachable(run, x):
    X_str, Y_str = x.strip().split()
    X, Y = int(X_str), int(Y_str)
