    },
    {
      "name": "test_metamorphic_add_zero_word",
      "intent": "Appending a word with zero capital letters (e.g., 'a') must not change the volume, because the maximum of a set and an element not greater than the maximum remains the same. Construct the new input and verify output unchanged."
    },
    {
      "name": "test_metamorphic_duplicate_text",
      "intent": "Duplicating the entire text (repeating the sequence of words) must not change the volume, as the set of word volumes is unchanged. Construct the new input and assert output unchanged."
    },
    {
      "name": "test_metamorphic_all_lowercase",
      "intent": "If all letters in the text are converted to lowercase, the volume must become 0 because there are no capital letters. Construct the modified input and assert output is 0."
    },
    {
      "name": "test_metamorphic_all_uppercase",
      "intent": "If all letters in the text are converted to uppercase, every word's volume equals its length, so the volume must equal the length of the longest word. Construct the modified input, compute max word length, and assert output equals that."
