      "name": "test_lower_bound",
      "source": "def test_lower_bound(run, x):
    out = run(x)
    if not out.startswith('Finite'):
        return
    lines = x.strip().split('\n')
    n = int(lines[0])
    a = list(map(int, lines[1].split()))
    # minimum per pair (same as maximum from specification)
    min_per_pair = { (1,2):3, (2,1):3, (3,2):3, (1,3):4, (3,1):4 }
    # The total distinct points must be at least the maximum over all pairs? Wait: specification says each pair touches in at least those points, but points may coincide across different pairs.
    # The plan says "the total distinct set must include at least that many points" – ambiguous. We'll implement as sum of minima, which is a safe lower bound (could be weaker).
    total = 0
    for i in range(n-1):
        pair = (a[i], a[i+1])
        total += min_per_pair.get(pair, 0)
    val = int(out.rstrip('\n').split('\n')[1])
    assert val >= total, f"Finite count {val} below sum of minimum per pair {total}""
    },
    {
      "name": "test_int32_range",
      "source": "def test_int32_range(run, x):
    out = run(x)
    if out.startswith('Finite'):
        lines = out.rstrip('\n').split('\n')
        val = int(lines[1])
        assert -2**31 <= val <= 2**31 - 1, "Finite count out of 32‑bit signed integer range""
    },
    {
      "name": "test_no_extra_whitespace",
      "source": "def test_no_extra_whitespace(run, x):
    out = run(x)
    # No leading/trailing whitespace overall
    assert out == out.strip('\n') + '\n', "Extra whitespace before or after output"
    lines = out.rstrip('\n').split('\n')
    for line in lines:
        assert line == line.strip(), f"Line contains leading/trailing spaces: '{line}'"
    # Exactly one or two lines
    assert len(lines) in (1, 2), "Must have 1 or 2 lines"
    if len(lines) == 1:
        assert lines[0] == 'Infinite', "Single line must be 'Infinite'"
    else:
        assert lines[0] == 'Finite', "Two lines: first must be 'Finite'""
    }
  ]
}

{
