  "plan": [
    {
      "name": "test_output_range",
      "intent": "The output must be a string that parses to an integer between 0 and 1000000006 inclusive, since the result is taken modulo 1000000007. A violation is any output outside this range or non-numeric."
    },
    {
      "name": "test_permute_nodes",
      "intent": "Applying a fixed permutation to node indices (e.g., rotating labels i → i+1 mod n) must not change the answer, as the problem depends only on tree structure and values, not labeling. Construct the permuted input and assert output equality."
    },
    {
      "name": "test_swap_same_value",
      "intent": "If two nodes have the same value, swapping their values must not affect the count. Pick the first two such nodes (if any), swap their values in the input, and assert the output remains the same."
    },
    {
      "name": "test_constant_values",
      "intent": "Setting all values to the same constant within [1,2000] must yield the same answer, because max‑min = 0 ≤ d for any connected subset. Construct two inputs with all values set to 1 and to 2, and assert they produce equal outputs (skip if original already has all values equal)."
    },
    {
      "name": "test_monotonic_d",
      "intent": "For trees with at most 10 nodes (so the count fits in a normal integer), increasing d cannot decrease the number of valid sets. If n ≤ 10 and d < 2000, create an input with d+1 and assert the new output is ≥ the original."
    },
    {
      "name": "test_lower_bound",
