  "plan": [
    {
      "name": "test_1_certificate",
      "intent": "Verify that the returned integer x satisfies the equation (x // k) * (x % k) == n. A violation occurs if the product does not equal n."
    },
    {
      "name": "test_2_positive",
      "intent": "Verify that the output is a positive integer. A violation occurs if x is not a positive integer."
    },
    {
      "name": "test_3_mod_range",
      "intent": "Verify that 1 <= x % k <= k-1. A violation occurs if the remainder is 0 or not less than k."
    },
    {
      "name": "test_4_quotient_positive",
      "intent": "Verify that x // k >= 1. A violation occurs if the quotient is zero."
    },
    {
      "name": "test_5_lower_bound",
      "intent": "Verify that x >= n + k. A violation occurs if x is smaller than n + k."
    },
    {
      "name": "test_6_upper_bound",
      "intent": "Verify that x <= n * k + (k - 1). A violation occurs if x exceeds this bound."
    },
    {
      "name": "test_7_divisor",
      "intent": "Verify that n is divisible by (x % k), i.e., n % (x % k) == 0. A violation occurs if the remainder does not divide n."
    },
    {
      "name": "test_8_form",
      "intent": "Verify that there exists an integer i in [1, k-1] such that n % i == 0 and x == (n // i) * k + i. A violation occurs if no such i exists."
    },
    {
      "name": "test_9_minimality",
      "intent": "Verify that for every i in [1, k-1] with n % i == 0, x <= (n // i) * k + i. A violation occurs if some candidate is smaller than x."
    },
    {
      "name": "test_10_metamorphic",
      "intent": "Let r = x % k. If n + r <= 10^6, run the program on input (n + r, k) and verify that its output is at most x + k. If n > r, run on (n - r, k) and verify that its output is at most x - k. Otherwise, pass. A violation occurs when the applicable inequality fails."
    }
  ]
}

{
