    },
    {
      "name": "test_horizontal_reflection",
      "intent": "Given input (n,m,x,y,vx,vy), construct reflected input (n,m,n-x,y,-vx,vy). Run the solution on both. If the original output is a pocket (px,py), the reflected output must be (n-px,py). If the original output is -1, the reflected output must also be -1."
    },
    {
      "name": "test_vertical_reflection",
