    }
  ]
}

{
  "rationale": "I implemented the 10 tests as per the plan. Each test is a property derived from the specification. Where the plan was vague, I interpreted strictly based on the spec: e.g., test_output_format checks exactly -1 or two integers matching pocket coordinates; test_bounds enforces coordinates within [0,n] and [0,m]; the reflection tests rely on physical symmetry (spec implies collisions obey reflection). The GCD and parity conditions come from necessary conditions for the ball to hit a pocket (derivable from the spec). The last test ensures consistency for -1 outputs. All tests are property-based and do not compute correct answers. If any test fails, it indicates a wrong answer. I'd drop test_output_format first, as it's the weakest (only checks format).",
  "tests": [
    {
      "name": "test_output_format",
      "source": "def test_output_format(run, x):
    out = run(x).strip()
    if out == '-1':
        return
    parts = out.split()
    assert len(parts) == 2, 'Output must be two integers or -1'
    a, b = map(int, parts)
    n, m = map(int, x.split()[:2])
    assert (a == 0 or a == n) and (b == 0 or b == m), 'Pocket coordinates must be (0,0), (0,m), (n,0), or (n,m)'"
    },
    {
      "name": "test_bounds",
      "source": "def test_bounds(run, x):
    out = run(x).strip()
    if out == '-1':
        return
    a, b = map(int, out.split())
    n, m = map(int, x.split()[:2])
    assert 0 <= a <= n and 0 <= b <= m, 'Pocket coordinates out of bounds'"
    },
    {
      "name": "test_horizontal_reflection",
      "source": "def test_horizontal_reflection(run, x):
    out1 = run(x).strip()
    n, m, xc, yc, vx, vy = map(int, x.split())
    # Reflect horizontally: x -> n - x, vx -> -vx
    reflected = f'{n} {m} {n - xc} {yc} {-vx} {vy}\n'
    out2 = run(reflected).strip()
    if out1 == '-1':
        assert out2 == '-1', 'Both must be -1 under horizontal reflection'
    else:
        px, py = map(int, out1.split())
        # Expected reflected pocket
        expected_px = n - px
        expected_py = py
        assert out2 != '-1', 'Reflected output should be pocket'
        px2, py2 = map(int, out2.split())
        assert (px2, py2) == (expected_px, expected_py), 'Pocket mismatch under horizontal reflection'"
    },
    {
      "name": "test_vertical_reflection",
      "source": "def test_vertical_reflection(run, x):
    out1 = run(x).strip()
    n, m, xc, yc, vx, vy = map(int, x.split())
    # Reflect vertically: y -> m - y, vy -> -vy
    reflected = f'{n} {m} {xc} {m - yc} {vx} {-vy}\n'
    out2 = run(reflected).strip()
    if out1 == '-1':
        assert out2 == '-1', 'Both must be -1 under vertical reflection'
    else:
        px, py = map(int, out1.split())
        expected_px = px
        expected_py = m - py
        assert out2 != '-1', 'Reflected output should be pocket'
        px2, py2 = map(int, out2.split())
        assert (px2, py2) == (expected_px, expected_py), 'Pocket mismatch under vertical reflection'"
    },
    {
      "name": "test_swap_symmetry",
      "source": "def test_swap_symmetry(run, x):
    out1 = run(x).strip()
    n, m, xc, yc, vx, vy = map(int, x.split())
    # Swap n<->m, x<->y, vx<->vy
    swapped = f'{m} {n} {yc} {xc} {vy} {vx}\n'
    out2 = run(swapped).strip()
    if out1 == '-1':
        assert out2 == '-1', 'Both must be -1 under swap'
    else:
        px, py = map(int, out1.split())
        expected_px, expected_py = py, px
        assert out2 != '-1', 'Swapped output should be pocket'
        px2, py2 = map(int, out2.split())
        assert (px2, py2) == (expected_px, expected_py), 'Pocket mismatch under swap'"
    },
    {
      "name": "test_vx_zero",
      "source": "def test_vx_zero(run, x):
    n, m, xc, yc, vx, vy = map(int, x.split())
    if vx != 0 or vy == 0:
        return
    out = run(x).strip()
    if xc != 0 and xc != n:
        assert out == '-1', 'Ball never falls if x not at boundary and vx==0'
    else:
        if vy < 0:
            assert out == f'{xc} 0', f'Expected ({xc},0) for vx=0, vy<0, x on boundary'
        else:
            assert out == f'{xc} {m}', f'Expected ({xc},{m}) for vx=0, vy>0, x on boundary'"
    },
    {
      "name": "test_vy_zero",
      "source": "def test_vy_zero(run, x):
    n, m, xc, yc, vx, vy = map(int, x.split())
    if vy != 0 or vx == 0:
        return
    out = run(x).strip()
    if yc != 0 and yc != m:
        assert out == '-1', 'Ball never falls if y not at boundary and vy==0'
    else:
        if vx < 0:
            assert out == f'0 {yc}', f'Expected (0,{yc}) for vy=0, vx<0, y on boundary'
        else:
            assert out == f'{n} {yc}', f'Expected ({n},{yc}) for vy=0, vx>0, y on boundary'"
    },
    {
      "name": "test_gcd_condition",
      "source": "def test_gcd_condition(run, x):
    n, m, xc, yc, vx, vy = map(int, x.split())
    if vx == 0 or vy == 0:
        return
    out = run(x).strip()
    if out == '-1':
        return
    # Adjust vx, vy as per plan
    vx_adj = vx
    vy_adj = vy
    if vx == -1 and xc == 0:
        vx_adj = 1
    if vx == 1 and xc == n:
        vx_adj = -1
    if vy == -1 and yc == 0:
        vy_adj = 1
    if vy == 1 and yc == m:
        vy_adj = -1
    from math import gcd
    g = gcd(n, m)
    left = (-vx_adj * xc) % g
    right = (-vy_adj * yc) % g
    assert left == right, 'GCD condition failed for non-zero velocities'"
    },
    {
      "name": "test_parity_condition",
      "source": "def test_parity_condition(run, x):
    n, m, xc, yc, vx, vy = map(int, x.split())
    if vx == 0 or vy == 0:
        return
    out = run(x).strip()
    if out == '-1':
        return
    px, py = map(int, out.split())
    parity_a = 1 if px == n else 0
    parity_b = 1 if py == m else 0
    left = (parity_a * n + xc) % 2
    right = (parity_b * m + yc) % 2
    assert left == right, 'Parity condition failed'"
    },
    {
      "name": "test_minus_one_consistency",
      "source": "def test_minus_one_consistency(run, x):
    n, m, xc, yc, vx, vy = map(int, x.split())
    out = run(x).strip()
    if out != '-1':
        return
    # Adjust vx, vy as per plan
    vx_adj = vx
    vy_adj = vy
    if vx == -1 and xc == 0:
        vx_adj = 1
    if vx == 1 and xc == n:
        vx_adj = -1
    if vy == -1 and yc == 0:
        vy_adj = 1
    if vy == 1 and yc == m:
        vy_adj = -1
    from math import gcd
    if vx_adj == 0 and (xc != 0 and xc != n):
        return
    if vy_adj == 0 and (yc != 0 and yc != m):
        return
    if vx_adj != 0 and vy_adj != 0:
        g = gcd(n, m)
        left = (-vx_adj * xc) % g
        right = (-vy_adj * yc) % g
        assert left != right, 'Output -1 but GCD condition would allow a pocket'"
    }
  ]
}

{
