def test_certificate(run, x):
    import sys
    lines = x.strip().split('\n')
    first = list(map(int, lines[0].split()))
    n, p = first[0], first[1]
    a = list(map(int, lines[1].split()))
    max_a = max(a) if a else 0
    sorted_a = sorted(a)
    # compute good x set
    good = []
    for x0 in range(1, max_a):  # x only up to max(a)-1
        prod = 1
        for i in range(1, n+1):
            cnt = sum(1 for val in sorted_a if val <= x0 + i - 1)
            term = cnt - (i-1)
            if term <= 0:
                prod = 0
                break
            prod = (prod * (term % p)) % p
        if prod % p != 0:
            good.append(x0)
    # parse output
    out = run(x).strip().split('\n')
    if len(out) == 0:
        sys.stderr.write('empty output\n')
        assert False
    k_line = out[0].strip()
    if not k_line:
        sys.stderr.write('first line empty\n')
        assert False
    k = int(k_line)
    if k == 0:
        if len(out) == 1 or (len(out) == 2 and out[1].strip() == ''):
            # second line may be empty, or missing entirely (spec says print 0 then newline? examples show blank second line)
            # accept either
            output_x = []
        else:
            output_x = list(map(int, out[1].split()))
            if output_x:
                sys.stderr.write('non-empty second line when k=0\n')
                assert False
    else:
        if len(out) < 2:
            sys.stderr.write('missing second line\n')
            assert False
        output_x = list(map(int, out[1].split()))
    if set(output_x) != set(good):
        sys.stderr.write('good x mismatch\n')
        assert False
    # also check order: already handled by later test_sorted, but we can also enforce that order matches good (ascending)
    if output_x != good:
        sys.stderr.write('order mismatch\n')
        assert False

