    k_line = out[0].strip()
    if not k_line:
        assert False, 'first line empty'
    k = int(k_line)
    if k == 0:
        # second line may be empty or missing
        output_x = []
    else:
        if len(out) < 2:
            assert False, 'missing second line'
        output_x = list(map(int, out[1].split()))
    # check each x in [1, max_a-1]
    for val in output_x:
        if val < 1 or val > max_a - 1:
            assert False, f'x={val} outside [1, {max_a-1}]'
    # check count does not exceed max_a-1 (since only that many possible x)
    if k > max_a - 1:
