def test_format(run, x):
    out_lines = run(x).strip().split('\n')
    # must have exactly two lines (even if second line empty)
    if len(out_lines) != 2:
        assert False, f'expected 2 lines, got {len(out_lines)}'
    first = out_lines[0].strip()
