        # but k cannot be negative
        assert False, 'first line not an integer'
    k = int(first)
    if k < 0:
        assert False, 'k negative'
    # second line: if k==0, must be empty (or possibly spaces? spec says second line with k integers; examples show blank line)
    if k == 0:
        if second != '':
