def test_range_upper(run, x):
    lines = x.strip().split('\n')
    a = list(map(int, lines[1].split()))
    max_a = max(a) if a else 0
    out = run(x).strip().split('\n')
    if len(out) == 0:
        assert False, 'empty output'
    k_line = out[0].strip()
    if not k_line:
        assert False, 'first line empty'
    k = int(k_line)
    if k == 0:
        return
